insert into documentos_oficiais (id, titulo, categoria, fonte, versao, ativo, data_atualizacao) values
insert into documentos_chunks (id, documento_id, ordem, conteudo) values
  ('44064cfd-3b4d-4152-a3cf-435373eb3d79', 'a00debc3-9655-5859-b11c-6b7f1d389d09', 1, 'Acesso a Obras Raras: Você sabia que, na FECAP, é possível ter acesso a obras raras? Demais, não é?! Para isso, basta verificar a disponibilidade do livro no Catálogo On-line da Biblioteca e agendar o acesso ao material físico. Porém, não é permitido levar a obra para casa, fazer fotocópias, manusear o material sem luvas e máscara, tirar fotos com flash ou comer e beber enquanto estiver folheando o livro. Aproveite a leitura e desfrute da oportunidade de ter contato com obras tão especiais!'),
  ('af8e3838-062c-4826-aee2-9759cd6943f3', 'a00debc3-9655-5859-b11c-6b7f1d389d09', 2, 'Acesso a Obras Raras - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('63d6ef6d-aa4d-4415-811e-459f51b5847b', 'a00debc3-9655-5859-b11c-6b7f1d389d09', 3, 'Acesso a Obras Raras - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca – 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('d240e58f-7b0a-4d6d-9d1d-d92e7ebf1766', '78575b3e-33e7-5fdd-bf85-0aa13bb7ff6c', 1, 'Atestado de conclusão: Precisando de um documento que ateste a sua formação, mas ainda não colou grau? Nós podemos te ajudar! Enquanto espera seu certificado de conclusão, você pode emitir o seu atestado de conclusão de maneira rápida e fácil pelo seu Portal do Aluno > Menu > Relatórios > Atestado de Conclusão > Emitir Relatório. Em caso de dúvidas, estamos à disposição para te auxiliar!'),
  ('9320a98a-94d3-4a0c-a1b3-637415b87fdb', '78575b3e-33e7-5fdd-bf85-0aa13bb7ff6c', 2, 'Atestado de conclusão - Condições: 1) O aluno precisa estar com situação de matrícula “Formado”; 2) A solicitação deve ocorrer antes da data de colação de grau'),
  ('473b7c7b-1482-45bc-893d-e864f924c044', '78575b3e-33e7-5fdd-bf85-0aa13bb7ff6c', 3, 'Atestado de conclusão - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('3b2049b5-83f6-487c-a7d1-e1fc93dbd7de', '886328bb-7da1-5bf5-9625-9eb6a761e85c', 1, 'Bibliotroca – Feira de Troca de Livros: Você já conhece a Bibliotroca? Esse é um evento incrível que permite dar um novo destino aos livros que estão parados em sua casa, além de proporcionar momentos de troca de histórias e experiências com amigos e professores. A Feira de troca de livros acontece anualmente no pátio da FECAP – Campus Liberdade. Participar é simples: basta trazer obras em bom estado e efetuar a troca de um livro por outro. Não perca esta chance! Esperamos por você para celebrar o amor pela leitura e pelo compartilhamento de conhecimento.'),
  ('1e008510-6588-4ed5-ac4d-4649b7bf7b80', '886328bb-7da1-5bf5-9625-9eb6a761e85c', 2, 'Bibliotroca – Feira de Troca de Livros - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('55a5c9a3-5163-48d7-9f78-697f68fd48ea', '886328bb-7da1-5bf5-9625-9eb6a761e85c', 3, 'Bibliotroca – Feira de Troca de Livros - Atendimento: Setor responsável: Biblioteca. Local: Pátio da FECAP, Campus Liberdade. Horário de atendimento: Das 09h às 12h e das 17h às 21h, conforme calendário. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('5eb9c938-ee64-4b0b-8b56-92c15d419fe0', '8e5fb4dd-216f-5924-a089-268546553d3d', 1, 'Bolsa Ex-Aluno: Se você é um ex-aluno FECAP, prepare-se para uma notícia que vai aquecer o seu coração Alvarista: temos uma bolsa exclusiva para você! São 25% de desconto nos cursos de Graduação, Pós-Graduação e Mestrado. É a nossa maneira de agradecer pela sua dedicação e carinho pela nossa instituição. Para solicitar a sua bolsa, basta acessar o Portal do Aluno > Menu > Secretaria/Requerimento > Bolsa Ex-Aluno.'),
  ('51354b2c-f8ee-445a-ab15-c0c3ef2a104b', '8e5fb4dd-216f-5924-a089-268546553d3d', 2, 'Bolsa Ex-Aluno - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('8c97079b-9346-4d02-9f5d-f7c682302612', '8e5fb4dd-216f-5924-a089-268546553d3d', 3, 'Bolsa Ex-Aluno - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('7a3f9e1b-164a-460e-8098-3be3e64ff8de', '4e39200d-e7ad-5940-8e1d-1320c1dec49c', 1, 'Cadastro de Alumni Alvarista (Ex-aluno): Uma vez Alvarista, sempre Alvarista! Como ex-aluno da FECAP, você tem direito a usufruir dos programas, recursos e serviços da Instituição. Incrível, não é mesmo? Se você deseja continuar aproveitando as excelentes leituras da Biblioteca, basta solicitar seu cadastro de Alumni Alvarista e preencher o formulário presente no site. O cadastro é válido por 6 meses e permite que você retire até 2 materiais, com empréstimo de 7 dias cada. Será um prazer te receber novamente e continuar fortalecendo essa conexão entre você e a FECAP.'),
  ('facad041-42be-4fd8-8582-7dc493936668', '4e39200d-e7ad-5940-8e1d-1320c1dec49c', 2, 'Cadastro de Alumni Alvarista (Ex-aluno) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('feb6e493-ca3e-41c6-89ee-686f9a998de1', '4e39200d-e7ad-5940-8e1d-1320c1dec49c', 3, 'Cadastro de Alumni Alvarista (Ex-aluno) - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca – 6º andar Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h30 | Sábados, das 8h às 16h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('42816bd6-30db-4def-a9a3-03653a85108d', '3d43e14b-4be9-5359-b254-6868c46467b2', 1, 'Diploma: Chegou na etapa final dos seus estudos. Parabéns, Alvarista! Você está pronto(a) para encarar os desafios dessa nova jornada. Em breve, você receberá um e-mail e SMS da Secretaria com o acesso ao seu Diploma. Fique ligado(a) sobre as condições para receber o Diploma: é necessário o cumprimento de todos os requisitos acadêmicos; todos os documentos pessoais e acadêmicos devem ter sido entregues; o termo da colação de grau deve estar assinado. Em caso de dúvidas sobre as condições e procedimentos de recebimento, entre em contato por meio dos nossos canais de atendimento. Será um prazer te ajudar!'),
  ('9d496982-b6ae-429f-893c-b4f45e7f29b2', '3d43e14b-4be9-5359-b254-6868c46467b2', 2, 'Diploma - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('d6664ce0-b7fc-4141-9053-49fa2c79fd09', '3d43e14b-4be9-5359-b254-6868c46467b2', 3, 'Diploma - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('e83bba6e-7e35-49c9-9186-9ab33acb2715', '3fef25cd-1d82-5f6f-8337-fc8dd19e989b', 1, 'Diploma – 2ª via: Perdeu o seu diploma? Saiba que podemos disponibilizar uma nova versão digital para você! Realize a solicitação e pague a taxa por meio do seu portal Requerimento/ Diploma 2ª via. Se preferir, pode nos procurar em um dos nossos canais de atendimento. Estamos prontos para te ajudar!'),
  ('edd6a306-f7a7-4903-84c1-46cbe5b165a6', '3fef25cd-1d82-5f6f-8337-fc8dd19e989b', 2, 'Diploma – 2ª via - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('4187d521-22f8-4d23-a84f-0daf8580c544', '3fef25cd-1d82-5f6f-8337-fc8dd19e989b', 3, 'Diploma – 2ª via - Atendimento: Setor responsável: Secretaria Acadêmica. Local: ASA – Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado.'),
  ('7d95e034-d6a9-44e7-9b13-365dfb195848', '99e9f546-cc49-5e19-84a5-b8c85455c4a7', 1, 'Agenda dos Plantões de Dúvidas – Monitoria: Participe dos Plantões de Monitoria e tenha todas as suas dúvidas esclarecidas! Durante esses plantões, que este semestre iniciam no 16/03/2026, estudantes dos cursos de Graduação oferecem suporte, respondendo a todas as perguntas que possam surgir. O melhor de tudo é que não é necessário se inscrever, basta comparecer nos dias e horários definidos. Não perca essa oportunidade de aprimorar seu aprendizado e alcançar seus objetivos acadêmicos! Confira aqui as disciplinas e a agenda dos plantões ou acesse o Moodle > Programa de Monitoria. Qualquer dúvida, entre em contato por meio dos nossos canais de atendimento.'),
  ('c9701dd7-63ee-4f13-80d5-85a5d274ad40', '99e9f546-cc49-5e19-84a5-b8c85455c4a7', 2, 'Agenda dos Plantões de Dúvidas – Monitoria - Condições: A participação nos plantões é livre, ou seja, não é necessária qualquer inscrição, o/a discente pode frequentá-los nos dias e horários que preferir e não é limitado o número de frequência semanal'),
  ('f2cd25b3-bc4b-4fbc-8ec7-f72e7f05c724', '99e9f546-cc49-5e19-84a5-b8c85455c4a7', 3, 'Agenda dos Plantões de Dúvidas – Monitoria - Atendimento: Setor responsável: Pró-Reitoria de Extensão e Desenvolvimento. Local: Diversos (conferir a programação). Horário de atendimento: Segunda a Sábado (Horários diversos, confira a programação). Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('aea1cfef-ceac-43dc-902b-0cf5750401de', '5b337695-b47b-5367-8f89-559b78a51122', 1, 'Coach Acadêmico: Crie hábitos benéficos de estudos para a realização dos seus sonhos e do seu futuro! Com o coach acadêmico, você será um personagem ativo na construção da sua carreira. Para fazer seu agendamento, basta entrar no Portal do Aluno > URLs externa > “FECAP + Desenvolvimento” e em reservas, selecione a agenda da Profa. Maria de Lurdes.'),
  ('178a3e1e-c275-4813-967b-572d3cbdd6e9', '5b337695-b47b-5367-8f89-559b78a51122', 2, 'Coach Acadêmico - Condições: O agendamento é destinado para alunos e ex-alunos FECAP. Acesso regular ao Portal do Aluno'),
  ('56049a96-e56b-4f7d-a494-b13eab6082c1', '5b337695-b47b-5367-8f89-559b78a51122', 3, 'Coach Acadêmico - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('a9d0f081-0cd1-4a9f-bc73-ef62d76f5885', '7c41ed8b-4458-5581-b6b1-6b65ccd8131f', 1, 'Cursos Extras Curriculares: Ei! Você sabia que o Colégio FECAP oferece Cursos livres (extracurriculares) sem custo adicional ao longo do ano? No início do período letivo, é liberada a lista dos cursos ofertados através do ClasApp. Então fique de olho para se inscrever e aproveitar todos os recursos de aprendizagem que a FECAP te oferece! Obs.: fique atento(a), os cursos não podem conflitar com seus horários de aula.'),
  ('d4932cdc-2b06-4e18-bc66-86f01c02d1e6', '7c41ed8b-4458-5581-b6b1-6b65ccd8131f', 2, 'Cursos Extras Curriculares - Condições: Aluno deve aguardar a divulgação via classapp; Não pode se inscrever em cursos no mesmo horário de aula; A classificação é de acordo com a ordem de inscrição'),
  ('e1056663-00a7-4370-9f98-38840a5fa346', '7c41ed8b-4458-5581-b6b1-6b65ccd8131f', 3, 'Cursos Extras Curriculares - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: De segunda a sexta-feira, das 07h00 às 18h00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('b8ab45ce-dd69-4f52-b553-d1edcc222660', '0d768427-a87b-5d53-8bcd-adae3faa1767', 1, 'English Corner: O English Corner é um programa que oferece aulas de conversação em inglês para estudantes, funcionários e professores da FECAP, independentemente do nível de proficiência no idioma. É uma oportunidade imperdível para aqueles que desejam praticar a língua, compartilhar conhecimentos e conhecer novas pessoas, sempre conversando em inglês! Durante a dinâmica, os participantes são convidados a participar de cinco atividades de 15 minutos cada, nas quais têm a oportunidade de discutir temas variados, como experiências passadas, estratégias de aprendizagem, carreira profissional, vivências inusitadas e muito mais. Além disso, os participantes poderão aprender novos métodos de aprendizado e aprimorar suas habilidades de comunicação em inglês. Participe do English Corner e comece a construir sua confiança e fluência em inglês! Início: 20 de fevereiro.'),
  ('eeae07bc-f598-4299-ba91-55811c9eab4a', '0d768427-a87b-5d53-8bcd-adae3faa1767', 2, 'English Corner - Condições: Qualquer pessoa pode participar, independentemente do nível do idioma'),
  ('d698a2af-bddd-4bdc-9613-91c0191f2b38', '0d768427-a87b-5d53-8bcd-adae3faa1767', 3, 'English Corner - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Sala Empreendedorismo – Bloco E. Horário de atendimento: Sextas-feiras, em dois horários: das 11h30 às 12h30 e das 18h às 19h. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('9a1d5f62-d641-4921-a649-18a54dacc4a8', 'ed6eed90-9d84-5193-8082-f2693254ddb5', 1, 'Grupo de Apoio Linguístico Pedagógico e o Grupo ATENTO: Você sabia que a FECAP tem um grupo de apoio linguístico pedagógico direcionados a estudantes com dificuldades no processo de aprendizagem? Aqui, o foco é inclusão e respeito no aprendizado acessível para todos(as)! Para participar, basta entrar em contato com o Colégio e apresentar o laudo do(a) aluno(a) dentro da validade de 6 (seis) meses.'),
  ('4c7dfb23-7db3-4b5a-9859-5c0c6172b548', 'ed6eed90-9d84-5193-8082-f2693254ddb5', 2, 'Grupo de Apoio Linguístico Pedagógico e o Grupo ATENTO - Condições: Estudante precisa ter laudo (últimos 6 meses) assinado por profissional da área atestando a sua necessidade de inclusão; A família deverá passar por entrevista com a psicopedagoga do Colégio'),
  ('cdc0d851-ec17-4851-9fc1-4c9867041a9a', 'ed6eed90-9d84-5193-8082-f2693254ddb5', 3, 'Grupo de Apoio Linguístico Pedagógico e o Grupo ATENTO - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('79373058-33c3-4ae4-ba38-6c18bb58f36f', '28eca26a-6b65-5e8e-8bf4-082681427ed4', 1, 'Laboratório de Métodos Quantitativos: O laboratório é voltado a todos os alunos da FECAP e oferece suporte acadêmico gratuito, com acompanhamento de professores especializados. O objetivo é fortalecer a aprendizagem e auxiliar os estudantes no desenvolvimento das competências necessárias para as disciplinas quantitativas. Durante os plantões, os professores poderão: Tirar dúvidas e revisar conteúdos de Cálculo I, Cálculo II e Álgebra Linear; Auxiliar na resolução de exercícios e atividades das disciplinas; Oferecer apoio às atividades do Nivelamento I e II de Matemática. Segundas e terças-feiras 11h20 às 13h – Prof. Jefferson Nery Segundas-feiras 17h às 18h40 – Prof. Jefferson Nery Terças e quintas-feiras 17h às 18h40 – Prof. Aimberê Galdino Sábados 9h às 12h20 e 13h às 14h40 – Prof. Aimberê Galdino'),
  ('1ddcc7e0-70b2-45e5-963c-3d534983ac4a', '28eca26a-6b65-5e8e-8bf4-082681427ed4', 2, 'Laboratório de Métodos Quantitativos - Condições: É gratuito e todos(as) os(as) estudantes da FECAP podem participar!; Não é preciso fazer inscrição, basta aparecer nos dias e horários marcados!'),
  ('53927db8-6281-4bff-ab5b-551336f0e94d', '28eca26a-6b65-5e8e-8bf4-082681427ed4', 3, 'Laboratório de Métodos Quantitativos - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Sala 503 - Bloco A. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('93157180-ae2f-4235-ac28-df122a6f01d8', 'caab5dc9-1666-58d0-858a-f81b4dca12f1', 1, 'Laboratórios de Português e Inglês: Os Laboratórios de Português e Inglês da FECAP são aulas gratuitas destinadas a todos os membros da Comunidade Alvarista que desejam aprimorar seus conhecimentos nas duas línguas. O objetivo dos laboratórios é auxiliar os participantes a resolverem necessidades específicas de aprendizagem, por meio de exercícios orais e escritos que abrangem gramática, vocabulário e pronúncia. Durante as aulas, os alunos têm a oportunidade de trabalhar com temas relevantes e atuais, relacionados aos seus interesses pessoais e profissionais. Participe dos Laboratórios de Português e Inglês da FECAP e melhore sua comunicação nas duas línguas! Em caso de dúvidas, entre em contato conosco por meio de nossos canais de atendimento.'),
  ('fb53f063-ae8c-4640-be60-7640204927f2', 'caab5dc9-1666-58d0-858a-f81b4dca12f1', 2, 'Laboratórios de Português e Inglês - Condições: Gratuitas para toda a Comunidade Alvarista: estudantes, professores e funcionários interessados em entender melhor sobre algum assunto ou regra gramatical relacionada às duas línguas'),
  ('8a984f9e-3081-4ca5-bf18-bbcd84e74d3d', 'caab5dc9-1666-58d0-858a-f81b4dca12f1', 3, 'Laboratórios de Português e Inglês - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Sala de reuniões – 4º andar – Bloco B. Horário de atendimento: Segundas-feiras, das 11h30 às 12h30 Início: 02 de março | Sextas-feiras, das 17h00 às 18h00 Início: 06 de março. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('48bb4d52-670e-4924-8a9d-dc8b7970bef8', '8f509e27-c13c-5c1a-b824-d722166e5a5e', 1, 'Monitoria de estudos: A Monitoria de Estudos oferece apoio acadêmico aos estudantes, visando melhorar o desempenho escolar. Os(as) alunos(as) são selecionados pelo Colégio. Após o aceite, serão disponibilizados os horários na semana para realizar a monitoria. Esta é uma excelente oportunidade para reforçar os estudos e promover a colaboração entre os estudantes.'),
  ('5bb2e507-3818-48d5-bfae-640f13c13937', '8f509e27-c13c-5c1a-b824-d722166e5a5e', 2, 'Monitoria de estudos - Condições: Ter registro de matrícula; Possuir bom desempenho escolar; Dispor de horas semanais para auxiliar os demais estudantes'),
  ('5f04916c-adf6-46f0-a54f-7939cff6b74e', '8f509e27-c13c-5c1a-b824-d722166e5a5e', 3, 'Monitoria de estudos - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('b827338d-8ec8-4da4-88b5-5ea29f255494', 'bcaeee6d-7f70-58ab-ba4c-ebaf1e80ed48', 1, 'Nivelamento: O Programa de Nivelamento da graduação tem como objetivo nivelar conhecimentos em Língua Portuguesa e Matemática dos estudantes dos primeiros e segundos semestres, contribuindo para seu progresso acadêmico. As disciplinas são ofertadas com aulas presenciais e educação a distância (EaD) por meio da plataforma Moodle. Os alunos recebem horas complementares e a oportunidade de obter até 1 ponto na média de todas as disciplinas obrigatórias. Não é necessária inscrição, todos os alunos dos primeiros e segundos semestres são automaticamente matriculados. O programa é dividido em Nivelamento I e II para as disciplinas de Língua Portuguesa e Matemática, e o conteúdo programático é detalhado para cada disciplina. Saiba mais no Regulamento do Programa de Nivelamento I (para estudantes do 1º Semestre), no Regulamento do Programa de Nivelamento II (para estudantes do 2º Semestre) ou pelo Moodle.'),
  ('ebdc7989-ab30-491d-96db-ddb23aa0d122', 'bcaeee6d-7f70-58ab-ba4c-ebaf1e80ed48', 2, 'Nivelamento: Coordenação: Cristina Machado Correa Leite'),
  ('784e9019-6ea0-455a-bce6-47f4c2f3d4b0', 'bcaeee6d-7f70-58ab-ba4c-ebaf1e80ed48', 3, 'Nivelamento - Condições: Estarão aptos a participar do Programa somente os alunos/as alunas regularmente matriculados/matriculadas no 1º semestre, para o Nivelamento I, ou no 2º semestre, para o Nivelamento II, da Graduação; Não é necessário fazer inscrição'),
  ('2de308b8-abe9-4855-843b-7e2798aa6b68', 'bcaeee6d-7f70-58ab-ba4c-ebaf1e80ed48', 4, 'Nivelamento - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Verificar na disciplina direto pelo Moodle. Horário de atendimento: Verificar diretamente no Regulamento. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('f19612ba-6d93-4851-9a58-7975b0a215b3', '36dd5bc8-113f-50cf-8c70-9a4e76578a35', 1, 'Projeto Universidade: Prepare-se para os principais vestibulares do Brasil com o Projeto Universidade do Colégio FECAP! Aqui você tem todo o apoio pedagógico e estudantil, com conteúdos retirados de vestibulares, materiais didáticos e simulados ao longo do período letivo. Para participar, o estudante deve aguardar a divulgação do processo pelo Colégio via ClassApp. Confira a data do início das aulas no Calendário acadêmico e fique atento(a) aos avisos!'),
  ('46d95b02-15c6-4942-9b6d-78147f6df551', '36dd5bc8-113f-50cf-8c70-9a4e76578a35', 2, 'Projeto Universidade - Condições: Ter registro de matrícula'),
  ('745bbe87-66f1-4755-92e1-2941027e1bba', '36dd5bc8-113f-50cf-8c70-9a4e76578a35', 3, 'Projeto Universidade - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Aulas no período da tarde: de segunda a sexta-feira, das 13h45 às 17h50, com intervalo das 15h25 às 15h45. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('2e89e010-92cb-4dba-b726-47a44b7d8e0a', 'bb24577f-2e21-5c17-8b7d-d1bef87bf33d', 1, 'Reforço de Português e Matemática: Está tendo alguma dificuldade em português e/ou matemática? Não se preoucupe! Aqui no Colégio FECAP, você tem direito às aulas de reforço gratuitas para melhorar seu desempenho. O cronograma das aulas é divulgado no calendário acadêmico e você pode participar entrando em contato com a Orientação do Colégio ou pelos canais de atendimento.'),
  ('56e1bdfc-798f-468f-b7d0-1dadf6301d58', 'bb24577f-2e21-5c17-8b7d-d1bef87bf33d', 2, 'Reforço de Português e Matemática - Condições: Possuir registro de matrícula'),
  ('c11e10a2-2407-4c80-9fa6-9c6402f76ab4', 'bb24577f-2e21-5c17-8b7d-d1bef87bf33d', 3, 'Reforço de Português e Matemática - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('88a8f024-d072-4c37-8bb7-dfee409e0df2', '807c8669-2909-5e7b-a087-68eb1e9abd1b', 1, 'Saídas Técnicas: Aqui na FECAP, você tem diversas oportunidades de aprendizagem extracurricular com as visitas técnicas. Ao longo do período letivo, você será avisado(a) pelo ClassApp sobre as saídas externas em empresas, museus, fábricas entre outros. Para isso, é necessário que o responsável assine o Termo de Autorização da visita técnica e efetue o pagamento da taxa de visitação.'),
  ('f4fb2479-23f2-48ac-96d1-be286eef414c', '807c8669-2909-5e7b-a087-68eb1e9abd1b', 2, 'Saídas Técnicas - Condições: Ter registro de matrícula; Responsável deverá assinar o Termo de Autorização da visita técnica; Efetuar o pagamento da taxa, se houver'),
  ('4d7dd7a1-b855-485b-b3fa-b77d78b80702', '807c8669-2909-5e7b-a087-68eb1e9abd1b', 3, 'Saídas Técnicas - Atendimento: Setor responsável: Coordenação do Colégio. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta-feira, das 08:00 às 21:00 e aos sábados, das 09:00 às 13:00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('84e31c93-01b9-4fce-88c0-addce45c560a', '56000f3c-9eaf-5073-a88f-fac03f49533f', 1, 'Teste de proficiência de Inglês para ingressantes: Hey! Ainda não realizou seu teste de proeficência em inglês? Para participar da aula, você precisa realizar um teste de proeficiência pelo aplicativo “English Score”. Mas é simples, veja o passo a passo: – Baixe o aplicativo do EnglishScore no seu celular e crie uma conta; – Realize os 2 testes disponíveis: Core Skills e Speaking; – Dica: comece pelo teste Speaking que contém 3 etapas: grammar and vocabulary, reading e listening; – Inicie o teste adicionando o Connect Code: CELLEP-FECAP (maiúsculo); – O teste Core Skills terá uma duração de 30 minutos. Você precisa fazer todo o teste até visualizar a pontuação; – Se você atingiu 200 pontos, inicie o Speaking adicionando o código anterior; – Ao finalizar o Speaking, não é necessário realizar o Writing. Caso tenha alguma dúvida, entre em contato pelos canais de atendimento.'),
  ('4917ba6d-4f40-400e-872c-09886d07c0f2', '56000f3c-9eaf-5073-a88f-fac03f49533f', 2, 'Teste de proficiência de Inglês para ingressantes - Condições: Ter registro de matrícula'),
  ('7fc91133-09aa-4c20-a067-f04150dd27d4', '56000f3c-9eaf-5073-a88f-fac03f49533f', 3, 'Teste de proficiência de Inglês para ingressantes - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('ac7a7643-cc65-4583-9a55-635b22b9effa', '6f23bf3c-61fe-53db-af23-b9ecc398a22c', 1, 'Acesso à Biblioteca Digital Catalogus: A Biblioteca Digital Catalogus é um acervo de e-books disponíveis para todos os alunos, professores e funcionários. Nela, você terá acesso a até 5 títulos por vez, sendo cada título com acesso por 7 dias. Não sabe como acessar? Vamos descomplicar para você! Acesse Portal FECAP / Sites / Biblioteca / Acervos Digitais > Biblioteca Digital Catalogus > Escolha a Área do Conhecimento > Busque na lista o título do seu interesse > Clique no link > Faça o login com Matrícula + Senha da Biblioteca > Insira um e-mail para cadastro > Preencha com seus dados > Clique em “Ativar” em seguida “Começar a Leitura” > Inicie a sua leitura. Em caso de dúvidas, entre em contato com o ASA por meio de nossos canais de atendimento e nós iremos te orientar.'),
  ('edb2b71f-3fa9-4493-bd9e-edc888566421', '6f23bf3c-61fe-53db-af23-b9ecc398a22c', 2, 'Acesso à Biblioteca Digital Catalogus - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f8b1aedf-1a47-4432-8d75-bc2901dc856b', '6f23bf3c-61fe-53db-af23-b9ecc398a22c', 3, 'Acesso à Biblioteca Digital Catalogus - Atendimento: Setor responsável: Biblioteca. Local: Terminais de Pesquisa da Biblioteca (6o andar - Bloco E). Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Colégio / Graduação / Mestrado / Pós-Graduação.'),
  ('537a4406-75ca-4ce6-ae9d-d8b146c70b74', 'a0000000-0000-0000-0000-000000000005', 1, 'Biblioteca - Empréstimo de Livros: O empréstimo de livros na biblioteca permite até 3 exemplares simultâneos por 14 dias, com renovação automática caso não haja fila de espera pelo título.'),
  ('d77e3fea-c162-47d1-b318-84a71912caa9', 'a0000000-0000-0000-0000-000000000005', 2, 'Biblioteca - Empréstimo de Livros - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e764af55-e24b-4fc5-8d85-7f4ae84c5af9', 'a0000000-0000-0000-0000-000000000005', 3, 'Biblioteca - Empréstimo de Livros - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('aaf73886-d56a-468c-a073-0964d04f6acc', '23bb6701-1db1-5d59-b16f-f7c6e7b88c59', 1, 'Cadastro de Senha: Ainda não possui uma senha de acesso aos serviços da Biblioteca? Não se preocupe, solicitar é muito fácil! Basta comparecer ao balcão da Biblioteca, no 6º andar do Bloco E, e informar seu nome completo e número de matrícula da FECAP. Em instantes, sua senha será cadastrada e você poderá desfrutar de todos os serviços disponíveis. Caso queira alterar sua senha, é só acessar o site da Biblioteca, inserir sua matrícula e senha, ir em Perfil de Usuário e fazer a alteração. Não perca mais tempo e tenha acesso aos acervos da Biblioteca de forma rápida e fácil.'),
  ('bc968a2c-d8ed-4032-9c93-3e5d6d97c8b5', '23bb6701-1db1-5d59-b16f-f7c6e7b88c59', 2, 'Cadastro de Senha - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ff0e85f1-27e1-44f5-99fe-4e4b375dbcf6', '23bb6701-1db1-5d59-b16f-f7c6e7b88c59', 3, 'Cadastro de Senha - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('9bb19a2a-4e5f-4c65-b382-4103cd6d9d81', 'fead7e4e-6429-5538-8014-069796842106', 1, 'Cópia de Documentos Técnico-Científicos (COMUT): Quer enriquecer ainda mais os seus projetos e embasar seus argumentos? Então, se liga nesta dica: com o serviço pago de COMUT você pode solicitar fotocópias de documentos disponíveis em bibliotecas brasileiras e estrangeiras. Tenha acesso a artigos, teses, dissertações, anais de congressos nacionais e internacionais e capítulos de livros. Acesse o portal Requerimento/ Cópia de Documentos Técnico-Científicos (COMUT) e faça a requisição. Caso prefira, entre em contato pelos canais de atendimento do ASA e nós iremos te ajudar. Ah, e para agilizar o serviço tenha em mãos os seguintes dados: título, autor, ano de publicação, volume, número e título do periódico.'),
  ('6b62e5ee-8900-41e4-a9cb-6ce95b8368e8', 'fead7e4e-6429-5538-8014-069796842106', 2, 'Cópia de Documentos Técnico-Científicos (COMUT) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('5f77ed26-b2da-4c91-bc41-03028bd58bb5', 'fead7e4e-6429-5538-8014-069796842106', 3, 'Cópia de Documentos Técnico-Científicos (COMUT) - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('e2f56d0c-b03c-4473-b51a-ffa17adaeef3', '9fd9531b-e204-590b-9eb5-ce733619b1d0', 1, 'Devolução de Materiais: Devolver os materiais da Biblioteca é muito simples! Além de poder realizar a entrega no Balcão de Atendimento (segunda a sexta-feira, das 7h30 às 21h50, e sábado, das 8h às 16h50), você também tem à disposição as caixas de devolução (segunda a sexta, 07h às 23h, e sábado, das 7h às 18h), junto às catracas do térreo e no 7º andar do Bloco E. Atenção: verifique o prazo de devolução para evitar multas e garantir a utilização de todos os serviços da Biblioteca.'),
  ('634c5f5f-0e07-4c0c-a933-7dae01fccb58', '9fd9531b-e204-590b-9eb5-ce733619b1d0', 2, 'Devolução de Materiais - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('c57c255e-f9bd-4cb9-aa35-e94a66713236', '9fd9531b-e204-590b-9eb5-ce733619b1d0', 3, 'Devolução de Materiais - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca: 6° andar, Bloco E | Caixa de Devolução: 7º andar do bloco E e junto às catracas. Horário de atendimento: Balcão: Segunda a sexta, das 7h30 às 21h50 e sábado, das 8h às 16h50. | Caixas de Devolução: Segunda a sexta, das 07h às 23h e sábado, das 7h às 18h. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('aef859b2-e8ee-4a6e-86ae-8781ed4988e4', '206fa220-f580-5c17-be74-37cff8d3ba57', 1, 'Doações de Livros para a Biblioteca: Possui um livro bacana que está parado em sua prateleira? Doe para a Biblioteca! A Biblioteca aceita doações de alunos, ex-alunos, empresas e Instituições de Ensino. Os materiais passarão por avaliação da Biblioteca e, a partir disso, poderão ser incorporados ao acervo, doados, descartados ou devolvidos ao doador. Envie um e-mail para biblioteca@fecap.br com a relação dos materiais que deseja doar, informando autor, título e data da publicação. Caso prefira, procure um agente de sucesso em um de nossos canais. Vamos adorar te ajudar a compartilhar livros e conhecimento!'),
  ('e1ed2abd-1f8b-41d7-ba53-f7f7c78a82a3', '206fa220-f580-5c17-be74-37cff8d3ba57', 2, 'Doações de Livros para a Biblioteca - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('7bb0e7cf-e8a4-43f4-8ad7-d0bbd7dbef7b', '206fa220-f580-5c17-be74-37cff8d3ba57', 3, 'Doações de Livros para a Biblioteca - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('9a48c9b4-a8c2-4bc6-a42a-944a419eb9e1', 'e45f8047-2dc1-5490-bf92-8396a22af998', 1, 'Empréstimo entre Bibliotecas: Deseja consultar uma obra de outro acervo? Faremos a ponte entre você e as Bibliotecas de Instituições Conveniadas. Para isso, entre em contato por meio dos canais de atendimento do ASA, com o título do material e a instituição a qual ele pertence. Estaremos disponíveis para te ajudar! Lembre-se: você será responsável por retirar e devolver o material emprestado à biblioteca a qual solicitou.'),
  ('52699317-c219-45f0-bc30-64d37355a394', 'e45f8047-2dc1-5490-bf92-8396a22af998', 2, 'Empréstimo entre Bibliotecas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('3551645d-9295-4cf6-8be2-05a01db9329a', 'e45f8047-2dc1-5490-bf92-8396a22af998', 3, 'Empréstimo entre Bibliotecas - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('747c6587-631c-49fa-8060-3a604f9213b8', '4a13bef9-f543-5746-b0a0-5d716d970538', 1, 'Guarda-volumes: Aproveite sua leitura com tranquilidade e sem pesos extras. A Biblioteca disponibiliza guarda-volumes para armazenamento de bolsas, mochilas e outros materiais, para você usufruir por até 8 horas e enquanto estiver no recinto. Basta comparecer ao balcão de atendimento da Biblioteca, informar sua matrícula e retirar as chaves. Boa leitura!'),
  ('e3b17b80-5314-4fde-8ed9-76ceffbabe1e', '4a13bef9-f543-5746-b0a0-5d716d970538', 2, 'Guarda-volumes - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('4de56e94-3dde-4fce-8b5a-5dca0b14fd83', '4a13bef9-f543-5746-b0a0-5d716d970538', 3, 'Guarda-volumes - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('566f5e52-11cb-4466-8d5f-14348963ac50', 'd4aed182-71ce-5940-839c-25693f3244de', 1, 'Levantamento Bibliográfico: Que tal uma ajudinha com o seu projeto? Você pode solicitar o serviço de levantamento bibliográfico e ter acesso a pesquisas sobre determinado assunto disponível em livros, artigos científicos, entre outros. Acesse o portal Requerimento/Levantamento Bibliográfico e realize a solicitação. Caso prefira, entre em contato pelos canais de atendimento do ASA e nós iremos te ajudar. Lembre-se de separar todas as informações necessárias para a realização do levantamento, como: delimitação do tema, palavras-chave, tipo de documentos desejados, bases de referência, idioma e local de publicação e formato que deseje receber o material.'),
  ('3be16245-11ed-4c97-9128-4f5e5ff71a97', 'd4aed182-71ce-5940-839c-25693f3244de', 2, 'Levantamento Bibliográfico - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('bd9e0778-d84e-489f-9af2-f9662ac4ed84', 'd4aed182-71ce-5940-839c-25693f3244de', 3, 'Levantamento Bibliográfico - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('39a2bc92-90b3-4116-80df-6a1995cf1b9b', 'c2c81935-9d7a-5546-b101-08618f9fae4f', 1, 'Orientações a Recursos de Pesquisas: Quer saber a melhor maneira de realizar suas pesquisas no Catálogo da Biblioteca On-line e Base de Dados? Vamos te ajudar! Entre em contato por meio dos canais de atendimento do ASA e nós te auxiliaremos com o passo a passo sobre o acesso e utilização das ferramentas disponíveis.'),
  ('77c80642-b71d-4da8-ab23-a71af58c8df6', 'c2c81935-9d7a-5546-b101-08618f9fae4f', 2, 'Orientações a Recursos de Pesquisas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('682196fc-d471-4989-baa3-eb7f1974516c', 'c2c81935-9d7a-5546-b101-08618f9fae4f', 3, 'Orientações a Recursos de Pesquisas - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('ae1eede6-86f0-4191-ab0f-7cdbf7685909', '24a1cf2d-e081-5b77-a18e-9869f279197f', 1, 'Orientações às Normas ABNT/APA: Chegou a hora de fazer um trabalho ou o TCC e bateu dúvidas em relação às normas da ABNT e APA? Não se preocupe, isso é normal. No site da Biblioteca você poderá encontrar materiais para consulta em “Manuais e Templates ABNT e APA”. Em caso de dúvidas, entre em contato por meio de um dos canais de atendimento e nós iremos te ajudar.'),
  ('aacf53e5-6470-47dd-bd77-d3ee507ce91c', '24a1cf2d-e081-5b77-a18e-9869f279197f', 2, 'Orientações às Normas ABNT/APA - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('1449fbc3-4171-422d-9b09-55eb48bb842e', '24a1cf2d-e081-5b77-a18e-9869f279197f', 3, 'Orientações às Normas ABNT/APA - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h50 | Sábado, das 8h às 16h50. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('ecae91d4-3208-40b7-9f5d-14b25a4ed631', '61637732-0f9a-58bc-aff2-c6b97b44e3d1', 1, 'Pagamento de Multas: Regularize suas multas na Biblioteca e aproveite todos os serviços disponíveis: empréstimo, renovação, reserva de material, reserva de sala de vídeo e das salas Co-labs e emissão de “nada consta” para a retirada de documentos na Secretaria. Compareça ao Balcão de Atendimento e realize o pagamento por meio de cartão de débito ou crédito.'),
  ('df47f4b5-c446-4e98-ae86-e95153e3f8fd', '61637732-0f9a-58bc-aff2-c6b97b44e3d1', 2, 'Pagamento de Multas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e976418f-5a19-445f-aa41-442e7562a807', '61637732-0f9a-58bc-aff2-c6b97b44e3d1', 3, 'Pagamento de Multas - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca no 6° andar| Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h30 | Sábado, das 8h às 16h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('4331dd48-d299-4dbd-94b2-2be172ed0f38', 'a238052c-4e38-5d46-846b-2ca6a6372f92', 1, 'Renovação de Materiais: Sabemos que a vida do(a) estudante é corrida. E, por isso, se você precisar renovar o empréstimo de materiais da Biblioteca por mais 7 dias, não tem problema. Basta acessar o Portal FECAP > Sites > Biblioteca > Acesso ao Usuário e Renovação (N° da Matrícula + Senha da Biblioteca) > Clique em Acessar > Renovação > Marque os itens e confirme a operação no botão Renovar > Biblioteca envia automaticamente pelo sistema a confirmação da renovação ao estudante. Atente-se às regras: – A obra não pode estar reservada por outro usuário. – Sua situação na Biblioteca não pode estar irregular (multa e/ou materiais em atraso). – Não ter ultrapassado a data de devolução da obra. – Você pode efetuar até 4 renovações.'),
  ('2bec4047-25b3-4bad-8308-3af8a5f3333c', 'a238052c-4e38-5d46-846b-2ca6a6372f92', 2, 'Renovação de Materiais - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('0beacafd-1dfe-4001-a3f9-d7b85610c28c', 'a238052c-4e38-5d46-846b-2ca6a6372f92', 3, 'Renovação de Materiais - Atendimento: Setor responsável: Biblioteca. Horário de atendimento: Segunda à sexta-feira, das 7h30 às 21h30 | Sábado, das 8h às 16h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8af99323-50ef-4546-8e50-0cf9e80467db', '75e0b455-2029-54b6-a046-d77f58f4cc16', 1, 'Reserva de Co-labs: *Usufrua de salas colaborativas equipadas com computadores para criação de projetos, trabalhos em grupos, orientações e entrevistas.* *Você poderá usar a sala por até 2 horas, tendo a possibilidade de renovação caso não exista reserva para outro(a) estudante.* *Faça a reserva, com até 24 horas de antecedência, via Portal FECAP > URL’s Externas > Biblioteca – Reserva de Salas OU no balcão de atendimento da Biblioteca.* *É necessário retirar a chave da sala no balcão de atendimento.* *Importante: O tempo de tolerância de atraso é de até 10 minutos. Vê se não vai se atrasar, ok?*'),
  ('c2d85179-303c-4be8-99ad-e72ab961c21e', '75e0b455-2029-54b6-a046-d77f58f4cc16', 2, 'Reserva de Co-labs - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('3d2db48a-a4bc-4070-93f4-f8e0eaa11489', '75e0b455-2029-54b6-a046-d77f58f4cc16', 3, 'Reserva de Co-labs - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca no 6° andar - Bloco E. Horário de atendimento: Segunda à sexta-feira, das 7h30 às 21h30 | Sábado, das 8h às 16h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('cd002fc8-9200-44a4-8b13-c556b4aece6f', '7bcdbfb5-cad4-5923-a0f1-29ad09d70d66', 1, 'Reserva de Materiais: Precisa de uma obra que está emprestada a outro usuário? Saiba que você pode solicitar a reserva do material. Se liga no passo a passo: compareça ao Balcão de Atendimento da Biblioteca ou solicite a reserva diretamente no catálogo da biblioteca acessando o Portal da FECAP > Sites > Biblioteca > Consulta ao Acervo > Busque o Material > Clique em “Reserva” > Insira sua Matrícula + Senha da Biblioteca. Pronto! Fique atento(a) a lista para não perder o prazo de retirada do material, pois ficará disponível para você por apenas 24h. A publicação não poderá ser reservada: - Caso haja exemplar disponível no acervo; - Se o usuário estiver com a situação irregular (em atraso); - Se o usuário estiver com o mesmo livro emprestado; - Se houver ultrapassado o limite de até 5 reservas.'),
  ('7173793f-b069-4fb2-82a1-042386680fa6', '7bcdbfb5-cad4-5923-a0f1-29ad09d70d66', 2, 'Reserva de Materiais - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('335a2ac0-9786-4866-ae86-05a6706c4e31', '7bcdbfb5-cad4-5923-a0f1-29ad09d70d66', 3, 'Reserva de Materiais - Atendimento: Setor responsável: Biblioteca. Local: Balcão de Atendimento da Biblioteca - 6° andar, Bloco E. Horário de atendimento: Segunda a sexta-feira, das 7h30 às 21h30 | Sábado, das 8h às 16h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('bd3a9899-7f84-442d-bc65-48b326ceb6fd', 'e6764a61-8824-52c3-b867-76cac2aa9549', 1, 'Abertura de comissão de ética: Viveu alguma experiência em que se sentiu desrespeitado(a) ou ofendido(a)? Nós sentimos muito e queremos te ajudar! Saiba que você pode abrir uma solicitação para a comissão de ética avaliar a situação. Basta requisitar diretamente pelo portal Requerimento/ Abertura de comissão de ética ou nos procurar nos canais de atendimento do ASA. Estamos ao seu lado! Fique tranquilo(a), o seu sigilo será mantido.'),
  ('9d67d7ec-fd40-43d6-959b-c851d01f78ac', 'e6764a61-8824-52c3-b867-76cac2aa9549', 2, 'Abertura de comissão de ética - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('30cab766-fc03-4c01-ba93-c584958a1e3b', 'e6764a61-8824-52c3-b867-76cac2aa9549', 3, 'Abertura de comissão de ética - Atendimento: Setor responsável: Pró-Reitoria de Graduação. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('be033319-e17e-416a-b042-5b18e69df358', 'dc6a07a8-81b9-585e-a9ce-cb310e1ec871', 1, 'Academia FECAPFIT: Ei, Alvarista! Que tal começar uma mudança de hábitos saudáveis? Na FECAPFIT você como aluno(a), possui desconto semestral na mensalidade da academia. O investimento é de R$350,00 referente a 1(um) semestre. Você pode fazer sua inscrição e saber mais pelo formulário. Aproveite essa chance!'),
  ('eff256ef-7f25-4dc8-b084-d3d58a2b4a26', 'dc6a07a8-81b9-585e-a9ce-cb310e1ec871', 2, 'Academia FECAPFIT - Condições: Estar regularmente matriculado; O aluno deve entrar em contato através do instagram da academita: @fecapfit'),
  ('8df31ad7-fdda-4623-845e-67e5dc4b17c6', 'dc6a07a8-81b9-585e-a9ce-cb310e1ec871', 3, 'Academia FECAPFIT - Atendimento: Setor responsável: FECAPFIT. Local: 3° andar - Bloco D. Horário de atendimento: Seg. a Sex, das 07:30 às 19:30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('3a9f236e-c127-4653-8aea-71469d8d7461', '71c449ba-0a15-59e9-b3b2-6e2e01100654', 1, 'Escola de esportes: Você já conhece a Escola de Esportes do Colégio FECAP? São atividades e aulas de esportes que movimentam a vida do estudante e contribui diretamente para o desenvolvimento corporal e físico. O link para inscrição da Escola de Esportes é disponibilizado semestralmente via ClassApp. Fique atento(a) aos comunicados e garanta sua participação!'),
  ('5090317a-1dbd-427e-94f3-30e4769bf381', '71c449ba-0a15-59e9-b3b2-6e2e01100654', 2, 'Escola de esportes - Condições: Ter registro de matrícula; Realizar a inscrição através do link divulgado via ClassApp'),
  ('39732c62-dddc-4844-a4c0-a6ae20b6a599', '71c449ba-0a15-59e9-b3b2-6e2e01100654', 3, 'Escola de esportes - Atendimento: Setor responsável: Coordenação do Colégio. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta das 9h00 às 21h00 | Sábado das 09h00 às 12h00. Nível de ensino: Colégio.'),
  ('5b48e27c-0251-4c8a-b47d-605e474a8b84', '26d069c6-3bc2-5f75-a42e-5a15a4c963a4', 1, 'Grupo de voluntariado: Já pensou em participar de um projeto de voluntarido e adquirir novas habilidades? Aqui na FECAP você pode fazer a diferença! As inscrições para o Grupo de Voluntariado são gratuitas e oferecidas semestralmente via ClassApp. Essa é uma excelente oportunidade para enriquecer o seu currículo e desenvolver competências essenciais, como liderança, empatia e trabalho em equipe.'),
  ('9c5ea4cf-1e36-4329-99cb-50bdfcb4e176', '26d069c6-3bc2-5f75-a42e-5a15a4c963a4', 2, 'Grupo de voluntariado - Condições: Possuir disponibilidade de horário no dia da atividade'),
  ('95e87e03-3657-4b4f-958d-c40aa6694072', '26d069c6-3bc2-5f75-a42e-5a15a4c963a4', 3, 'Grupo de voluntariado - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('65c6ab6a-048d-4a2f-aea7-eb587f702cd1', 'cad096b5-3ce3-5789-b12b-d6d1088d3aa6', 1, 'Ingressantes – Uniforme: O uso do uniforme é fundamental para identificar o verdadeiro alvarista que você é! Por isso, seu uso é obrigatório durante a permanência nas dependências do Colégio. Lembre-se que você pode comprar seu uniforme na Livraria Brainstore, no 4° andar do Bloco A (pátio).'),
  ('500ef94a-6a17-4fb6-bbf1-88297bc92a03', 'cad096b5-3ce3-5789-b12b-d6d1088d3aa6', 2, 'Ingressantes – Uniforme - Condições: Ter registro de matrícula; Estar regularmente matriculado'),
  ('b050cf10-c411-4e92-a636-ad3f9d8d9a5b', 'cad096b5-3ce3-5789-b12b-d6d1088d3aa6', 3, 'Ingressantes – Uniforme - Atendimento: Setor responsável: Coordenação do Colégio. Local: Livraria Brainstore: 4° andar - Bloco A (pátio). Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('91de19d5-8fca-4385-bb54-a10d3188c370', '27686c70-2a1c-5903-aa5b-53afe193eda8', 1, 'Primeiros Passos para Ingressantes na FECAP: Seja bem-vindo(a) à FECAP! Agora você é oficialmente um Alvarista! Os primeiros dias de aulas podem causar um pouco de nervosismo. Mas não se preocupe! Estamos aqui para te orientar nessas horas. Fique de olho do seu e-mail, iremos te instruir acerca dos seus acessos, Portal do Aluno, serviços disponíveis, e muito mais. Caso precise, pode nos procurar a qualquer momento em nossos canais de atendimento ASA. Será um prazer te ajudar nesta jornada de sucesso!'),
  ('63bea660-e607-43e9-ae03-1e42f5b1d06b', '27686c70-2a1c-5903-aa5b-53afe193eda8', 2, 'Primeiros Passos para Ingressantes na FECAP - Condições: Ter registro de matrícula'),
  ('34996b65-d7e7-471b-bb3d-a9aa3797a31c', '27686c70-2a1c-5903-aa5b-53afe193eda8', 3, 'Primeiros Passos para Ingressantes na FECAP - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('eeff415a-0ddf-4d6d-8644-ae6d77f871a2', '90d1afe3-ed3c-5957-a944-178f5e466ef4', 1, 'Adesão ao Programa de Assistência Financeira: Sabemos que imprevistos podem ocorrer, como desemprego, invalidez por acidente ou perda de renda decorrente de afastamento médico do responsável financeiro. Entretanto, não desanime, pois a FECAP está pronta para ajudá-lo(a) a realizar seu sonho! A Fundação oferece o Programa de Assistência Financeira para incentivar a continuidade do seu curso. Se este é o seu caso, basta acessar o Portal do Aluno > Menu > Secretaria/Requerimento > Adesão ao Programa de Assistência Financeira, preencher a solicitação e fazer o upload da documentação necessária. Caso você seja elegível, terá direito a isenção de até 3 mensalidades. Em caso de dúvidas, não hesite em entrar em contato com um dos nossos agentes de sucesso por meio dos nossos canais de atendimento. Teremos prazer em ajudá-lo(a).'),
  ('b371a453-fccc-42e6-a5bd-b0ecc87efb0b', '90d1afe3-ed3c-5957-a944-178f5e466ef4', 2, 'Adesão ao Programa de Assistência Financeira - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('a8a6fc76-591f-4bf4-a9a8-40d9df11b5d6', '90d1afe3-ed3c-5957-a944-178f5e466ef4', 3, 'Adesão ao Programa de Assistência Financeira - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('f46951e1-e3b0-4d4d-8611-52969dd2aeda', 'a0000000-0000-0000-0000-000000000011', 1, 'Auxílio Financeiro Emergencial: O auxílio financeiro emergencial pode ser solicitado por estudantes em situação de vulnerabilidade comprovada, com análise em até 10 dias úteis pela equipe do ASA.'),
  ('46e5907f-317f-4230-bb56-81a92a55f2ed', 'a0000000-0000-0000-0000-000000000011', 2, 'Auxílio Financeiro Emergencial - Condições: Situação de vulnerabilidade comprovada'),
  ('83bb5b8b-baab-4a38-9cc2-f43722c82a98', 'a0000000-0000-0000-0000-000000000011', 3, 'Auxílio Financeiro Emergencial - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('0c4f3bcb-4cb9-476a-b940-1428df8a1be6', '179bc771-b28f-5081-a2ac-f47b41ef2b98', 1, 'Benefício Bolsa Parente (de Colaboradores): Toda família tem aquele tiozão da piada do pavê, não é mesmo? Boa notícia: ele pode te ajudar a estudar! Se você tem alguém da família (tios, primos, entre outros) que trabalha na FECAP, conheça a Bolsa Parente: com ela você tem direito a 50% de desconto nas mensalidades! Incrível, não é?! Para saber como iniciar o processo de aplicação da bolsa, pode nos procurar por meio dos canais do ASA. Estamos à disposição para te ajudar!'),
  ('7272ed89-0639-4d75-ab3b-7a3995b951f2', '179bc771-b28f-5081-a2ac-f47b41ef2b98', 2, 'Benefício Bolsa Parente (de Colaboradores) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('312705a0-ba6a-447d-9a2f-2b55f88b6f5b', '179bc771-b28f-5081-a2ac-f47b41ef2b98', 3, 'Benefício Bolsa Parente (de Colaboradores) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8747b213-cdeb-470c-84f7-30df597e1b12', '42e4c259-e305-5996-9b23-1ac66b7106bf', 1, 'Bolsa Convenção Trabalhista (de Colaboradores): Imagine trabalhar em um ambiente descontraído, que estimula o crescimento e ainda te proporciona estudar em uma instituição que é referência em pioneirismo e excelência na educação. Na FECAP é assim! Funcionários, cônjuges, filhos e dependentes legais têm direito à bolsa integral. Para saber mais sobre o processo de aplicação da bolsa, entre em contato com um dos nossos canais de atendimento. Será um prazer te auxiliar!'),
  ('da1b8cf9-bf7b-4cbb-a364-77bb08eb0e77', '42e4c259-e305-5996-9b23-1ac66b7106bf', 2, 'Bolsa Convenção Trabalhista (de Colaboradores) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('12791031-1b9a-43fa-b0ac-63531f85bf83', '42e4c259-e305-5996-9b23-1ac66b7106bf', 3, 'Bolsa Convenção Trabalhista (de Colaboradores) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('4d11c982-1573-49d4-86e4-11099e2cbdae', '9d334cef-cb6e-56bc-bada-a25d368202fa', 1, 'Bolsa Convênio com Organizações Parceiras: Você trabalha em alguma empresa parceira da FECAP? Então, saiba que pode solicitar a Bolsa Convênio a qualquer momento e terá direito a ela enquanto mantiver o vínculo com a organização. Para isso, basta acessar o Portal do Aluno > Menu > Secretaria/Requerimento > Bolsa Convênio com Organizações Parceiras. Mas, não se preocupe. Caso a sua empresa ainda não seja afiliada à FECAP, basta acessar o link para saber mais e se tornar uma empresa parceira.'),
  ('df1892f5-4a2a-470c-a3c1-79be526e4f1b', '9d334cef-cb6e-56bc-bada-a25d368202fa', 2, 'Bolsa Convênio com Organizações Parceiras - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('06e90298-cb56-4f36-8cef-b4edcb10b95c', '9d334cef-cb6e-56bc-bada-a25d368202fa', 3, 'Bolsa Convênio com Organizações Parceiras - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('1415b4fb-8c18-4f50-b0ad-572e609bde27', '96b7b584-26e8-52c2-a682-815ec1c199ff', 1, 'Bolsa Desempenho Acadêmico (Bolsa Melhores Alunos): Aqui no Colégio FECAP, o aluno de melhor desempenho em sua série, receberá bolsa de 75%. Os demais estudantes mais bem avaliados, terão 25% de desconto na mensalidade. Observações: – Você receberá a indicação pela Coordenação do Colégio; – As Bolsas têm duração de um período letivo e são concedidas no ano seguinte à classificação (conforme regulamento de bolsa disponibilizado pelo Colégio). Caso tenha alguma dúvida, entre em contato com a coordenação do Colégio pelos canais de atendimento.'),
  ('20e1a39a-3b04-4ebd-af37-d16ab9c058d3', '96b7b584-26e8-52c2-a682-815ec1c199ff', 2, 'Bolsa Desempenho Acadêmico (Bolsa Melhores Alunos) - Condições: Possuir registro de matrícula; Ser considerado o melhor estudante da sua série'),
  ('a98ef76b-b5d8-403f-ac03-ad36d40e2113', '96b7b584-26e8-52c2-a682-815ec1c199ff', 3, 'Bolsa Desempenho Acadêmico (Bolsa Melhores Alunos) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio / Graduação.'),
  ('470bb130-af2a-4c5d-a5a0-7f52ef47ffa1', 'e93ae8c2-572d-5b95-b52f-92b700fc4f25', 1, 'Bolsa Desempenho Acadêmico – Formandos: Você sabia que os alunos de melhor desempenho possuem 40% de bolsa no primeiro semestre dos cursos de Graduação, após concluir o ensino médio aqui na FECAP? Confira as condições: – Se você recebeu o Certificado de Mérito de melhor estudante do último ano da sua turma; – Está com status formado; – E deseja cursar algum curso de Graduação na FECAP; Basta apresentar o documento no ato da matrícula para consolidar o desconto. Caso tenha alguma dúvida, entre em contato com a coordenação do Colégio pelos canais de atendimento.'),
  ('cd18c51a-db22-4d0a-a543-b0b36fe1d069', 'e93ae8c2-572d-5b95-b52f-92b700fc4f25', 2, 'Bolsa Desempenho Acadêmico – Formandos - Condições: Ter sido considerado FORMADO; Ter sido considerado o melhor estudante do último ano da sua turma; Ter sido considerado o melhor estudante do curso (média global); Ter cursado ao menos 50% da carga horária total do curso na FECAP'),
  ('0e2075bf-9a29-4b8d-b3ee-ffe0a166b8ec', 'e93ae8c2-572d-5b95-b52f-92b700fc4f25', 3, 'Bolsa Desempenho Acadêmico – Formandos - Atendimento: Setor responsável: Área de Sucesso Alvarista - ASA. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio.'),
  ('3574cd50-2e99-4fcb-b089-eb1459c17fa7', '7c83051f-f1f0-5dd7-b222-b1498d550336', 1, 'Bolsa Estudantes Ingressantes – Teste de Conhecimento: Você já conhece a Bolsa para estudantes ingressantes? Ao longo do período de matrículas, o Colégio FECAP aplica o “Teste de Conhecimento”. Trata-se de uma prova de 20 questões, que avalia o conhecimento nas áreas de Língua Portuguesa e Matemática. O estudante pode receber bolsa de até 10% de desconto ao longo de todo período letivo que estiver cursando na FECAP. Observação: no caso da reprovação do estudante em qualquer série do Ensino Médio ou Ensino Médio Técnico, não será concedida a bolsa enquanto ele estiver cursando a série na qual reprovou. Caso tenha dúvidas, entre em contato pelos canais de atendimento.'),
  ('fb69bb57-437c-4bd4-81ba-b0589ff65812', '7c83051f-f1f0-5dd7-b222-b1498d550336', 2, 'Bolsa Estudantes Ingressantes – Teste de Conhecimento - Condições: O candidato deverá atingir os critérios definidos pelo Regulamento de Bolsas'),
  ('309f8319-9417-425b-88de-676f1d6ff457', '7c83051f-f1f0-5dd7-b222-b1498d550336', 3, 'Bolsa Estudantes Ingressantes – Teste de Conhecimento - Atendimento: Setor responsável: Financeiro. Local: Coordenação do Colégio. Nível de ensino: Colégio.'),
  ('5c2691e0-a951-479c-a111-594d97b6df8b', '6080d3d3-fdcc-515c-abac-3040c9ab651c', 1, 'Bolsa Estágio: Foi aprovado(a) como estagiário(a) FECAP? Parabéns! Agora, você tem direito à Bolsa de Estágio! Confira com o RH. Em caso de dúvidas, entre em contato por meio dos canais de atendimento do ASA. Será um prazer te auxiliar!'),
  ('780de608-a688-4d94-9fce-4d4066c04687', '6080d3d3-fdcc-515c-abac-3040c9ab651c', 2, 'Bolsa Estágio - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('658505ee-606e-40eb-998f-0ac15622123c', '6080d3d3-fdcc-515c-abac-3040c9ab651c', 3, 'Bolsa Estágio - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('a101a076-0b3e-4fdc-a8ab-b674f1063c13', 'd38c57ae-af94-5c39-9088-7e131ce5b397', 1, 'Bolsa Familiar (de Estudante): Estudar com a família é ainda melhor! Se você é aluno(a) da FECAP e tem um parente de primeiro grau estudando na instituição, pode solicitar a Bolsa Familiar e ganhar um desconto de 10% na mensalidade. Basta acessar o Portal do Aluno > Menu > Secretaria/Requerimento > Bolsa Familiar e preencher a solicitação. Lembre-se de que o desconto só será válido enquanto você e seu(sua) parente estiverem estudando simultaneamente.'),
  ('2981c470-a32f-4000-a2b8-4b3be58c75b1', 'd38c57ae-af94-5c39-9088-7e131ce5b397', 2, 'Bolsa Familiar (de Estudante) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('882f84e8-1221-4be0-bbf4-27d09dccf0d8', 'd38c57ae-af94-5c39-9088-7e131ce5b397', 3, 'Bolsa Familiar (de Estudante) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('7a3a3409-8898-4a88-bb84-3e75d5133fd7', '9fbe997a-710c-5994-9849-a4418d468663', 1, 'Bolsa Ingresso Especial (não elegíveis ao ProUni/FIES): Se você perdeu a bolsa ProUni ou Fies durante a realização do curso, não desanime. Isso não é motivo para desistir dos seus sonhos! Você pode solicitar a Bolsa Ingresso Especial FECAP. Basta enviar o seu pedido para análise via portal Requerimento/Bolsa Ingresso Especial ou entre em contato conosco por meio dos canais de atendimento. Nós queremos te ajudar a construir o seu futuro!'),
  ('01b2cf9b-5ef3-4283-b290-a48672ea583a', '9fbe997a-710c-5994-9849-a4418d468663', 2, 'Bolsa Ingresso Especial (não elegíveis ao ProUni/FIES) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('553f6994-f320-4201-b280-f32cff0ee212', '9fbe997a-710c-5994-9849-a4418d468663', 3, 'Bolsa Ingresso Especial (não elegíveis ao ProUni/FIES) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('b11de445-ce8a-49f1-897e-120744cba232', '0aefb5f9-21b7-5901-82df-e0255f431a33', 1, 'Bolsa Iniciação Científica: Você é participante do Programa de Iniciação Científica e não identificou a aplicação da bolsa em sua mensalidade? Não se preocupe. Siga o passo a passo: Portal do Aluno> Requerimento> Bolsa Iniciação Científica e preencha a solicitação. O prazo para a conclusão do requerimento é de 15 dias úteis. Qualquer dúvida, estamos à disposição!'),
  ('f846c48b-b9a4-4fcb-bed0-deade22b81e9', '0aefb5f9-21b7-5901-82df-e0255f431a33', 2, 'Bolsa Iniciação Científica - Condições: O estudante deve ter sido selecionado no Programa de Iniciação Científica no período letivo da solicitação'),
  ('bbf100bf-2049-4726-9e73-ac696b0015ab', '0aefb5f9-21b7-5901-82df-e0255f431a33', 3, 'Bolsa Iniciação Científica - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('8942abd3-2feb-401b-bc06-e7b2351c8bff', '4f8e7f14-fcb3-5404-8ec3-2ef66862bad5', 1, 'Bolsa Monitoria: Você sabia que a FECAP disponibiliza Bolsa Monitoria para os estudantes participantes? Para participar, precisa fazer o processo seletivo que ocorre no começo do ano. A bolsa mensal corresponde a 50% do valor da mensalidade, então fique de olho na divulgação do edital e prazos de inscrição. Se você já participa do Programa de Monitoria, mas ainda não identificou o desconto em sua mensalidade, nós iremos te ajudar! Acesse o Portal do Aluno > Requerimentos > Bolsa Monitoria e preencha a solicitação. Qualquer dúvida, estamos à disposição!'),
  ('e513c2b8-07dd-41d8-ab80-acc7703740f1', '4f8e7f14-fcb3-5404-8ec3-2ef66862bad5', 2, 'Bolsa Monitoria - Condições: O estudante deve ter sido selecionado como Monitor de determinada disciplina no período letivo da solicitação'),
  ('8b23e7fc-e8c8-4f92-9321-5e720fe2ccb2', '4f8e7f14-fcb3-5404-8ec3-2ef66862bad5', 3, 'Bolsa Monitoria - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('0bba8d0c-0439-49a6-b87f-c7f5b1d70673', 'f3717c02-d634-563d-add2-c98bddba3e06', 1, 'Bolsa Santander: Na FECAP, seu desempenho e esforço valem muito! Com o Programa de Bolsa Santander Graduação, os(as) estudantes com bom desempenho acadêmico são beneficiados com um auxílio financeiro para dar continuidade aos estudos e concluir o curso dos sonhos. Para se inscrever, acesse e preencha as informações solicitadas. Ficou com dúvidas sobre o processo de inscrição? Não hesite em entrar em contato conosco por meio dos nossos canais de atendimento. Ficaremos felizes em te ajudar em seu caminho rumo ao sucesso!'),
  ('7bf2bedc-92f2-4ffe-9acb-fa41799d4aa8', 'f3717c02-d634-563d-add2-c98bddba3e06', 2, 'Bolsa Santander - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('42510ea6-473e-4be8-93ce-eaac15b6a3b9', 'f3717c02-d634-563d-add2-c98bddba3e06', 3, 'Bolsa Santander - Atendimento: Setor responsável: Pró-Reitoria de Extensão e Desenvolvimento. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('5044e397-80c1-4148-b9fa-b0e56add3936', 'd1b538bd-9824-5348-b4cf-7456189a07cb', 1, 'FIES – Aditamento para Renovação: Quer realizar a renovação (Aditamento) semestral do FIES e não sabe como? Entre em contato por meio dos canais de atendimento do Asa e nós te orientaremos sobre o processo de aditamento para renovação, esclarecendo todas as suas dúvidas quanto às condições e os tipos de aditamento disponíveis (simplificado ou não simplificado). Será um prazer te ajudar!'),
  ('091aec4f-c2a4-4b5d-b52f-daac9843c212', 'd1b538bd-9824-5348-b4cf-7456189a07cb', 2, 'FIES – Aditamento para Renovação - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('bda7946b-6056-46ad-811b-3cc95dac2789', 'd1b538bd-9824-5348-b4cf-7456189a07cb', 3, 'FIES – Aditamento para Renovação - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado.'),
  ('04683d62-e112-4a6a-8029-0a075558ef71', 'ad697276-e830-549d-b315-19623e848d3d', 1, 'FIES – Dilatação do Prazo (Prorrogação): Precisa prorrogar o prazo de utilização do FIES? Inicie o processo de dilatação pelo site e comunique o Financeiro pelo e-mail fies@fecap.br Em caso de dúvidas, pode nos procurar em um dos canais de atendimento do ASA. Faremos de tudo para lhe ajudar. Atenção: o(a) estudante pode solicitar a dilatação somente um semestre por vez. O limite são de 04 (quatro) dilatações, porém o valor de todos os semestres dilatados não poderá ultrapassar o dobro do valor do último semestre contratado regularmente.'),
  ('5bb6d430-3882-49f9-9a1f-826263ddb525', 'ad697276-e830-549d-b315-19623e848d3d', 2, 'FIES – Dilatação do Prazo (Prorrogação) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e090ce06-b7c4-468b-ac00-c7e06906d75f', 'ad697276-e830-549d-b315-19623e848d3d', 3, 'FIES – Dilatação do Prazo (Prorrogação) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado.'),
  ('6d8bb6e9-b6b6-4261-8fe8-c76921d62210', 'ffbcf329-299f-5e08-9b86-edebc43b875a', 1, 'ProUni: Atualização: Para garantir o seu benefício ProUni, lembre-se de que a cada semestre você deverá assinar o Termo de Atualização do Usufruto da Bolsa. Fique atento(a) às comunicações enviadas pelo ASA com os prazos para assinatura. Em caso de dúvidas, você pode nos procurar a qualquer momento. Os nossos meios de atendimento estão sempre abertos para te auxiliar.'),
  ('f1bd7489-347c-434c-9383-9d76b3e96797', 'ffbcf329-299f-5e08-9b86-edebc43b875a', 2, 'ProUni: Atualização - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('573a76ce-e5b7-4713-a944-46b4f1555cdc', 'ffbcf329-299f-5e08-9b86-edebc43b875a', 3, 'ProUni: Atualização - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('cea00d0e-3507-4b77-88ee-63ea31cb78a5', '0f728f5a-c049-5969-bb92-8da8861dcf98', 1, 'ProUni: Concessão (vagas remanescentes): Se você não foi chamado(a) nas listas do ProUni, não fique triste! Ainda há opção de vagas remanescentes. Fique ligado(a) aos seus meios de comunicação, você será orientado sobre a entrega dos documentos por e-mail ou contato telefônico. Boa sorte! Lembre-se, em caso de dúvidas estamos sempre prontos para te ajudar!'),
  ('214134f5-cc7b-48b7-bdc8-113b5a7a4234', '0f728f5a-c049-5969-bb92-8da8861dcf98', 2, 'ProUni: Concessão (vagas remanescentes) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e49b4ab1-fe8a-4675-ac22-207a27992eb2', '0f728f5a-c049-5969-bb92-8da8861dcf98', 3, 'ProUni: Concessão (vagas remanescentes) - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('660321a4-f023-4970-84f5-9c27c3b3c794', '4eb4a723-dcd7-50d5-8849-8618df25505a', 1, 'ProUni: Reconsideração da bolsa: Você foi reprovado(a) e está com medo de perder a sua bolsa ProUni? Temos uma boa notícia: você pode solicitar a reconsideração da bolsa por até duas vezes. Abra a solicitação, informando os principais motivos que o(a) levarem a reprovação, pelo portal Requerimento/ ProUni: Reconsideração da bolsa. Sua requisição será analisada e você poderá acompanhar por meio do seu Portal do Aluno. Qualquer dúvida, entre em contato por meio dos nossos canais de atendimento. Estamos disponíveis para te ajudar!'),
  ('746fe5d0-bed9-4247-a793-9b58fda5c4d5', '4eb4a723-dcd7-50d5-8849-8618df25505a', 2, 'ProUni: Reconsideração da bolsa - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e6e8ce88-b232-4c34-b153-c13e6a95469d', '4eb4a723-dcd7-50d5-8849-8618df25505a', 3, 'ProUni: Reconsideração da bolsa - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('db96665d-3bf3-41c8-ae62-38e56769545f', 'd48f62c2-0e90-50fa-8cf6-fb6eebdac084', 1, 'Programa de Bolsa Restituível – Adesão: Na FECAP, acreditamos em facilitar o acesso à educação de qualidade para todos(as). Em uma destas iniciativas, a Fundação conta com o Programa de Bolsa Restituível. Nesta modalidade, os(as) candidatos(as)/estudantes podem realizar o curso de graduação pagando um percentual menor em sua mensalidade. Ao final, os valores restantes devem ser restituídos à FECAP, sem juros, de forma a beneficiar novos estudantes. Não deixe seu futuro para depois! Participe do programa! Envie a sua solicitação pelo portal Requerimento/ Programa de Bolsa Restituível – Adesão. Em caso de dúvidas, pode nos procurar por meio dos canais de atendimento do ASA. Será um prazer te auxiliar na sua jornada rumo ao sucesso!'),
  ('220ebf5f-5432-48d9-8793-e00a576c2d30', 'd48f62c2-0e90-50fa-8cf6-fb6eebdac084', 2, 'Programa de Bolsa Restituível – Adesão - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('985476f1-b884-4fed-adea-f8b3eb363982', 'd48f62c2-0e90-50fa-8cf6-fb6eebdac084', 3, 'Programa de Bolsa Restituível – Adesão - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('d2de7d3c-70f9-448d-a46f-6faeb2406724', '904bd485-7aba-5270-b3d7-58d04b26a395', 1, 'Programa de Bolsa Restituível – Prorrogação do Prazo: Se por algum motivo você precisa prorrogar o prazo de pagamento da sua Bolsa Restituível, fique tranquilo(a), você pode abrir uma solicitação de análise para novo vencimento. Basta requisitar pelo portal Requerimento/ Programa de Bolsa Restituível – Prorrogação do Prazo ou, caso tenha dúvidas, nos procure em um dos canais de atendimento do ASA. Faremos de tudo para lhe ajudar. Atenção: a solicitação deverá ser aberta antes do vencimento das parcelas do Programa.'),
  ('b4418b53-4932-449e-890e-a9144a80f224', '904bd485-7aba-5270-b3d7-58d04b26a395', 2, 'Programa de Bolsa Restituível – Prorrogação do Prazo - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9969974f-cf4e-41c5-91ae-b919af0943fc', '904bd485-7aba-5270-b3d7-58d04b26a395', 3, 'Programa de Bolsa Restituível – Prorrogação do Prazo - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('f126c29f-794c-4940-bdd1-5e6c72a72737', 'c299d420-38a9-5897-ba0d-a4d9b4ea47e1', 1, 'Programa de Bolsa Restituível – Quitação Antecipada: Deseja antecipar suas parcelas do Programa de Bolsa Restituível? É possível! Basta acessar o portal Requerimento/Programa de Bolsa Restituível – Quitação Antecipada ou, caso tenha dúvidas, entre em contato por meio dos canais de atendimento do ASA. Será um prazer te auxiliar!'),
  ('67380bab-1951-40e7-9084-49f9d7e46e32', 'c299d420-38a9-5897-ba0d-a4d9b4ea47e1', 2, 'Programa de Bolsa Restituível – Quitação Antecipada - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ae1b11a6-8860-4e84-9649-b9442d472133', 'c299d420-38a9-5897-ba0d-a4d9b4ea47e1', 3, 'Programa de Bolsa Restituível – Quitação Antecipada - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('36d68070-ce72-4e27-b7e2-cfcb4a349c06', '2f183c3b-8509-5aaf-9f76-a917f56d2d12', 1, 'Programa de Bolsa Restituível – Renovação: Faça a renovação do Programa de Bolsa Restituível e garanta a continuidade da construção do seu futuro! Envie a sua solicitação pelo portal Requerimento/Programa de Bolsa Restituível – Renovação ou, em caso de dúvidas, fale conosco por meio de um dos canais de atendimento do ASA. Vamos adorar te ajudar a realizar seu sonho da formação superior!'),
  ('bcff0eb2-f715-4a84-be05-c85add1df5ab', '2f183c3b-8509-5aaf-9f76-a917f56d2d12', 2, 'Programa de Bolsa Restituível – Renovação - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('01bcbf28-c1b9-4c69-93be-85cad0df3d33', '2f183c3b-8509-5aaf-9f76-a917f56d2d12', 3, 'Programa de Bolsa Restituível – Renovação - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('dc72b06a-e6a2-4843-bbdd-918f2647ee40', '3c37f062-68c5-5958-a6f4-9a186c1197cb', 1, 'Acesso a vagas – FECAP+ Oportunidades: Bem-vindo(a) à sua Jornada de Desenvolvimento Pessoal e Profissional! E para começar com chave de ouro, queremos compartilhar uma incrível oportunidade que vai alavancar ainda mais o seu crescimento! Apresentamos a você o FECAP+ Oportunidades, a plataforma de empregabilidade e carreira da FECAP. Esta é uma ferramenta muito poderosa que lhe possibilitará realizar a autogestão de sua carreira, aprimorar suas habilidades, identificar seu perfil comportamental e explorar caminhos profissionais alinhados ao seu potencial, além de dar aumentar o seu autoconhecimento. Para acessar é muito fácil: faça o login em seu Portal do Aluno > Menu > Urls Externas > FECAP+ Oportunidades.'),
  ('a9ce0aef-b238-4a3d-98c7-0f0bdeddcae7', '3c37f062-68c5-5958-a6f4-9a186c1197cb', 2, 'Acesso a vagas – FECAP+ Oportunidades - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9e900d55-ffc7-48c8-aaf1-5b9a7b44b158', '3c37f062-68c5-5958-a6f4-9a186c1197cb', 3, 'Acesso a vagas – FECAP+ Oportunidades - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação / Mestrado.'),
  ('fce4c2b9-a9e6-4799-9ce9-80069a43cada', 'd640745d-246d-500a-a5e9-fbd2ad10fabe', 1, 'Aconselhamento de Carreira: Está com dúvidas sobre seu direcionamento profissional no mercado de trabalho? Aqui na FECAP, nós te auxiliamos nesta jornada. Com as sessões individuais da mentoria de carreiras, você poderá focar em um plano de ação direcionado à colocação ou recolocação no mercado de trabalho. Comece agora mesmo a traçar as estratégias para o seu futuro! Agende seu horário pelo caminho: Portal do Aluno > Menu > Urls Externas > FECAP + Desenvolvimento.'),
  ('d2220146-23b1-43d4-b198-adeb26b159ca', 'd640745d-246d-500a-a5e9-fbd2ad10fabe', 2, 'Aconselhamento de Carreira - Condições: O agendamento é destinado para alunos e ex-alunos FECAP; O estudante poderá solicitar o serviço por meio do canal listado'),
  ('96469337-7ff7-412f-9885-417e74ae275f', 'd640745d-246d-500a-a5e9-fbd2ad10fabe', 3, 'Aconselhamento de Carreira - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('82c56a8f-055b-4c63-adf0-97ec0233d167', 'b9d20b58-24c9-57a2-9fec-e1797aa49a3c', 1, 'Aconselhamento sobre Estágio Não Obrigatório: Desde o primeiro semestre você já pode estagiar. Mas, está com dúvidas sobre como alavancar a sua carreira ou buscar por uma recolocação no mercado de trabalho? Ou gostaria de dicas para montar o seu currículo e/ou seu perfil no LinkedIn? Não se preocupe, estamos preparados para te auxiliar nesse momento tão importante da vida! Aproveite e faça agora mesmo o seu agendamento de Mentoria de Carreira exclusivamente pelo Portal do Aluno. Confira o caminho: Menu > URLs Externas > FECAP+ Desenvolvimento.'),
  ('6458bec3-aaef-4044-94d2-3c959fc7e8a0', 'b9d20b58-24c9-57a2-9fec-e1797aa49a3c', 2, 'Aconselhamento sobre Estágio Não Obrigatório - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ad6fb765-64a1-4a81-914c-4621ef6a1237', 'b9d20b58-24c9-57a2-9fec-e1797aa49a3c', 3, 'Aconselhamento sobre Estágio Não Obrigatório - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação.'),
  ('437a742e-5ac0-40b2-88b3-2e9ad5a05fdf', '7f1e2b77-e57f-5247-8e06-e03fe9ffeabb', 1, 'Coach Holístico: Já ouviu falar em Coach Holístico? São atendimentos individuais, realizados em 10 sessões, para te ajudar a definir seus objetivos, compreender os seus valores e identificar os obstáculos e conflitos da sua mente. Faça seu agendamento pelo Portal do Aluno > URLs externa > “FECAP + Desenvolvimento” e em reservas, selecione a agenda da Profa. Maria de Lurdes.'),
  ('d4399d69-2c3a-4367-8e15-fc7c9181fddb', '7f1e2b77-e57f-5247-8e06-e03fe9ffeabb', 2, 'Coach Holístico - Condições: O agendamento é destinado para alunos e ex-alunos FECAP. O estudante poderá solicitar o serviço por meio do canal listado'),
  ('5fc30a9c-db4f-4eac-b74d-2654eb6f928f', '7f1e2b77-e57f-5247-8e06-e03fe9ffeabb', 3, 'Coach Holístico - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('46b22180-bd14-4edf-ad1c-0ab4afc58a6f', 'e97f21c2-bc59-506d-b4f5-68aee56d4e25', 1, 'Construção do Currículo do Futuro: Ainda não fez o seu currículo do futuro? Não espere mais para sair na frente e se destacar na busca daquela oportunidade de emprego que faz seu olho brilhar! Acesse o seu Portal do Aluno, selecione a opção Urls externas, clique em FECAP+ Oportunidades e preencha todas as informações solicitadas em “Currículo do Futuro”. Seu currículo será gerado automaticamente em PDF e você poderá compartilhar via e-mail, LinkedIn etc. Se precisar de ajuda e orientações, fique à vontade para nos procurar. Nossos canais estão sempre abertos para te receber!'),
  ('8c9fdf4d-ab7e-4af1-bb27-bdbfd0b552cc', 'e97f21c2-bc59-506d-b4f5-68aee56d4e25', 2, 'Construção do Currículo do Futuro - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9723d28a-2b60-4996-b671-4a4a87116e31', 'e97f21c2-bc59-506d-b4f5-68aee56d4e25', 3, 'Construção do Currículo do Futuro - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('a568a912-d129-4a15-9fa2-cbc9a00b3132', 'a8daf560-6f3f-5dec-b158-fe134f477c96', 1, 'Entrega do Relatório de Estágio Supervisionado: O Estágio Supervisionado é essencial para a conclusão do curso, sendo sua carga horária um requisito obrigatório para a obtenção do diploma. Para ser aprovado(a) na disciplina e comprovar as horas, é necessário entregar o Relatório de Estágio/Trabalho Supervisionado dentro dos prazos estabelecidos. Os cursos que exigem a entrega do Relatório de Estágio Supervisionado são: Administração, Ciências Contábeis/CCG, Secretariado Executivo e Relações Públicas. Cronograma – 2026.1: - 1º Prazo: até 24/04/2026 - 2º Prazo: até 22/05/2026 Entrega do relatório A entrega do relatório é obrigatória e condição para análise e validação pela instituição. Acesse mais informações aqui. O envio deve ser realizado uma única vez pelo caminho: *Portal do Aluno > Menu > URLs Externas > FECAP+ Oportunidades > Gestão de Estágios*'),
  ('b47dbbb0-3ee8-491a-b200-5dfba23516db', 'a8daf560-6f3f-5dec-b158-fe134f477c96', 2, 'Entrega do Relatório de Estágio Supervisionado - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ca2cbca0-cfc7-492b-b153-4c6878782f8e', 'a8daf560-6f3f-5dec-b158-fe134f477c96', 3, 'Entrega do Relatório de Estágio Supervisionado - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('59fd10ea-7b0d-452b-89b6-8a3b320dff2f', 'a0000000-0000-0000-0000-000000000003', 1, 'Estágio Obrigatório: O estágio obrigatório precisa ser iniciado a partir do 4º semestre, com carga horária mínima de 300 horas, supervisionado por um professor orientador e registrado no sistema de estágios.'),
  ('47dc4725-56e1-48c5-ae24-d4dc016cf36d', 'a0000000-0000-0000-0000-000000000003', 2, 'Estágio Obrigatório - Condições: Iniciar a partir do 4º semestre; carga horária mínima de 300 horas; supervisão de um professor orientador; registro no sistema de estágios'),
  ('3ee03b17-f8a0-451e-a07d-98a81618da50', 'a0000000-0000-0000-0000-000000000003', 3, 'Estágio Obrigatório - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('381c7afa-2a71-45d9-a453-2f8e41772b77', '4c0e557b-20cd-5d64-b2f4-a61a2f88f6ce', 1, 'Estágio: Entrega de Documentação: Conseguiu uma proposta de estágio técnico e precisa da sua documentação? Ficamos felizes com o seu progresso! Para dar andamento à solicitação de assinatura do Estágio, acione a coordenação do Colégio e, caso já possua a documentação da empresa, leve o documento. O prazo desta solicitação é de 7 (sete) dias úteis. Qualquer dúvida, entre em contato pelo telefone: 3272-2280.'),
  ('c2f10365-59e2-45e5-93d8-ee8342b12162', '4c0e557b-20cd-5d64-b2f4-a61a2f88f6ce', 2, 'Estágio: Entrega de Documentação - Condições: Ter registro de matrícula; Estar regularmente matriculado, com status de CURSANDO no período letivo'),
  ('6c5953c1-ff3c-4627-bce5-933ce21e4a1f', '4c0e557b-20cd-5d64-b2f4-a61a2f88f6ce', 3, 'Estágio: Entrega de Documentação - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio / Graduação / Pós-Graduação.'),
  ('38ed276a-eeea-4c27-b75b-4afbe4037d57', '57cf404e-76f5-5b53-976f-fd2c7e5f66e4', 1, 'FECAP+ Oportunidades | Dificuldade de Acesso: Se tentou fazer login na plataforma FECAP+ Oportunidades, mas está com dificuldades referentes ao acesso? Não se preocupe! Entre em contato conosco por meio de um de nossos canais de atendimento informando o seu número da matrícula (RA), nome completo e o erro que aparece para você que um de nossos agentes terá o prazer em te auxiliar.'),
  ('e837816c-7cbb-4f38-9552-c5d2e3d519c8', '57cf404e-76f5-5b53-976f-fd2c7e5f66e4', 2, 'FECAP+ Oportunidades | Dificuldade de Acesso - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('418eb4c9-48d6-4c80-89a9-8b6682246f9d', '57cf404e-76f5-5b53-976f-fd2c7e5f66e4', 3, 'FECAP+ Oportunidades | Dificuldade de Acesso - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('7e974cfb-4932-480a-8497-85b0f68a4a2f', '6351abb8-f448-5c76-a34f-5e5da1491d11', 1, 'Modelos de Documentos de Estágio: Passou no estágio e não sabe quais documentos deve entregar para a empresa? Vamos te ajudar! Confira alguns modelos de documentação que preparamos para você: - Acordo de Cooperação: baixe aqui. - Termo de Compromisso de Estágio e Plano de Atividades (Contrato): baixe aqui. - Relatório Semestral de Atividades (Avaliação de Desempenho do(a) estagiário(a)): baixe aqui. - Orientação Institucional para Elaboração do Relatório Semestral de Atividades: baixe aqui. - Termo Aditivo: baixe aqui. - Rescisão (Termo de Encerramento de Estágio): baixe aqui. - Plano de Trabalho para Comprovação de Horas Complementares: baixe aqui. Após o preenchimento e assinatura do(s) documento(s), encaminhe para a aprovação e assinatura da FECAP por meio do Portal do Aluno > Menu > Secretaria/Requerimentos > Estágio: Entrega de Documentação.'),
  ('64bfd901-c93b-4aa4-aab0-5dca833683f5', '6351abb8-f448-5c76-a34f-5e5da1491d11', 2, 'Modelos de Documentos de Estágio - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ef6c2d4e-e28f-4104-b769-c7e122bb5e74', '6351abb8-f448-5c76-a34f-5e5da1491d11', 3, 'Modelos de Documentos de Estágio - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação.'),
  ('94568bf8-7c81-48bd-bc0f-b9c89dcb36d2', '7b7e11f6-ec43-5379-bdf2-94635f47187a', 1, 'Orientação para Construção de Currículo: Chegou a hora de criar um currículo campeão! E é claro que estamos ao seu lado nesse momento! Oferecemos plantões presenciais ou on-line (via Zoom) para conversa, análise e elaboração de currículos, dicas para colocar informações assertivas sobre cada perfil de vaga, além de tirar dúvidas sobre processos seletivos. Para agendar seu horário, acesse o Portal do Aluno e selecione a opção URLs Externas > FECAP+ Desenvolvimento. Se preferir, entre em contato por meio dos canais de atendimento do ASA. Vamos juntos rumo ao seu sucesso!'),
  ('c3d6e7fc-838a-462f-9071-8f2decabe471', '7b7e11f6-ec43-5379-bdf2-94635f47187a', 2, 'Orientação para Construção de Currículo - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('2cca1705-37ea-4c80-a28f-d6aaf7b7306a', '7b7e11f6-ec43-5379-bdf2-94635f47187a', 3, 'Orientação para Construção de Currículo - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('79edb06c-bed9-4d35-b81b-cf17c6b49e6c', '0508bf3c-1bac-56e5-8703-5956a0749094', 1, 'Orientação para Desenvolvimento do LinkedIn: Você já deu o primeiro passo para uma carreira de sucesso: a escolha do seu curso de graduação na FECAP! Agora, é o momento de elaborar um perfil forte e com bom engajamento no LinkedIn. Oferecemos plantões presenciais ou on-line (via Zoom) para aprender como criar um perfil na rede, conteúdos e informações que devem ser colocadas, tipo de linguagem, além de tirar dúvidas sobre processos seletivos. Vamos conversar? Os agendamentos devem ser realizados pelo Portal do Aluno, escolha a opção URLs Externas > FECAP+ Desenvolvimento. Em caso de dúvidas, entre em contato por meio dos canais de atendimento do ASA. Esperamos por você!'),
  ('9a8dd573-5d09-4435-8c4f-fee968f04fa9', '0508bf3c-1bac-56e5-8703-5956a0749094', 2, 'Orientação para Desenvolvimento do LinkedIn - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('37e113c6-2c46-427e-b2ab-9bfd5386ca99', '0508bf3c-1bac-56e5-8703-5956a0749094', 3, 'Orientação para Desenvolvimento do LinkedIn - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('61dbec0c-e18e-4887-8492-da5e80f8613c', 'c487e992-c72f-54d7-b49a-18c8f1f15580', 1, 'Alteração de dados cadastrais: Deseja alterar os seus dados cadastrais, como nome e endereço? Podemos te ajudar! Abra a solicitação pelo seu Portal do Aluno > Requerimento/ Alteração de dados cadastrais ou, se preferir, entre em contato conosco pelos nossos canais de atendimento.'),
  ('13fbd41a-d4b1-468d-9f45-3879440779b6', 'c487e992-c72f-54d7-b49a-18c8f1f15580', 2, 'Alteração de dados cadastrais - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('2daf5ea4-4297-42a3-895e-426637fe37fc', 'c487e992-c72f-54d7-b49a-18c8f1f15580', 3, 'Alteração de dados cadastrais - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta: 09:45h às 13:30 e das 17h às 20h. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('998f924d-775f-49fd-aafe-5fbb4e5e95cd', 'ef63fcb6-5994-5469-ae39-e3c285e9e872', 1, 'Alteração de gênero no registro de matrícula: Seja você com muito orgulho! Você pode solicitar a mudança de gênero no registro de matrícula. Para isso, basta acessar o seu portal Requerimento/ Alteração de gênero no registro de matrícula e realizar a solicitação. E lembre-se, você pode contar sempre conosco por meio dos nossos canais de atendimento.'),
  ('5ea88034-7bd6-44f9-bd03-ec28fcb15740', 'ef63fcb6-5994-5469-ae39-e3c285e9e872', 2, 'Alteração de gênero no registro de matrícula - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f5031907-149e-46e7-b435-d8619f461cc5', 'ef63fcb6-5994-5469-ae39-e3c285e9e872', 3, 'Alteração de gênero no registro de matrícula - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('04e513f5-5410-4dc7-b1df-7ffd6d56b28f', '21a7b25d-9e1c-5bc3-b93b-26042a41a8f5', 1, 'Alteração de responsável financeiro: Precisou alterar seu responsável financeiro? Siga as instruções abaixo: Abra a solicitação pelo Portal do Aluno> Requerimento/Alteração de responsável financeiro e em seguida, anexe as declarações de autorização da transferência de ambas as partes e os documentos do novo responsável financeiro. Fácil, não é?!'),
  ('d58f0f51-9933-4cf2-be81-1cd143438107', '21a7b25d-9e1c-5bc3-b93b-26042a41a8f5', 2, 'Alteração de responsável financeiro - Condições: O estudante deve estar regularmente matriculado e adimplente em todas as mensalidades até o momento da solicitação; O responsável financeiro atual deve autorizar a transferência, por meio de carta assinada e datada; O novo responsável financeiro deve aceitar a transferência e entregar RG, CPF, comprovante de residência, e-mail, telefone e carta de próprio assinada e datada contendo o aceite'),
  ('8777f657-bf70-4ea0-a52a-6160d9a547e5', '21a7b25d-9e1c-5bc3-b93b-26042a41a8f5', 3, 'Alteração de responsável financeiro - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio / Graduação / Mestrado.'),
  ('0f915540-8373-409a-9da1-de7c98ad59bd', '0ab35901-6497-5c6f-b2cf-95acfcff1ca4', 1, 'Alteração de responsável financeiro para Empresa: Deseja alterar o responsável financeiro de pessoa física para jurídica (empresa)? Vamos te explicar como! Abra a solicitação por meio do portal Requerimento/Alteração de responsável financeiro para Empresa, anexando as declarações de autorização da transferência de ambos os responsáveis financeiros e os documentos da pessoa jurídica. Em caso de dúvida, é só nos procurar em um dos nossos canais. Será um prazer te auxiliar!'),
  ('2317867b-2ac2-4153-8f0d-fb04466f3046', '0ab35901-6497-5c6f-b2cf-95acfcff1ca4', 2, 'Alteração de responsável financeiro para Empresa - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('cf5cf7cd-735b-48d1-bf04-ddabea12f5b7', '0ab35901-6497-5c6f-b2cf-95acfcff1ca4', 3, 'Alteração de responsável financeiro para Empresa - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('bbb4df55-f954-4757-8c27-b83696a5545f', '22438636-64a1-5f5b-ba4b-575966f859dd', 1, 'Inclusão de nome social do estudante no registro de matrícula: Na FECAP, o respeito e a igualdade fazem parte do nosso DNA. Se você não se identifica com a sua identidade de gênero e não deseja ser chamad@ por seu nome civil, solicite a inclusão do seu nome social no registro da matrícula por meio do portal Requerimento/Inclusão de nome social do estudante no registro de matrícula. Caso prefira, fique à vontade para falar conosco por meio dos canais de atendimento.'),
  ('1973bec0-9af7-4b85-82e6-23ecb9d73cc3', '22438636-64a1-5f5b-ba4b-575966f859dd', 2, 'Inclusão de nome social do estudante no registro de matrícula - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('57ed8af3-b238-4e8b-8226-e494f2e03a52', '22438636-64a1-5f5b-ba4b-575966f859dd', 3, 'Inclusão de nome social do estudante no registro de matrícula - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('1d436005-e435-4c42-b62a-9c8f382f709a', '30e4dba4-4a4a-5ecf-b364-bbd828dd298e', 1, 'Alteração de contrato de prestação de serviços: Você precisa atualizar algum de seus dados cadastrais, como responsável acadêmico ou financeiro? Não se preocupe! Você pode fazer isso facilmente por meio do Portal do Aluno > Menu > Secretaria/Requerimento > Alteração de Contrato de Prestação de Serviços.'),
  ('e70602a8-3dfb-4c2d-b2a8-f46f209cb8c4', '30e4dba4-4a4a-5ecf-b364-bbd828dd298e', 2, 'Alteração de contrato de prestação de serviços - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('c80ec551-37a0-44e4-838e-34176dc5e4c9', '30e4dba4-4a4a-5ecf-b364-bbd828dd298e', 3, 'Alteração de contrato de prestação de serviços - Atendimento: Setor responsável: Área de Sucesso Alvarista. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('33816751-d2a9-43e0-b1f9-048ffadc5186', '6814cb54-6191-5bb0-8406-2b8bd8aed064', 1, 'Antecipação da Assinatura do Termo de Colação de Grau: Vai fazer intercâmbio ou foi aprovado em concurso e precisa da antecipação da assinatura do termo de colação de grau? Sem problemas, vamos resolver para você! Acesse o seu portal Requerimento/ Antecipação da Assinatura do Termo de Colação de Grau e faça a solicitação explicando a necessidade da antecipação. Caso prefira, fique à vontade para nos procurar em um dos nossos canais de atendimento. Será um prazer te ajudar!'),
  ('1e44bcd1-a1f3-4292-8e83-805ab00bd9e2', '6814cb54-6191-5bb0-8406-2b8bd8aed064', 2, 'Antecipação da Assinatura do Termo de Colação de Grau - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('c327755f-1ec8-4b32-9134-8a1bcf5f9223', '6814cb54-6191-5bb0-8406-2b8bd8aed064', 3, 'Antecipação da Assinatura do Termo de Colação de Grau - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('fe7cca07-861b-40c1-8e27-391c53bc763d', 'bfcab964-f7e5-5cc5-ad54-5171968118b7', 1, 'Atestado Personalizado: Precisou de um Atestado de Matrícula que contenha alguma informação específica nele? Você pode solicitar um Atestado Personalizado e incluir exatamente o que precisa! Veja como é simples: Acesse o Portal do Aluno > Secretaria/Requerimentos > Atestado Personalizado.'),
  ('8946a049-12ce-409a-8f29-bc31e2f80539', 'bfcab964-f7e5-5cc5-ad54-5171968118b7', 2, 'Atestado Personalizado - Condições: Ter registro de aluno ativo no ano da solicitação'),
  ('f61fd564-2866-4c03-950e-932929400937', 'bfcab964-f7e5-5cc5-ad54-5171968118b7', 3, 'Atestado Personalizado - Atendimento: Setor responsável: Área de Sucesso Alvarista. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('fd465821-d079-464d-96d3-9e5592e996e3', '1e68830a-f228-5a41-9724-ce74c0753a72', 1, 'Atestado de comparecimento: Sabemos que você gosta de participar das aulas e atividades, não é mesmo?! Caso precise de um Atestado de Comparecimento, fique tranquilo, é só pedir! Basta acessar o seu Portal do Aluno > Menu > Secretaria/Requerimento > Atestado de comparecimento e preencher a solicitação.'),
  ('aabc8a5c-59b6-4bcd-8869-20cda827ac2c', '1e68830a-f228-5a41-9724-ce74c0753a72', 2, 'Atestado de comparecimento - Condições: 1) Ter comparecido à FECAP ou ter realizado alguma atividade pela FECAP'),
  ('32e96cbf-cad5-402c-a554-93a949f8573f', '1e68830a-f228-5a41-9724-ce74c0753a72', 3, 'Atestado de comparecimento - Atendimento: Setor responsável: Área de Sucesso Alvarista. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('886bcca2-bc58-46c8-8bdf-bd448af1115b', '0c66e0d5-4e7b-56a3-838a-7a44a4405079', 1, 'Atestado de matrícula: Precisa do atestado de matrícula? É super simples: basta acessar o portal, escolher a opção Relatórios e emitir o documento. Ficou com dúvidas? Entre em contato por meio dos nossos canais de atendimento. Será um prazer te ajudar!'),
  ('8bf31878-5577-4a99-852b-a5d068a74a8a', '0c66e0d5-4e7b-56a3-838a-7a44a4405079', 2, 'Atestado de matrícula - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('83ea5ede-d073-4a02-8542-dd0e6a78060f', '0c66e0d5-4e7b-56a3-838a-7a44a4405079', 3, 'Atestado de matrícula - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('3e8bb963-c144-4d91-9bba-2f27216630c5', '19ba9dc6-99be-5891-9bb0-e4ddb2407d71', 1, 'Carta de recomendação da direção: Precisa de uma carta de recomendação autenticada pela FECAP? Basta ir presencialmente à coordenação do Colégio dentro do horário de atendimento e fazer sua solicitação.'),
  ('b9ce0144-9358-4d08-b866-79c00c4050a1', '19ba9dc6-99be-5891-9bb0-e4ddb2407d71', 2, 'Carta de recomendação da direção - Condições: Possuir registro de matrícula'),
  ('ddb86863-b220-4dad-b1f4-0b4ab8287598', '19ba9dc6-99be-5891-9bb0-e4ddb2407d71', 3, 'Carta de recomendação da direção - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: De segunda a sexta-feira, das 07h00 às 18h00. Nível de ensino: Colégio.'),
  ('c749b786-016d-44a6-8bdd-eeaa553961db', '024e3583-3754-5632-a974-c4d1061e6699', 1, 'Certificado de Conclusão – Latu Senso – 2ª via: Caso tenha perdido o seu Certificado de Conclusão da Pós-Graduação, não se preocupe, podemos disponibilizar um novo para você. Para isso, basta realizar a solicitação e efetuar o pagamento da taxa através do seu Portal do Aluno > Menu > Secretaria/Requerimento > Solicitação 2ª via do Certificado da Pós-Graduação e realizar o pagamento da taxa.'),
  ('d5901a7d-1708-47b7-bf2f-dc4c64ea08e6', '024e3583-3754-5632-a974-c4d1061e6699', 2, 'Certificado de Conclusão – Latu Senso – 2ª via - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('357d0233-4d74-4684-a35b-5bd004325c8d', '024e3583-3754-5632-a974-c4d1061e6699', 3, 'Certificado de Conclusão – Latu Senso – 2ª via - Atendimento: Setor responsável: Secretaria Acadêmica. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('b766ed05-8421-47f5-8546-8dd890d11ef7', '8d0d1cbf-eeee-5af0-a4b3-f0d0814cf7f5', 1, 'Certificado de Conclusão – Latu Sensu: Parabéns pela sua formatura, Alvarista! Nós estamos extremamente orgulhosos de você e acreditamos que você está pronto para alcançar grandes realizações. Para solicitar o seu Certificado de Conclusão, basta acessar o Portal do Aluno > Menu > Secretaria/Requerimento > Certificado de Conclusão – Latu Sensu. Aguarde o recebimento do certificado em seu e-mail após a solicitação.'),
  ('fcb6ecac-2ea3-4648-b35e-cc338164940e', '8d0d1cbf-eeee-5af0-a4b3-f0d0814cf7f5', 2, 'Certificado de Conclusão – Latu Sensu - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('087acc0c-b10a-47c8-9c2f-88fa5cf73904', '8d0d1cbf-eeee-5af0-a4b3-f0d0814cf7f5', 3, 'Certificado de Conclusão – Latu Sensu - Atendimento: Setor responsável: Secretaria Acadêmica. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('9cdb07d3-1ec8-465c-8a14-4ecca6da7c99', '301fdf9a-2b88-5e76-8218-cf0531ac3169', 1, 'Certificado de conclusão: Você se formou! Estamos muito orgulhosos, Alvarista! Você está pronto para voar ainda mais alto. Para a emissão do seu certificado de conclusão, faça a solicitação por meio do portal Requerimento/ Certificado de conclusão, e aguarde o recebimento em seu e-mail. Importante: você deve esperar a colação de grau para abrir a solicitação, combinado?! E você já sabe, qualquer dúvida pode continuar contando conosco por meio dos nossos canais de atendimento. Estamos sempre à disposição para te atender!'),
  ('8e4e6f95-ef19-40c5-898a-f38653d8b1af', '301fdf9a-2b88-5e76-8218-cf0531ac3169', 2, 'Certificado de conclusão - Condições: O aluno precisa estar com situação de matrícula "Formado"'),
  ('468a06d0-0e1e-4c71-b6f8-75bbd46c23e1', '301fdf9a-2b88-5e76-8218-cf0531ac3169', 3, 'Certificado de conclusão - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('282fe9b5-8f01-4a24-bab6-91ce1a3725d9', 'a968ee9a-c895-5eb8-9872-a0138af8161c', 1, 'Confecção da Carteirinha – 2ª Via: Perdeu sua carteirinha, Alvarista? Não se preocupe, podemos fornecer uma nova para você pelo custo de R$ 10,00. Basta enviar sua solicitação por meio do Portal do Aluno > Menu > Secretaria/Requerimento > Confecção da Carteirinha da FECAP – 2ª Via. Uma dica importante: se você perdeu sua carteirinha devido a um roubo, apresente o Boletim de Ocorrência para obter a isenção do pagamento da segunda via.'),
  ('0dfc9f84-806e-48fd-9a75-45fa9926eec5', 'a968ee9a-c895-5eb8-9872-a0138af8161c', 2, 'Confecção da Carteirinha – 2ª Via - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('4c7e01b0-1479-44cc-b6eb-e9bf09c52e45', 'a968ee9a-c895-5eb8-9872-a0138af8161c', 3, 'Confecção da Carteirinha – 2ª Via - Atendimento: Setor responsável: Área de Sucesso Alvarista - ASA. Local: Área de Sucesso Alvarista - ASA. Horário de atendimento: Segunda a sexta das 10h às 13h30 e das 17h às 20h. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('26f5443d-fd86-40cf-b0fe-1f663047ba35', '4d097f27-bd01-5355-b125-181c10351575', 1, 'Confecção da carteirinha da FECAP: Parabéns por ser aprovado(a) na FECAP e iniciar um novo capítulo em sua vida acadêmica! Para acessar o campus, é necessário solicitar sua carteirinha de aluno(a) por meio do Portal do Aluno > Menu > Secretaria/Requerimento > Confecção da Carteirinha. Importante: Certifique-se de anexar sua foto frontal com fundo neutro. Estamos ansiosos para recebê-lo(a) em nosso campus e apoiá-lo(a) em sua jornada acadêmica.'),
  ('cb5e3907-d2b0-4cb6-bddf-577992d8a367', '4d097f27-bd01-5355-b125-181c10351575', 2, 'Confecção da carteirinha da FECAP - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('2fd2716e-c7ea-4482-b5ac-4cd00313a42b', '4d097f27-bd01-5355-b125-181c10351575', 3, 'Confecção da carteirinha da FECAP - Atendimento: Setor responsável: Área de Sucesso Alvarista. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('efc15324-d355-461c-9492-047d0b23171c', '736754b4-62d1-51c8-8758-5e18210f107a', 1, 'Correção de Documentos: Caso você tenha recebido ou emitido um certificado de um curso da FECAP com dados incorretos, não se preocupe! Nós fazemos a correção. Basta abrir uma solicitação pelo Portal do Aluno, acessando o Menu e selecionando a opção Secretaria/Requerimento > Correção de Documentos. Não se esqueça de informar qual é o documento e qual(is) é(são) o(s) dado(s) incorreto(s), anexando-o(s) à solicitação. Após a correção do documento, você receberá o novo certificado por e-mail ou pelo próprio Portal do Aluno. Essa situação pode ocorrer em cursos realizados pelo Moodle, cuja emissão é automatizada. Por isso, é fundamental que os(as) estudantes mantenham seus dados cadastrais sempre atualizados.'),
  ('d4e48491-2f57-4a92-9a40-efd3ec0b7ce1', '736754b4-62d1-51c8-8758-5e18210f107a', 2, 'Correção de Documentos - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('5d58f72c-35b0-4b93-bc85-012d5b5e9918', '736754b4-62d1-51c8-8758-5e18210f107a', 3, 'Correção de Documentos - Atendimento: Setor responsável: ASA - Área do Sucesso Alvarista. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('ed764184-fc08-4e2e-92fb-4cb61cd1bdbd', '5aa9dd31-2527-5591-920a-3afe1f2dbb78', 1, 'Crachá – 2ª via: Está sem sua carteirinha? Não tem problema, nós podemos disponibilizar outra para você! Basta nos enviar a sua solicitação por meio do portal Requerimento/ Crachá – 2ª via ou pode nos procurar em um dos nossos canais de atendimento. Estaremos prontos para te ajudar! Uma dica muito importante: caso esteja sem a sua carteirinha por motivo de roubo, basta apresentar o seu Boletim de Ocorrência para obter a isenção do pagamento da 2ª via.'),
  ('6882e5dc-3f83-4a7e-a7ba-c50c6eee5685', '5aa9dd31-2527-5591-920a-3afe1f2dbb78', 2, 'Crachá – 2ª via - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('5b8a3337-57df-4d91-ba0f-15a5b5f54344', '5aa9dd31-2527-5591-920a-3afe1f2dbb78', 3, 'Crachá – 2ª via - Atendimento: Setor responsável: Área de Sucesso Alvarista. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('04be0453-f7a7-4f79-b476-32fd6d7ffa34', '86c6113b-bead-5af5-9616-97b3a9ceb78b', 1, 'Crachá – resolução de problemas: Se você recebeu a sua carteirinha de acesso ao campus e ela apresenta erro ao passar nas catracas, fique tranquilo(a). Pode nos procurar presencialmente no atendimento do ASA para verificarmos o que está acontecendo. Se for necessário, faremos uma nova carteirinha para você.'),
  ('e3216aa3-7aeb-419a-9c55-297a1bdc6386', '86c6113b-bead-5af5-9616-97b3a9ceb78b', 2, 'Crachá – resolução de problemas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ef2bb11a-0357-4a4a-9caa-973b0421ac21', '86c6113b-bead-5af5-9616-97b3a9ceb78b', 3, 'Crachá – resolução de problemas - Atendimento: Setor responsável: Área de Sucesso Alvarista. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('a7c74501-c7d2-4dd1-a255-da68ad422b20', '20423b67-4d52-5dc7-a52e-bfb30310f539', 1, 'Declaração de Conclusão: Você precisa de um documento que comprove sua formação? Nós temos a solução ideal para você! Enquanto espera o seu Certificado de Conclusão, é possível emitir seu Atestado de Conclusão de forma rápida e fácil. Acesse o Portal do Aluno, vá em Menu > Relatórios > Atestado de Conclusão > Emitir Relatório. Caso tenha dúvidas, estamos sempre à disposição para ajudar. Entre em contato conosco pelos nossos canais de atendimento. Queremos estar ao seu lado nessa jornada rumo ao sucesso!'),
  ('f5f1aea9-6bda-4dc6-9d5b-a6f9e8346d7c', '20423b67-4d52-5dc7-a52e-bfb30310f539', 2, 'Declaração de Conclusão - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('7de345ba-5faa-4e88-b124-7e08e199916c', '20423b67-4d52-5dc7-a52e-bfb30310f539', 3, 'Declaração de Conclusão - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('70f32c59-657d-40ca-995d-fa2bd913ae9e', '07f1bb8b-5ff9-5e06-9537-a1ec7431789e', 1, 'Declaração de Escolaridade: Se você já foi aluno(a) do Colégio FECAP e deseja comprovar seu vínculo de escolaridade, o processo é simples: Basta abrir uma solicitação pelo Portal do Aluno > Requerimentos > Declaração de Escolaridade e aguardar o prazo informado. Caso tenha alguma dúvida, entre em contato por meio de nossos canais de atendimento do Colégio.'),
  ('de7fd4a9-78f8-4817-b25c-544ec1450cbc', '07f1bb8b-5ff9-5e06-9537-a1ec7431789e', 2, 'Declaração de Escolaridade - Condições: Ter registro de matrícula ou ter sido estudante regularmente matriculado'),
  ('4de3b3e2-7463-4a53-9fe6-0a95006f3aec', '07f1bb8b-5ff9-5e06-9537-a1ec7431789e', 3, 'Declaração de Escolaridade - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta das 9h00 às 21h00 | Sábado das 09h00 às 12h00. Nível de ensino: Colégio.'),
  ('da4648aa-d19c-472b-9435-d5ab147b5acf', '952c7958-18c1-58ab-a73b-c0e7a343bac3', 1, 'Declaração de Notas: Você precisa de um documento com a relação das disciplinas e a notas? Nós temos a solução ideal para você! Enquanto espera o seu Histórico Escolar, é possível emitir sua Declaração de Notas de forma rápida e fácil. Acesse o Portal do Aluno, vá em Menu > Relatórios > Atestado de Conclusão > Emitir Relatório. Caso tenha dúvidas, estamos sempre à disposição para ajudar. Entre em contato conosco pelos nossos canais de atendimento.'),
  ('bccf8e0b-068e-4ae4-a916-9527a1f8d958', '952c7958-18c1-58ab-a73b-c0e7a343bac3', 2, 'Declaração de Notas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('4a0c51bc-d2c2-4d92-9a90-a9674ca3f810', '952c7958-18c1-58ab-a73b-c0e7a343bac3', 3, 'Declaração de Notas - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('3f24b406-1201-4e33-a72f-fef70c8a3411', 'c2dfbbfd-8aba-5b08-8058-3f00172fae10', 1, 'Entrega de documentos pendentes: Já fez a sua matrícula, mas ainda está com algum documento pendente? Agora ficou mais fácil de regularizar sua situação! – Acesse o Portal do Aluno e role a tela para baixo até o Mural; – Nesta aba você conseguirá visualizar a situação dos seus documentos e enviá-los via anexo no formato PDF. Evite problemas na sua rematrícula e conclusão de curso! Se precisar de ajuda, entre em contato conosco pelos canais de atendimento.'),
  ('01cb183f-5d10-4e34-b496-01908dea75fe', 'c2dfbbfd-8aba-5b08-8058-3f00172fae10', 2, 'Entrega de documentos pendentes - Condições: Ter registro de matrícula e situação de matrícula diferente de Cancelado; Canais digitais, o documento deverá estar escaneado em PDF, não pode ser foto/imagem; Estar no nome do(a) aluno(a) e/ou do seu responsável financeiro'),
  ('2ae01fee-9d46-45b0-993a-ce00b813b71e', 'c2dfbbfd-8aba-5b08-8058-3f00172fae10', 3, 'Entrega de documentos pendentes - Atendimento: Setor responsável: Secretaria. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('5e7abdc1-dbb9-469d-a9cb-2bb3f875e467', 'c01e4aee-5d98-56c1-8e2a-c0cffe33d087', 1, 'Eventos – Solicitação de Certificado: Participou de um dos nossos eventos e deseja o certificado de presença? Entre em contato conosco por meio dos canais de atendimento e nós iremos providenciar. Será um prazer te ajudar!'),
  ('84c7623d-42f5-4d93-b8a0-3edf910ca8d8', 'c01e4aee-5d98-56c1-8e2a-c0cffe33d087', 2, 'Eventos – Solicitação de Certificado - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ff1c6c35-d328-41ee-a5f3-7aa948aa8f8b', 'c01e4aee-5d98-56c1-8e2a-c0cffe33d087', 3, 'Eventos – Solicitação de Certificado - Atendimento: Setor responsável: Pró-Reitoria de Extensão e Desenvolvimento. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('2c072e66-185b-4e1a-b380-8b473bd1e95a', '0e99d4b2-7020-5894-8829-d15c362f8add', 1, 'Validação de Cartão de Ex-aluno: Parabéns, você se formou e recebeu a sua carteirinha dourada de Eterno(a) Alvarista! Lembre-se de validá-la para ter acesso livre e vitalício às instalações dos campi, inclusive às bibliotecas, e usufruir de recursos e serviços da Instituição. Basta comparecer à recepção da FECAP Liberdade e solicitar a validação. Bem-vindo(a) à comunidade Alumni Alvarista!'),
  ('fea8379b-40bc-48f8-bf7d-1af942e535d3', '0e99d4b2-7020-5894-8829-d15c362f8add', 2, 'Validação de Cartão de Ex-aluno - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('552a44eb-60e1-4687-94da-a30a08f91118', '0e99d4b2-7020-5894-8829-d15c362f8add', 3, 'Validação de Cartão de Ex-aluno - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('ca2299e8-4d2b-468f-9731-149470645580', '1ee7cfa4-d5ce-5213-8608-38ec4816b721', 1, 'Carta de Quitação de Débito: Precisa de um documento que declara a quitação de débitos com a FECAP? Basta acessar o Portal do Aluno > Menu > Secretaria/Requerimentos > Carta de quitação de débito e realizar a solicitação.'),
  ('b9aadb02-656c-49e9-baa5-ce390d2d74b6', '1ee7cfa4-d5ce-5213-8608-38ec4816b721', 2, 'Carta de Quitação de Débito - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('5f50acf0-95c5-4ea1-99cf-9f3f4a38d18f', '1ee7cfa4-d5ce-5213-8608-38ec4816b721', 3, 'Carta de Quitação de Débito - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('078be09c-ca24-4051-90aa-f26291bdac7a', '491e60c0-c18a-5814-955b-288281e2af3f', 1, 'Declaração de adimplência: Está com a sua mensalidade em dia e deseja uma Declaração de Adimplência e comprovação de pagamento? Você pode extrair a declaração diretamente pelo Portal do Aluno. Confira como é fácil: abra o Menu e escolha a opção Relatórios, clique em Demonstrativo de Pagamento e selecione o período desejado. Agora é só emitir o relatório! Se preferir, entre em contato por meio dos nossos canais de atendimento. Estamos prontos para te auxiliar!'),
  ('337cd754-1adf-4afb-9d17-26a2d2dedaed', '491e60c0-c18a-5814-955b-288281e2af3f', 2, 'Declaração de adimplência - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('4f593ce3-2c9c-4273-b44f-c1b15f27ff3d', '491e60c0-c18a-5814-955b-288281e2af3f', 3, 'Declaração de adimplência - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('5cd077e2-a603-4031-8674-0e17b9b26bcd', 'c0efcb68-df0a-5d32-9401-d84e17d492aa', 1, 'Declarações Financeiras: Quer ter acesso a declarações financeiras como: Declaração de Quitação de Débitos, Demonstrativo de Pagamento Detalhado, Declaração de Quitação de Cheque, Declaração de Anuência para títulos protestados em cartório, entre outros? Basta acessar o Portal do Aluno > Requerimentos > Declarações Financeiras e fazer sua sua solicitação. Fácil, não é?'),
  ('c7b6d450-5055-43f2-a0f9-989763b3418e', 'c0efcb68-df0a-5d32-9401-d84e17d492aa', 2, 'Declarações Financeiras - Condições: Aluno precisa abrir o atendimento no portal do aluno na opção Secretaria / Requerimentos > Declarações Financeiras > no campo observação especificar (tipo de declaração que deseja, período letivo, parcela, tipo de serviço, entre outras informações)'),
  ('736f64e2-8fa1-424f-b8e9-4c11efa4cd04', 'c0efcb68-df0a-5d32-9401-d84e17d492aa', 3, 'Declarações Financeiras - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('58c4ae33-bbfd-4c79-9ebe-dde7b39a627e', 'ccb47a64-6761-5745-a6f3-aa385f37b169', 1, 'Demonstrativo de Pagamento (IR): Solicitar o Demonstrativo de Pagamento, para fins de Imposto de Renda, é rápido e simples. Confira o passo a passo: acesse o portal do aluno, escolha a opção Relatórios, selecione o período letivo desejado e clique em Emitir Relatório para o documento Demonstrativo de Pagamento no Período Letivo. Caso prefira, entre em contato com a equipe ASA e nós iremos te ajudar.'),
  ('b2118072-291e-4059-821d-f7b81bcf8a1c', 'ccb47a64-6761-5745-a6f3-aa385f37b169', 2, 'Demonstrativo de Pagamento (IR) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('aaadcf12-a889-4403-b297-9da99c8c1477', 'ccb47a64-6761-5745-a6f3-aa385f37b169', 3, 'Demonstrativo de Pagamento (IR) - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('cfe05fc3-77eb-4d8c-a8d4-4f589cf1afa5', '1d0d1df1-dd7b-509e-9627-448a48e3cdbf', 1, 'Eventos – Divulgação do Calendário de Eventos: Não fique de fora da nossa programação de eventos! Na Agenda de Eventos você pode conferir todas as atividades disponíveis, informações e links de inscrição. Além disso, você também fica por dentro de tudo o que está rolando na FECAP pela nossa NewsFECAP!'),
  ('625ccae7-6fce-463c-80ad-b623047b2a33', '1d0d1df1-dd7b-509e-9627-448a48e3cdbf', 2, 'Eventos – Divulgação do Calendário de Eventos - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('484ce935-6240-41f3-b05c-6b794ebc8e71', '1d0d1df1-dd7b-509e-9627-448a48e3cdbf', 3, 'Eventos – Divulgação do Calendário de Eventos - Atendimento: Setor responsável: Marketing. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8cb40c98-e003-4093-8936-0f4833af0739', '9c80befa-36d3-55b0-95fb-5b65264baaa6', 1, 'Eventos – Link do Evento para Inscrição: Você pode conferir todos os links de inscrição na Agenda de Eventos. Ainda assim não achou algum link de inscrição? Entre em contato com a equipe ASA, vamos adorar te ajudar!'),
  ('734dfdb7-2ad6-41dc-b26b-5fa440592185', '9c80befa-36d3-55b0-95fb-5b65264baaa6', 2, 'Eventos – Link do Evento para Inscrição - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('6047ce1a-1a52-46fe-9773-2b74923f7cd8', '9c80befa-36d3-55b0-95fb-5b65264baaa6', 3, 'Eventos – Link do Evento para Inscrição - Atendimento: Setor responsável: Marketing. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('bf9d436e-b65e-48bb-9d6f-e7e4251a59ef', '105ed469-f778-5bae-bb47-e69f80515d74', 1, 'Eventos – Locação de Espaço: Quer realizar um evento, mas não sabe onde? Você pode fazer a locação das áreas comuns da FECAP! Olha só quanta opção bacana para reservar: Teatro, Auditórios, Laboratórios de informática, Sala de Empreendedorismo, Sala de Co-Labor-Ação, Sala de Negociações, entre outros. Envie a solicitação para locacoes@fecap.br, contendo as seguintes informações: nome da empresa, nome do evento, objetivo do evento, data, horário de início e término, número de participantes, público-alvo, espaço desejado, dados completos do estudante solicitante. Em caso de dúvidas, fique à vontade para nos chamar em um dos nossos canais de atendimento. Será um prazer te ajudar!'),
  ('dc276f2e-f00a-4b98-bd8d-f18a0f4f894b', '105ed469-f778-5bae-bb47-e69f80515d74', 2, 'Eventos – Locação de Espaço - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('510469fb-fe0a-4a7a-9ead-530572a9032d', '105ed469-f778-5bae-bb47-e69f80515d74', 3, 'Eventos – Locação de Espaço - Atendimento: Setor responsável: Marketing. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('68f14b4d-5a8e-4c63-bb7c-d3ddb00f3756', 'a8e2dbf3-5eb2-5b12-8a8d-7d5110d63d3f', 1, 'Eventos – Publicação de Notícia: Quer publicar uma notícia para divulgação interna ou externa da FECAP? Envie a sua solicitação para imprensa@fecap.br. Ah, para facilitar a aprovação, lembre-se de mandar o maior número de informações possíveis sobre a notícia, combinado?! Ficou com dúvidas? Entre em contato por meio dos nossos canais de atendimento. Será um prazer te ajudar!'),
  ('943c6335-df50-4c8a-b698-2a4e5c716e3a', 'a8e2dbf3-5eb2-5b12-8a8d-7d5110d63d3f', 2, 'Eventos – Publicação de Notícia - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('734cbf24-0ed9-47e1-a4eb-8d50ba1cacc2', 'a8e2dbf3-5eb2-5b12-8a8d-7d5110d63d3f', 3, 'Eventos – Publicação de Notícia - Atendimento: Setor responsável: Marketing. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8aba3a6c-0183-40c2-b795-dcb2ee3ad174', '2e03c4c3-b439-5255-8537-cf94a85edfe0', 1, 'Eventos – Transmissão nos Canais Digitais Institucionais: Quer transmitir alguma live pelos canais oficiais da FECAP? Envie sua solicitação para o e-mail marketing.digital@fecap.br. Ah, para facilitar a aprovação não esqueça de enviar o maior número de informações possíveis sobre a ação, combinado?! Precisa de ajuda? Entre em contato conosco por meio dos canais de atendimento.'),
  ('96f2e3d6-8fc9-42ea-881c-9e2b1290b3d5', '2e03c4c3-b439-5255-8537-cf94a85edfe0', 2, 'Eventos – Transmissão nos Canais Digitais Institucionais - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('bcae5407-3c8f-4d92-954a-5f9155dfbefc', '2e03c4c3-b439-5255-8537-cf94a85edfe0', 3, 'Eventos – Transmissão nos Canais Digitais Institucionais - Atendimento: Setor responsável: Marketing. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('e317ed98-1c98-4b33-bfb6-4095994f503f', '2eb5cf95-713e-555c-b49d-b850536f12fc', 1, 'Acesso ao Wi-Fi: Você sabia que, na FECAP, você pode ficar sempre conectado? A FECAP conta com uma rede de Wi-Fi pelo Campus todo! Para usufruir deste serviço, é só você acessar o link: https://login.wispot.com.br/ e realizar a autenticação na rede Wi-fi. O login pode ocorrer a partir do registro de matrícula e senha, pela conta Gmail, Facebook ou pelo cadastro do número de celular. Mas, se você tentou conectar e está enfrentando dificuldades de acesso ao Wi-Fi da FECAP? Calma, nós não vamos te deixar sem internet! Procure algum agente da equipe ASA presencialmente e relate a dificuldade enfrentada ou a mensagem de erro exibida. Estamos prontos para te auxiliar!'),
  ('f982082b-1e2a-45d3-a51f-67d30845aa87', '2eb5cf95-713e-555c-b49d-b850536f12fc', 2, 'Acesso ao Wi-Fi - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('40af753e-1d20-4917-91a1-b80b7e916394', '2eb5cf95-713e-555c-b49d-b850536f12fc', 3, 'Acesso ao Wi-Fi - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('5ef5622c-6f54-4322-af7a-cd163234762b', '1571adc5-90a1-5608-9074-2326801ab621', 1, 'Empréstimo de recursos audiovisuais: Quer tornar o seu trabalho da faculdade ainda mais profissional? Aproveite os vários recursos audiovisuais da FECAP, como empréstimo de câmeras fotográficas e filmadoras, além de reservas de estúdio fotográfico ou de rádio e TV. Envie a solicitação de empréstimo de material ou reserva de estúdio para: estudios@fecap.br'),
  ('8e9b3aaf-8e98-48fa-966e-ccbd3a26a938', '1571adc5-90a1-5608-9074-2326801ab621', 2, 'Empréstimo de recursos audiovisuais - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('3c1bfeb8-1343-40ea-b264-e8bc6ba537a6', '1571adc5-90a1-5608-9074-2326801ab621', 3, 'Empréstimo de recursos audiovisuais - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('a6a30772-a579-4d66-822e-bdad812b3f0b', '9e6dd123-aac7-5ebe-aaa6-1f40819b72d9', 1, 'Empréstimo de recursos para acessibilidade: É portador(a) de necessidades especiais e precisa de recursos para adaptação ao curso? Não se preocupe, estamos aqui para te auxiliar! Abra a sua solicitação em Requerimento/ Empréstimo de recursos para acessibilidade. Se preferir, entre em contato por meio dos nossos canais de atendimento. Faremos de tudo para te ajudar em sua jornada!'),
  ('6b0f24cb-dc42-433a-bd8b-c9979532640c', '9e6dd123-aac7-5ebe-aaa6-1f40819b72d9', 2, 'Empréstimo de recursos para acessibilidade - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('0f663dc0-fe8a-4b47-ab6a-44ccb62d6787', '9e6dd123-aac7-5ebe-aaa6-1f40819b72d9', 3, 'Empréstimo de recursos para acessibilidade - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8b07d3ed-58e9-40fb-be3a-549f97e9014f', 'a52d1cad-f65c-5583-975f-bef04dba274a', 1, 'Empréstimo de recursos tecnológicos: Quer uma ajudinha tecnológica para te dar aquela força nos estudos? Na FECAP, você pode realizar empréstimos de tablets, notebooks, Chrome Books e mesas digitalizadoras. Bacana, não é?! Faça a reserva, com até 24h de antecedência, pelo portal do aluno Requerimento/ Empréstimo de recursos tecnológicos. Se preferir entre em contato por meio de um de nossos canais de atendimento. Estamos prontos para te ajudar! Importante: o empréstimo está disponível apenas para uso local, dentro do Campus.'),
  ('c6a2d639-645b-4aa2-ab1c-c1722d700c6f', 'a52d1cad-f65c-5583-975f-bef04dba274a', 2, 'Empréstimo de recursos tecnológicos - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('32796600-8bb0-46ca-a7fe-076797cbf0ef', 'a52d1cad-f65c-5583-975f-bef04dba274a', 3, 'Empréstimo de recursos tecnológicos - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('65d5f4ca-589b-442f-b905-3c41289ca31f', '36ffad77-aff3-52d7-9e92-bcaad5a3b28a', 1, 'Manutenção de Periféricos (teclado, mouse, monitor): A FECAP mantém regularmente a manutenção de todos os materiais, mas caso identifique a necessidade de revisão ou troca de equipamentos, como teclado, mouse ou monitor, localizados nos laboratórios de informática ou salas Co-labs, você pode solicitar o suporte e auxílio no funcionamento. Basta acessar Requerimento/ Manutenção de periféricos ou, se preferir, entrar em contato por meio de um dos nossos canais de atendimento informando qual o material e a necessidade. Estamos prontos para te ajudar!'),
  ('8779f14c-36f4-49ff-a070-73b34bd75b46', '36ffad77-aff3-52d7-9e92-bcaad5a3b28a', 2, 'Manutenção de Periféricos (teclado, mouse, monitor) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('3b563e01-4599-432c-9fb5-eb5f62abd9b5', '36ffad77-aff3-52d7-9e92-bcaad5a3b28a', 3, 'Manutenção de Periféricos (teclado, mouse, monitor) - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('f027b189-e5a2-4238-bb47-740af84dd326', 'd4c6373b-0885-54cb-af7c-c3783778e2bc', 1, 'Refeitório Estudantil: Você sabia que no Colégio FECAP, temos um refeitório? Para sua comodidade, você pode trazer seu almoço, armazenar e esquentá-lo aqui. Mas tem que consumir no mesmo dia, ok?! O refeitório estudantil fica no 2º andar do Bloco B.'),
  ('862300be-8c25-44d9-b344-d12383d5e119', 'd4c6373b-0885-54cb-af7c-c3783778e2bc', 2, 'Refeitório Estudantil - Condições: Ter registro de matrícula'),
  ('a3ef87f6-43f5-433f-aeda-2ba577135f67', 'd4c6373b-0885-54cb-af7c-c3783778e2bc', 3, 'Refeitório Estudantil - Atendimento: Setor responsável: Classe de Primeira Classe. Local: 2° andar - Bloco B. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('4988b14f-942d-4c50-b3be-90b06689db9d', '3ef17acf-d1c9-53c2-877d-bfcd0042f6b3', 1, 'Suporte ao uso de ChromeBook: Está com dúvidas em relação a utilização e funcionamento do Chromebook? Vamos facilitar para você! Procure os agentes de sucesso e nós o ajudaremos com materiais explicativos e resolução das suas dúvidas. Afinal, a nossa meta é o seu sucesso!'),
  ('bd36239e-0367-4708-bb83-200ff660575c', '3ef17acf-d1c9-53c2-877d-bfcd0042f6b3', 2, 'Suporte ao uso de ChromeBook - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('69730ef3-ce3b-4036-9b22-85f376e8de89', '3ef17acf-d1c9-53c2-877d-bfcd0042f6b3', 3, 'Suporte ao uso de ChromeBook - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('11be003e-16d1-4c60-bb94-18665b65f69f', '7a961883-33cc-5b11-8cf5-b605140c4e5b', 1, 'Suporte ao uso local de computadores (Laboratórios de Informática ou Co-labs): Se você está com dificuldades na utilização dos laboratórios de informática ou salas Co-labs, não precisa se acanhar para pedir ajuda. A equipe ASA está disponível para te auxiliar! Basta nos procurar em um dos nossos canais de atendimento.'),
  ('31d67725-ac69-4fe4-b09e-3c2e5c30594d', '7a961883-33cc-5b11-8cf5-b605140c4e5b', 2, 'Suporte ao uso local de computadores (Laboratórios de Informática ou Co-labs) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('674a7c7d-aa65-4232-9c34-0ac165cfc28f', '7a961883-33cc-5b11-8cf5-b605140c4e5b', 3, 'Suporte ao uso local de computadores (Laboratórios de Informática ou Co-labs) - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8944eeee-6f1f-4d21-a6c6-5383b330f5a8', '5d24f93e-b490-5546-818b-135c47a3c81b', 1, 'Suporte para Impressão: Nós sabemos como é chato quando queremos imprimir um documento e acontecem falhas, como papel preso ou insuficiente. Se você encontrou dificuldades nos Totens de impressão, não se preocupe, informe-nos o que aconteceu por meio de um dos nossos canais de atendimento. Estamos prontos para te auxiliar! Importante: para utilizar os serviços de impressão nos Totens é necessário possuir crédito na carteirinha de estudante da FECAP.'),
  ('4646fab4-7d00-44ec-90c0-98fff0607a5c', '5d24f93e-b490-5546-818b-135c47a3c81b', 2, 'Suporte para Impressão - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('097e3e08-a323-4dc4-a80e-5a57e90d6384', '5d24f93e-b490-5546-818b-135c47a3c81b', 3, 'Suporte para Impressão - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('6fd763eb-1ea5-4390-94e7-a8270fe9caa6', '106c0522-d11e-50f3-a91f-2818073a390c', 1, 'Suporte para uso de Laboratórios de Informática (Disponibilidade, Softwares disponíveis): Precisa utilizar algum laboratório de informática ou consultar os softwares disponíveis? Entre em contato conosco por meio de nossos canais de atendimento, e nós te auxiliaremos em relação ao período disponível, horários livres e programas.'),
  ('ebcfcd80-1530-4e3a-8cc3-64973c536179', '106c0522-d11e-50f3-a91f-2818073a390c', 2, 'Suporte para uso de Laboratórios de Informática (Disponibilidade, Softwares disponíveis) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('a3a7374f-36c8-4ce6-b25d-0f8f49e35510', '106c0522-d11e-50f3-a91f-2818073a390c', 3, 'Suporte para uso de Laboratórios de Informática (Disponibilidade, Softwares disponíveis) - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('3868f893-ce26-4f34-b1f6-8ce1c4a4558b', '185caff7-b008-589d-b2ef-0312e6092db4', 1, 'Uso de Bicicletário: Quer fugir do trânsito de São Paulo? Aproveite para ir às aulas de bicicleta. Além de ser um ótimo meio de transporte, faz muito bem à saúde! Na FECAP, você tem à sua disposição o Bicicletário, durante sua permanência no Campus e mediante disponibilidade. Para aproveitar desse serviço, compareça presencialmente na Portaria de Veículos e faça a solicitação. Fique ligado(a): utilize sempre equipamento de proteção, como capacetes e joelheiras e permaneça nas ciclofaixas.'),
  ('32d6d5e9-6b07-428e-b560-3b8f17de9b62', '185caff7-b008-589d-b2ef-0312e6092db4', 2, 'Uso de Bicicletário - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('eb601545-832f-47b1-91ab-5e0a40ee79ae', '185caff7-b008-589d-b2ef-0312e6092db4', 3, 'Uso de Bicicletário - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Recepção Campi Liberdade. Horário de atendimento: Segunda a Sexta, das 6h00 às 22h40 | Sábado, das 07h00 às 18h00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('18f2d282-57d8-4350-9308-08052e5090f4', 'b9857f2e-1f58-52a3-9ebb-d43bff7ed39b', 1, 'Informações sobre Intercâmbio: Deseja realizar o intercâmbio cultural durante o período letivo? Confira as informações do processo: – O(a) estudante que irá realizar o intercâmbio, deve anexar toda a documentação exigida, pessoal (passaporte, vistos, autorizações e vacinas) e acadêmica (Histórico Escolar, Atestado de Matrícula e etc) e acionar a coordenação do Colégio; – A duração máxima para o intercâmbio é de até 6 (seis) meses; – A validação dos estudos realizados no exterior deverá ser validada no retorno ao Brasil, pela Coordenação do Colégio. Ficou com dúvidas? Entre em contato conosco pelos canais de atendimento.'),
  ('dc000072-9ede-41e1-a941-bc54419999db', 'b9857f2e-1f58-52a3-9ebb-d43bff7ed39b', 2, 'Informações sobre Intercâmbio - Condições: Ter registro de matrícula; Estar regularmente matriculado; Preparar toda a documentação exigida, tanto pessoal (passaporte, vistos, autorizações e vacinas) e acadêmicas (Histórico Escolar, Atestado de Matrícula e etc)'),
  ('fee45c6d-2266-4870-b7e0-1807455d5474', 'b9857f2e-1f58-52a3-9ebb-d43bff7ed39b', 3, 'Informações sobre Intercâmbio - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('3bddc6a1-8ad2-4f1a-9f47-ffebec721acd', '9e21af5f-960b-577e-ba49-2769d61f573c', 1, 'Acesso ao Moodle: O Moodle é a nossa ferramenta de estudos, onde você terá acesso ao conteúdo das aulas e às atividades. Por isso, é muito importante que você esteja sempre atento(a) ao Moodle para não perder nada! Seu usuário e senha são os mesmos do Portal do Aluno. Acesse o Moodle pelo Portal do Aluno > Menu > Urls Externas > EAD FECAP-Moodle. Mas, se você está enfrentando dificuldades ou falhas relativas ao acesso ao Moodle, como erro de usuário ou indisponibilidades técnicas, e está precisando de suporte, não se preocupe. Entre em contato conosco por meio do e-mail apoiomoodle@fecap.br, informando seu nome completo, RA e descreva o erro que aparece para você. Será um prazer te ajudar!'),
  ('cae6178e-d5a6-44ad-ae93-6043aafceb8d', '9e21af5f-960b-577e-ba49-2769d61f573c', 2, 'Acesso ao Moodle - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('2cf1a5c2-f2be-4cfd-975f-05ed63218a70', '9e21af5f-960b-577e-ba49-2769d61f573c', 3, 'Acesso ao Moodle - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('2677ee97-b1b3-4da1-8519-252042bd1195', '9b715466-d845-5182-b86d-1de34e8a37e1', 1, 'Acesso ao Portal do Aluno: O Portal do Aluno armazena toda a sua vida dentro da FECAP! Por lá, você tem acesso a documentos, notas, faltas, boletos, vagas, quadro de horários e muito mais! Você também pode abrir requerimentos, como envio de documentos, solicitação da carteirinha FECAP, atividades complementares, entre outros. Acesse o Portal do Aluno pelo link (https://portal.fecap.br/) ou pelo site (https://www.fecap.br/) > Portal do Aluno no canto superior direito. Para entrar no Portal do Aluno (e no Moodle), você utilizará seu Registro de Aluno (RA). Mas, você tentou acessar e está enfrentando dificuldades, como erro de usuário ou indisponibilidades técnicas? Fique tranquilo(a). Entre em contato conosco por meio de nossos canais de atendimento que iremos te ajudar!'),
  ('4f1522ca-1f08-4af4-aeef-127c19e7fb52', '9b715466-d845-5182-b86d-1de34e8a37e1', 2, 'Acesso ao Portal do Aluno - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('d6e8d3b5-5df8-4f59-aae0-268e3048f4a4', '9b715466-d845-5182-b86d-1de34e8a37e1', 3, 'Acesso ao Portal do Aluno - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('9fcddac2-d3da-4f63-858b-0785f4c01671', '9c476061-65ee-5a23-a09c-27d88ac10cfd', 1, 'Acesso ao VPN FECAP (Economática, Bases de Dados da Biblioteca): Se você não está frequentando presencialmente o Campus da Instituição e precisa de ajuda para acesso à rede local da FECAP (VPN), para uso das bases Economática e da Biblioteca, não se preocupe. Confira o tutorial aqui. Caso ainda tenha dúvidas, entre em contato por meio de um dos nossos canais de atendimento e solicite a análise para a resolução da dificuldade enfrentada. Estamos prontos para te ajudar!'),
  ('feda45bc-240f-4799-b45c-3f44829eb7b6', '9c476061-65ee-5a23-a09c-27d88ac10cfd', 2, 'Acesso ao VPN FECAP (Economática, Bases de Dados da Biblioteca) - Condições: É necessário possuir registro de matrícula'),
  ('8fb3fc02-e03b-4426-8a9a-bba033914882', '9c476061-65ee-5a23-a09c-27d88ac10cfd', 3, 'Acesso ao VPN FECAP (Economática, Bases de Dados da Biblioteca) - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('9cdaac1f-7475-4268-8d35-489307db59f0', '03550665-b4ad-51fa-b7fb-bacac412ec81', 1, 'Acesso ao Zoom: Está com dúvidas sobre como acessar e utilizar a plataforma Zoom? Não se preocupe! Preparamos um Tutorial para você. Confira aqui: Tutorial de Acesso ao Zoom.'),
  ('a77e3a63-ce90-4f6a-8901-e9511b5e6bbe', '03550665-b4ad-51fa-b7fb-bacac412ec81', 2, 'Acesso ao Zoom - Condições: É necessário possuir registro de matrícula'),
  ('b6eab763-21fe-416e-984e-f7d3bb564f0b', '03550665-b4ad-51fa-b7fb-bacac412ec81', 3, 'Acesso ao Zoom - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação / Mestrado.'),
  ('8173136c-05e7-4370-a2a7-bf5a1d2ac8af', 'f83be9cf-ae4b-5bdc-98c2-be48541b76ab', 1, 'Acesso ao e-mail FECAP: Você ainda não acessou ou está com dificuldades para acessar o seu e-mail FECAP? Sabia que ele possibilita o acesso a todos os recursos do Pacote Office online e Outlook 365, Teams e a 100GB de armazenamento no OneDrive? Para conseguir todos esses recursos, o seu Portal do Aluno > Menu > Secretaria/Requerimentos > Acesso ao e-mail FECAP e realizar a solicitação.'),
  ('8946a0d1-15d0-4747-8bc6-005982f6a1b2', 'f83be9cf-ae4b-5bdc-98c2-be48541b76ab', 2, 'Acesso ao e-mail FECAP - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9bfe5fda-6872-407f-bcc7-3ea9542b4783', 'f83be9cf-ae4b-5bdc-98c2-be48541b76ab', 3, 'Acesso ao e-mail FECAP - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('197a36fb-3ef1-4100-885a-d51b89634ad5', '40536024-e144-514b-9eee-1d3a75f8ebab', 1, 'Aplicativo EduFECAP: Ei, Alvarista! Já pensou ter todo o seu Portal do Aluno dentro de um só aplicativo? Agora com o EduFECAP, você tem acesso aos seus boletos, notas, e muito mais. Baixe o aplicativo da FECAP pelo Google Play ou Apple Store e tenha mais facilidade no seu dia a dia acadêmico!'),
  ('f9272a35-3473-4355-afb8-8377cccbfea1', '40536024-e144-514b-9eee-1d3a75f8ebab', 2, 'Aplicativo EduFECAP - Condições: Ter um registro de matrícula'),
  ('c5ba8cef-deed-4bba-93b7-fa853384731a', '40536024-e144-514b-9eee-1d3a75f8ebab', 3, 'Aplicativo EduFECAP - Atendimento: Setor responsável: Área de Sucesso Alvarista - ASA. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('85092141-80fc-4acd-a3df-e59338c726cd', 'b0e2838d-f64f-5a51-b620-5db8b4ee648b', 1, 'ClassApp: O ClassApp é o seu aliado na comunicação direta com o Colégio e vida acadêmica do seu filho(a). Para utilizá-lo, basta ter o número do registro de matrícula (RA), baixar o aplicativo pelo Google Play ou Apple Store e solicitar a liberação do acesso com a Coordenação do Colégio.'),
  ('060b62bf-fdd8-45f6-b229-1345a1c6c79e', 'b0e2838d-f64f-5a51-b620-5db8b4ee648b', 2, 'ClassApp - Condições: Ter registro de matrícula'),
  ('15df2878-a5a6-43e8-8908-27b32e28d48f', 'b0e2838d-f64f-5a51-b620-5db8b4ee648b', 3, 'ClassApp - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: De segunda a sexta-feira, das 07h00 às 18h00. Nível de ensino: Colégio.'),
  ('a0f0ea0f-d361-4f56-ae95-5c394da0883e', '51960255-8114-5609-a31f-9fa9382f7765', 1, 'Consulta de Apontamentos na Catraca: Para consultar o histórico de apontamento na catraca, o responsável acadêmico deve entrar no aplicativo EduFECAP com CPF e senha (data de nascimento no formato DD/MM/AAAA) e realizar a consulta dos apontamentos.'),
  ('057465e7-8128-4196-898a-d2b830821b2d', '51960255-8114-5609-a31f-9fa9382f7765', 2, 'Consulta de Apontamentos na Catraca - Condições: Estudante deve ter registro de matrícula; Estudante deve possuir status de “cursando”'),
  ('5691e16a-0203-4e3a-a344-2036452cac7e', '51960255-8114-5609-a31f-9fa9382f7765', 3, 'Consulta de Apontamentos na Catraca - Atendimento: Setor responsável: Coordenação do Colégio. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio.'),
  ('a52872fa-ee93-4e9c-9b9e-893fc8dc1d21', '34862d21-fc5f-5a85-bbea-4302b29eef96', 1, 'Créditos para cantina – GDS School: Você sabia que é possível utilizar o “Sistema GDS School” na cantina do Colégio? Para sua comodidade, você pode realizar seus pedidos on-line pelo celular, utilizando créditos pré-pagos. O cadastro deverá ser solicitado presencialmente pelo responsável e é feito no próprio site. Após a compra, os créditos são inseridos automaticamente no cartão do(a) aluno(a).'),
  ('65daf770-84a9-418d-8111-1986376814d4', '34862d21-fc5f-5a85-bbea-4302b29eef96', 2, 'Créditos para cantina – GDS School - Condições: Ter registro de matrícula; Possuir registro no aplicativo GDS School'),
  ('785e2a5c-eba6-47ed-9545-8572975cefb6', '34862d21-fc5f-5a85-bbea-4302b29eef96', 3, 'Créditos para cantina – GDS School - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: De segunda a sexta-feira, das 07h00 às 18h00. Nível de ensino: Colégio.'),
  ('0cd7398b-b1a1-42f7-835f-f137078c8923', 'b65ea66f-403b-5867-918d-6cf68bec9910', 1, 'Dificuldades Acadêmicas no Moodle: Se você está com dificuldades em relação ao Moodle, como problemas na abertura de arquivos, falta de acesso a alguma atividade, entre outras, não se preocupe. Abra uma solicitação em seu portal Requerimento/Dificuldades Acadêmicas no Moodle informando a dificuldade enfrentada. Você também pode nos procurar em um dos nossos canais de atendimento. Será um prazer te auxiliar! Caso prefira, confira o tutorial do Moodle.'),
  ('e33a9806-6301-4540-81df-e814f20edc03', 'b65ea66f-403b-5867-918d-6cf68bec9910', 2, 'Dificuldades Acadêmicas no Moodle - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e59facd8-6ec8-47ed-8afd-1f5f9989a185', 'b65ea66f-403b-5867-918d-6cf68bec9910', 3, 'Dificuldades Acadêmicas no Moodle - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('cc53c9ab-3977-4593-a412-13a16493cd70', 'a24bc442-3e1f-598f-9181-d089f3ce9852', 1, 'Disciplina Indisponível no Moodle: Entrou no Moodle e reparou que está faltando alguma disciplina? Fique tranquilo(a), vamos resolver essa questão! Abra uma solicitação em seu Portal do Aluno > Menu > Secretaria/Requerimentos > Disciplina Indisponível no Moodle, informando qual(is) disciplina(s) não aparece(m) para você que estaremos prontos para te ajudar!'),
  ('315af981-c037-49a6-9f59-a587c335ee70', 'a24bc442-3e1f-598f-9181-d089f3ce9852', 2, 'Disciplina Indisponível no Moodle - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f6d86e4c-76fc-4dc7-a7e2-d435c3058a50', 'a24bc442-3e1f-598f-9181-d089f3ce9852', 3, 'Disciplina Indisponível no Moodle - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('7fedafa9-5b7f-4ccd-b132-617f0cefd6d4', '80dbe176-48e4-5368-867c-4e204bdec28c', 1, 'Indisponibilidade de serviços on-line (Portal do Aluno, Wi-fi, Office 365, Moodle): Os serviços on-line, como Portal do Aluno, Office ou até mesmo o Moodle, estão indisponíveis? Pode nos procurar em um dos canais de atendimento do ASA para verificarmos o que está acontecendo. Estamos prontos para te auxiliar! Ah, para agilizar o atendimento, informe a mensagem de erro exibida ao tentar acesso.'),
  ('93710a76-7d58-4069-9090-4950251bb96a', '80dbe176-48e4-5368-867c-4e204bdec28c', 2, 'Indisponibilidade de serviços on-line (Portal do Aluno, Wi-fi, Office 365, Moodle) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('c3e69779-097b-422f-8055-f2bc97e7c3bb', '80dbe176-48e4-5368-867c-4e204bdec28c', 3, 'Indisponibilidade de serviços on-line (Portal do Aluno, Wi-fi, Office 365, Moodle) - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8ea1976e-3543-49c5-87ff-8bf3f00f75a4', 'ac170e69-5bb8-5d1a-ad41-e6ff75ab6fa9', 1, 'Office 365: As tecnologias evoluem a todo momento e se você está com dúvidas sobre a utilização da plataforma Office 365 (e-mail, Word, Excel, OneDrive, Teams, entre outros), nós podemos te ajudar! Confira o tutorial aqui. Em caso de dúvidas, envie a sua solicitação de suporte através do portal Requerimento/ Office 365. Se preferir, entre em contato conosco por meio dos canais de atendimento. A equipe ASA está treinada e pronta para solucionar todas as suas dúvidas!'),
  ('b8294edb-0c07-419d-bd3f-3cd325a3bbd7', 'ac170e69-5bb8-5d1a-ad41-e6ff75ab6fa9', 2, 'Office 365 - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('0d736e11-926c-47c7-bfc6-06bf207e6524', 'ac170e69-5bb8-5d1a-ad41-e6ff75ab6fa9', 3, 'Office 365 - Atendimento: Setor responsável: DTI Infraestrutura. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('cc4fb0f5-6c99-4b92-b954-ffe46c909cd6', 'd3c9566b-cae6-51f2-b3b8-8bef052b3333', 1, 'Reserva de Sala: Usufrua da infraestrutura das salas de aula para a realização de reuniões, atividades extras, trabalhos em grupo, orientações e muito mais! Faça a solicitação da reserva diretamente pelo portal Requerimento/ Reserva de Sala ou entre em contato por meio dos nossos canais de atendimento. Lembre-se de informar o nome da atividade, a data e o horário de início e término. Importante: a reserva dependerá da disponibilidade de salas e o limite de término da atividade deverá ser de até 30 minutos antes do início das aulas.'),
  ('40907933-757b-47be-941e-967cd118a619', 'd3c9566b-cae6-51f2-b3b8-8bef052b3333', 2, 'Reserva de Sala - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('8b48348b-7ba7-4a92-8562-56e60e4325d3', 'd3c9566b-cae6-51f2-b3b8-8bef052b3333', 3, 'Reserva de Sala - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('f42d66b5-4b5f-4a03-92b0-4d417c375c5c', '2b884738-2ae7-5b31-80ab-9f06c647963d', 1, 'Atendimento de Primeiros Socorros: Não está se sentindo bem ou presenciou alguma emergência em que será necessário atendimento de primeiros socorros? Entre em contato imediatamente com os canais de atendimento do ASA, informando a situação e local de ocorrência, e nós acionaremos o Bombeiro Civil ou Socorristas para prestar a devida assistência.'),
  ('caad4d20-e4c5-4042-af13-fc7da73358c9', '2b884738-2ae7-5b31-80ab-9f06c647963d', 2, 'Atendimento de Primeiros Socorros - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('5e72cb12-f6f2-48e5-9de0-bd81ac733942', '2b884738-2ae7-5b31-80ab-9f06c647963d', 3, 'Atendimento de Primeiros Socorros - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('acb9b1d8-5db1-4c81-8769-b8c07ab46be8', 'c945e979-f601-5233-bde8-80e1f5f53e77', 1, 'Orientações em caso de incêndio: A FECAP mantém rigorosamente a atualização do AVCB (Auto de Vistoria do Corpo de Bombeiros) e revisa regularmente o projeto técnico de incêndio. Estamos prontos para agir em momentos de crise (princípio de incêndio), com Brigadistas, Socorristas e Bombeiro Civil, orientando os(as) estudantes até o ponto de encontro. Caso presencie alguma situação de risco, informe ao ASA em um de nossos canais de atendimento e nós tomaremos as providências necessárias.'),
  ('db801f0a-167f-4bee-a20a-c3c570f50bcc', 'c945e979-f601-5233-bde8-80e1f5f53e77', 2, 'Orientações em caso de incêndio - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('6df56979-f279-441d-ae47-fd4e0e569f57', 'c945e979-f601-5233-bde8-80e1f5f53e77', 3, 'Orientações em caso de incêndio - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('68b373b0-ddc0-4aaa-8bd3-81d16dad71e2', '4e145e45-aab1-563a-8572-d958d4a0eb5c', 1, 'Participação no CONSEG (Conselho Comunitário de Segurança): Garantir a segurança e tranquilidade da comunidade Alvarista no Campus e redondezas é a nossa prioridade. Dentre as diversas iniciativas de proteção, a equipe de Segurança FECAP participa ativamente das reuniões mensais do Conseg (Conselho Comunitário de Segurança) para desenvolver ações conjuntas e cobrar dos órgãos públicos melhorias de acessibilidade, zeladoria e segurança para a região da Liberdade.'),
  ('5fd46c21-1d4f-4e5e-bc85-fe7c9ac51b42', '4e145e45-aab1-563a-8572-d958d4a0eb5c', 2, 'Participação no CONSEG (Conselho Comunitário de Segurança) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f07af28e-f79e-4ed7-bf83-337e319fb9d6', '4e145e45-aab1-563a-8572-d958d4a0eb5c', 3, 'Participação no CONSEG (Conselho Comunitário de Segurança) - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('2d8058ef-9091-4793-8560-5536163c5908', '88243140-84e3-5071-9469-e9171d025a20', 1, 'Rondas Internas: Presenciou alguma situação inadequada ou em que sentiu a sua segurança e dos demais abalada? Abra uma solicitação pelo portal Requerimento/ Rondas Internas ou comunique ao ASA em um de nossos canais de atendimento, informando local e horário da ocorrência. Iremos providenciar, junto à equipe de Segurança, a ampliação da ronda na área indicada. Estamos prontos para te ajudar e garantir a sua proteção.'),
  ('4871c2cb-3cc9-4681-9821-68b792e6cce5', '88243140-84e3-5071-9469-e9171d025a20', 2, 'Rondas Internas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('8b3b296c-0712-4c89-bc8a-cb39c404119a', '88243140-84e3-5071-9469-e9171d025a20', 3, 'Rondas Internas - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('95acbe5e-8f1e-42c3-a8f3-1a2282b5991f', 'f1f93cd4-9d37-5277-88b2-107efd58429f', 1, 'Sistema de Achados e Perdidos: Como diria a Luna Lovegood, “As coisas que nos pertencem acabam voltando para nós.”, não é mesmo?! Por isso, se você perdeu algo, tenha calma. Abra uma solicitação no portal Requerimento/ Sistema de Achados e Perdido ou compareça à recepção e comunique o item perdido e demais informações, como dia e possível local da perda. Caso o seu item tenha sido encontrado, estará guardado em segurança no depósito de achados e perdidos. Mas atenção, você terá um prazo de até 15 dias para retirada.'),
  ('d074818d-8ef7-45a6-a4be-3d000618a953', 'f1f93cd4-9d37-5277-88b2-107efd58429f', 2, 'Sistema de Achados e Perdidos - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9a67b75c-deeb-4b13-86f3-d1b595655fdb', 'f1f93cd4-9d37-5277-88b2-107efd58429f', 3, 'Sistema de Achados e Perdidos - Atendimento: Setor responsável: Segurança e Gestão de Riscos. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('2c399764-be05-4dd2-a42d-19b9f04820eb', '68457609-deb8-5186-89be-2b9ac7e9cbd5', 1, 'Abono ou Compensação de Faltas: Precisou faltar nas aulas por motivo de saúde, alistamento militar ou outras razões previstas em lei? Calma, nós podemos te ajudar. Envie o atestado e solicite a análise para o abono das faltas pelo Portal do Aluno > Menu > Secretaria/Requerimentos > Abono de Faltas.'),
  ('76f92ac7-27e8-4b05-8da9-811400742924', '68457609-deb8-5186-89be-2b9ac7e9cbd5', 2, 'Abono ou Compensação de Faltas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('afc11d80-7c83-477c-9c67-6ccaf1413994', '68457609-deb8-5186-89be-2b9ac7e9cbd5', 3, 'Abono ou Compensação de Faltas - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('e591e684-a27f-41ce-abaf-55999f301743', 'f378bffe-e318-5aa3-8c4e-92fe73e74e8b', 1, 'Afastamento – Licença Maternidade: Você pode solicitar a Licença Maternidade para a compensação de atividades e faltas. O atestado será válido por 90 dias, a partir da data de entrega do atestado. Para enviar a solicitação acesse o portal Requerimento/ Compensação de faltas – Licença Maternidade ou entre em contato por meio dos nossos canais de atendimento. Será um prazer te auxiliar nesse momento tão importante!'),
  ('b62c2101-5eed-45e1-962a-e989996a542f', 'f378bffe-e318-5aa3-8c4e-92fe73e74e8b', 2, 'Afastamento – Licença Maternidade - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('cdebd8bd-9791-48c3-a13e-945c91d06de1', 'f378bffe-e318-5aa3-8c4e-92fe73e74e8b', 3, 'Afastamento – Licença Maternidade - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação / Mestrado.'),
  ('5664518b-04f6-4716-b104-cf4d1e80afee', '7f95e1f2-dfb5-5bc7-80c5-58e506377396', 1, 'Ajuste de Ponderação: Precisa de alteração na ponderação de algumas disciplinas em virtude de não cursar o PEDP? Solicite por meio do portal Requerimento/ Ajuste de Ponderação. Caso prefira, entre em contato com os canais de atendimento do ASA. Estamos prontos para te ajudar!'),
  ('16dc8610-6976-4b48-930e-f9768ce13504', '7f95e1f2-dfb5-5bc7-80c5-58e506377396', 2, 'Ajuste de Ponderação - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('48744b99-c5ee-4a07-b798-839749318867', '7f95e1f2-dfb5-5bc7-80c5-58e506377396', 3, 'Ajuste de Ponderação - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('64c7fc50-b321-4b68-a9a0-cc2bbc2a39fd', 'b8c8e294-d154-5cdb-b7c5-1b4db825996c', 1, 'Ajustes por sobreposições de disciplinas: Possui disciplinas de semestres anteriores, DP ou adaptações, com horários conflitantes? Não se preocupe, nós podemos te ajudar. Abra uma solicitação no portal Requerimento/ Ajustes por sobreposições de disciplinas, informando qual disciplina deseja cursar e qual deseja alterar o status para “A Cursar”. Se preferir, procure pelo atendimento ASA em um de nossos canais.'),
  ('3973ca01-9267-4705-9b9c-a1e1afc487e1', 'b8c8e294-d154-5cdb-b7c5-1b4db825996c', 2, 'Ajustes por sobreposições de disciplinas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ec865aa5-1965-49c9-80b3-776c069f016d', 'b8c8e294-d154-5cdb-b7c5-1b4db825996c', 3, 'Ajustes por sobreposições de disciplinas - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('9669e7d9-dc78-42aa-b981-2de02cbfbbaa', 'cc22bbc7-c00d-5c7b-9e08-48d0c62a7781', 1, 'Alteração de Disciplinas: Deseja solicitar a alteração de alguma disciplina da sua grade? Basta abrir uma solicitação em seu Portal do Aluno > Menu > Secretaria/Requerimentos > Alteração de Disciplinas – Mestrado. Importante: só será possível solicitar a alteração até a primeira semana de aulas da disciplina.'),
  ('98e36d97-a00e-4741-8f7f-406b979a50d9', 'cc22bbc7-c00d-5c7b-9e08-48d0c62a7781', 2, 'Alteração de Disciplinas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('819ce88b-cece-45ae-86c8-9643612b5456', 'cc22bbc7-c00d-5c7b-9e08-48d0c62a7781', 3, 'Alteração de Disciplinas - Atendimento: Setor responsável: Mestrado. Local: Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Mestrado.'),
  ('40c645b0-d8ba-4435-9cae-2737d69e2b54', '6b5acf22-9bc9-554e-a88e-e643dfaab1bf', 1, 'Alteração de horário de provas (oficial e exame): Imprevistos acontecem e se você não conseguiu realizar suas provas (oficiais e exames), na data e horários pré-estabelecidos, por um motivo previsto em lei, solicite a análise para aplicação de nova prova por meio do portal Requerimento/ Alteração de horário de provas (oficial e exame). Se preferir, entre em contato conosco por meio dos nossos canais. Importante: não esqueça de apresentar o comprovante de impedimento (doenças infectocontagiosas, alistamento militar, licença maternidade etc.) para avaliação da Coordenação.'),
  ('82b84a12-d5e2-4064-9062-454dabbee04b', '6b5acf22-9bc9-554e-a88e-e643dfaab1bf', 2, 'Alteração de horário de provas (oficial e exame) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f130616f-b678-4df4-8364-eced447f9eae', '6b5acf22-9bc9-554e-a88e-e643dfaab1bf', 3, 'Alteração de horário de provas (oficial e exame) - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('c2f95c5f-f7e6-46bf-8f26-3beddad3a232', 'fda315b6-51e0-5cef-bb95-af7304c947d5', 1, 'Alteração do horário do PEDP: A correria está grande e você não está conseguindo encaixar as aulas do PEDP? Respira fundo que nós temos a solução! Solicite uma alteração de horário pelo portal Requerimento/ Alteração do horário do PEDP ou por um dos canais de atendimento do ASA. Vamos adorar te ajudar em sua trajetória de sucesso! Mas lembre-se, o PEDP deve ter outro horário disponível para podermos realizar a alteração.'),
  ('2284c8e5-baf4-48fe-a233-67613d6c21ff', 'fda315b6-51e0-5cef-bb95-af7304c947d5', 2, 'Alteração do horário do PEDP - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9f24fc25-8a48-44fe-a531-b321c6810ff6', 'fda315b6-51e0-5cef-bb95-af7304c947d5', 3, 'Alteração do horário do PEDP - Atendimento: Setor responsável: Secretaria. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('05427d30-fb7e-46d1-a9d5-61dd96711e76', '21c68c6e-d7e6-5ccd-aa85-30f9be6c2032', 1, 'Antecipação de Disciplinas: Possui janelas em sua grade horária e deseja antecipar algumas disciplinas da série seguinte? Isso é possível! Faça a solicitação pelo portal Requerimento/ Antecipação de Disciplina ou entre em contato conosco por meio dos canais de atendimento. Estamos prontos para te ajudar!'),
  ('976dfd2d-9abc-495c-8314-c3ea221a298a', '21c68c6e-d7e6-5ccd-aa85-30f9be6c2032', 2, 'Antecipação de Disciplinas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('af1ed1a5-5569-41b6-9022-99b8ac0dfe41', '21c68c6e-d7e6-5ccd-aa85-30f9be6c2032', 3, 'Antecipação de Disciplinas - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('acfeee4c-6066-4169-b36d-ad1f9bbc635a', '90fa2415-f7bb-5392-aece-66eaedbd2cde', 1, 'Análise de Grade: Decidiu mudar de curso, a matriz curricular foi alterada ou você trancou e resolveu voltar? Nós podemos te ajudar! Para Mudança de curso ou adaptação à nova matriz curricular, acesse o portal Requerimento/Análise de Grade e solicite a análise de grade. Em caso de Retorno, acesse o nosso site. A Coordenação do curso avaliará quais disciplinas deverá cursar e quais serão dispensadas ao longo do curso, assim como o semestre de ingresso. Se ficar com dúvidas, entre em contato conosco por meio dos canais de atendimento. Importante: confira o prazo para solicitação disponível no Manual do Aluno.'),
  ('ebd960f0-ceb5-446a-a596-4ccc02437a00', '90fa2415-f7bb-5392-aece-66eaedbd2cde', 2, 'Análise de Grade - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('646e8e1d-6f6d-4aa7-81ad-e2f2420c8d2f', '90fa2415-f7bb-5392-aece-66eaedbd2cde', 3, 'Análise de Grade - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('fff37c34-aae0-4b0c-9855-d4139273f80b', 'cece73b7-3da0-5ea8-b9b5-cb99a5a22787', 1, 'Aproveitamento de Disciplinas: Deseja solicitar a dispensa de alguma disciplina já cursada na FECAP ou em outra Instituição de Ensino? Basta abrir esta solicitação e anexar o Histórico Escolar e Conteúdo Programático da Instituição de origem. Importante: Só é possível solicitar a dispensa de alguma disciplina realizada em cursos de Pós-graduação. Matérias cursadas em Graduação não são consideradas equivalentes. O prazo para a análise e retorno é de até 15 dias úteis.'),
  ('e35f3fdf-d0b2-4566-84e3-a7893d30cd5f', 'cece73b7-3da0-5ea8-b9b5-cb99a5a22787', 2, 'Aproveitamento de Disciplinas - Condições: 1) Possuir status diferente de cancelado; 2) Caso solicite aproveitamento de estudos, deverá anexar Histórico Escolar e Conteúdo programático do antigo curso no requerimento'),
  ('552f8834-81ed-4336-8e96-9c59670e6df2', 'cece73b7-3da0-5ea8-b9b5-cb99a5a22787', 3, 'Aproveitamento de Disciplinas - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação / Mestrado.'),
  ('854ae1f8-663e-4eba-90cb-4992649d78dd', 'a0000000-0000-0000-0000-000000000007', 1, 'Atestado Médico e Justificativa de Falta: Faltas por motivo de saúde podem ser justificadas com atestado médico enviado em até 48 horas pelo portal do aluno, mas não isentam o estudante do conteúdo e das avaliações perdidas.'),
  ('c9458359-1e16-4791-90a1-ea4656ea14f2', 'a0000000-0000-0000-0000-000000000007', 2, 'Atestado Médico e Justificativa de Falta - Condições: Atestado médico enviado em até 48 horas pelo portal do aluno'),
  ('d42f0cc9-9e44-45b7-8584-5907dffda076', 'a0000000-0000-0000-0000-000000000007', 3, 'Atestado Médico e Justificativa de Falta - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('5e1fd61d-b991-48ec-8f0d-41d1056d043f', '9f8414a4-8548-53b6-b4c5-53bcd1763087', 1, 'Autorização para assistir aulas como ouvinte: Tem curiosidade ou interesse em assistir à aula de alguma disciplina que não está na sua grade? Você pode participar como ouvinte. Bacana, não é?! Faça a sua solicitação pelo portal Requerimento/ Autorização para assistir aulas como ouvinte. Se preferir, entre em contato pelos canais de atendimento ASA. Será um prazer te ajudar nesse pedido especial! Importante: a validação dependerá da autorização da Coordenação.'),
  ('85c9ec90-44fc-4cc3-91bc-55e77d86a9e3', '9f8414a4-8548-53b6-b4c5-53bcd1763087', 2, 'Autorização para assistir aulas como ouvinte - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('2b8eb3ab-7e28-434b-b8f0-a3f82fe9101d', '9f8414a4-8548-53b6-b4c5-53bcd1763087', 3, 'Autorização para assistir aulas como ouvinte - Atendimento: Setor responsável: Secretaria. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('74f9164e-47dc-4382-8551-94dc0bd96149', '1f03fc0a-53a2-5ab4-8149-2495a04df654', 1, 'Autorização para assistir aulas em outro curso: Tem curiosidade ou interesse em assistir às aulas de outro curso? Faça a sua solicitação pelo portal Requerimento/ Autorização para assistir às aulas em outro curso ou entre em contato pelos canais de atendimento do ASA que nós iremos te ajudar com esse pedido especial. Mas lembre-se, a validação dependerá da Coordenação, ok?!'),
  ('0b7d2a79-2400-4a38-a94e-3ff713d758eb', '1f03fc0a-53a2-5ab4-8149-2495a04df654', 2, 'Autorização para assistir aulas em outro curso - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('8189fd9a-79ba-469f-b0b5-e1d212203543', '1f03fc0a-53a2-5ab4-8149-2495a04df654', 3, 'Autorização para assistir aulas em outro curso - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('26937346-3482-4d42-90df-ba0d7c6b3684', '658c0e6f-6208-5e6d-93b1-b53e8d2c13ed', 1, 'Cadastro de atividade complementar: Se você já tem em mãos os certificados/comprovantes das suas atividades complementares, não esqueça de cadastrá-los para contarem como horas, a fim de cumprir o componente curricular obrigatório. Abra a solicitação e anexe os documentos em seu Portal do Aluno Requerimento/ Cadastro de atividade complementar. Se preferir, pode nos procurar em nossos canais de atendimento. Será um prazer te auxiliar Importante: cada curso tem um regulamento sobre qual tipo de atividade é aceita e quantas horas ela equivale. Confira em seu Portal do Aluno, no menu Arquivos.'),
  ('b23f9976-1e9e-4bea-ad25-96948daf62f7', '658c0e6f-6208-5e6d-93b1-b53e8d2c13ed', 2, 'Cadastro de atividade complementar - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('d9321a91-64aa-4e1d-a326-19dc54c82522', '658c0e6f-6208-5e6d-93b1-b53e8d2c13ed', 3, 'Cadastro de atividade complementar - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('ea1db6a7-b17f-404c-98e5-c34f133f27f8', '66666666-6666-6666-6666-666666666666', 1, 'Calendário Acadêmico: O calendário acadêmico completo, com datas de provas, feriados e período de rematrícula, fica disponível na aba Boletim do portal e também no aplicativo institucional.'),
  ('f501decf-cf30-4a74-bba0-ef1c8429b77f', '66666666-6666-6666-6666-666666666666', 2, 'Calendário Acadêmico - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ce7dc6b8-0810-4595-ae1d-f504607db674', '66666666-6666-6666-6666-666666666666', 3, 'Calendário Acadêmico - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('3e25f18b-b432-4367-9786-adb6a709d2e9', '8afdaf24-5a25-5ec9-b3bd-21cd30e087b9', 1, 'Cancelamento de Dispensa de Disciplinas: Foi dispensado(a) de uma disciplina, mas quer aproveitar todo o repertório e aprendizado? Sem problemas! Você pode solicitar o cancelamento da dispensa por meio do portal Requerimento/ Cancelamento de Dispensa de Disciplinas ou nos procurar nos canais de atendimento do ASA. Confira o prazo para solicitação disponível no Manual do Aluno. Atenção: o cancelamento de disciplina dispensada é irreversível, sendo obrigatório ser aprovado(a) por notas e faltas. Caso contrário, ficará como reprovado(a) na disciplina.'),
  ('ee1f6525-ab58-4b0c-9217-ed82e1d32237', '8afdaf24-5a25-5ec9-b3bd-21cd30e087b9', 2, 'Cancelamento de Dispensa de Disciplinas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('eeb11533-f809-4cd4-b11d-8933d6a08fb0', '8afdaf24-5a25-5ec9-b3bd-21cd30e087b9', 3, 'Cancelamento de Dispensa de Disciplinas - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('1ce1a257-0d72-46d1-8ffb-df849c45e4e3', 'a0000000-0000-0000-0000-000000000002', 1, 'Cancelamento de Matrícula: O cancelamento de matrícula é definitivo e diferente do trancamento: encerra o vínculo do estudante com a instituição e não garante direito a retorno automático no futuro.'),
  ('bb4040cc-0456-41e2-b9b4-a4a3ebc593d9', 'a0000000-0000-0000-0000-000000000002', 2, 'Cancelamento de Matrícula - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('19ebd972-ac7a-4fd8-9ffc-1bb642242091', 'a0000000-0000-0000-0000-000000000002', 3, 'Cancelamento de Matrícula - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('4ac11fbc-05e9-4d54-ad18-66bf4c37bb74', '0d897135-540a-5cdc-b7b7-fccef442d730', 1, 'Comprovante de restrição religiosa: Na FECAP, o respeito a liberdade de crença faz parte do nosso dia a dia. De acordo com a Lei nº 13.796 de 03/01/2019, o(a) estudante poderá ausentar-se de provas e aulas marcadas em dias em que, segundo os preceitos da sua religião, seja vedado o exercício de tais atividades. Para remarcação de provas e novas atividades para compensação de faltas, encaminhe a documentação por meio do portal Requerimento/ Comprovante de restrição religiosa. Se preferir, entre em contato por meios dos canais de atendimento. Será um prazer te ajudar!'),
  ('a5c6adea-0a9b-4721-9441-b50938f8eaed', '0d897135-540a-5cdc-b7b7-fccef442d730', 2, 'Comprovante de restrição religiosa - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('91be12e0-6de6-4507-84ca-ee5e2132b141', '0d897135-540a-5cdc-b7b7-fccef442d730', 3, 'Comprovante de restrição religiosa - Atendimento: Setor responsável: Secretaria Acadêmica. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Graduação / Pós-Graduação / Mestrado.'),
  ('553be020-33ad-4a25-968f-3b53e5dc9454', '1e9a73e1-5db7-576a-92f5-83172ed7e3f8', 1, 'Consulta de Faltas: Deseja consultar suas faltas e conferir o limite delas? É fácil! Basta acessar o seu Portal do Aluno > Menu > Aba “Faltas”.'),
  ('16da903c-010d-4ddd-8cde-482f0f1be4d2', '1e9a73e1-5db7-576a-92f5-83172ed7e3f8', 2, 'Consulta de Faltas - Condições: Ter registro de matrícula; Possuir status de “cursando”'),
  ('d6910b28-3e37-49f6-8ed9-a717dc1e164b', '1e9a73e1-5db7-576a-92f5-83172ed7e3f8', 3, 'Consulta de Faltas - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: De segunda a sexta-feira, das 07h00 às 18h00. Nível de ensino: Colégio.'),
  ('a17b7ba4-e45c-449f-a656-f6e74a3ce183', '64fd71c0-ec2a-510b-868a-aa5990c67962', 1, 'Consulta de Notas: Você realizou as avaliações e quer conferir as suas notas? Acesse o Portal do Aluno > Menu > Aba “Notas”. Fácil, não é?!'),
  ('dc7b4b41-c030-4cdc-8177-9690bba0f942', '64fd71c0-ec2a-510b-868a-aa5990c67962', 2, 'Consulta de Notas - Condições: Ter registro de matrícula; Possuir status de “cursando”'),
  ('bbb57e07-5d75-4bec-8610-d9ca9cc2b8df', '64fd71c0-ec2a-510b-868a-aa5990c67962', 3, 'Consulta de Notas - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: De segunda a sexta-feira, das 07h00 às 18h00. Nível de ensino: Colégio.'),
  ('27992546-32df-4036-ad48-86a2bc0268c9', 'cec317a7-4778-5852-9d50-2481c2964975', 1, 'Contestação da Bolsa Melhores Alunos: Não concordou com os critérios aplicados na seleção da Bolsa Melhores Alunos e deseja a revisão da sua turma? Você pode abrir uma solicitação para a Secretaria realizar uma nova análise. Envie para Requerimento/ Contestação da Bolsa Melhores Alunos ou, caso prefira, entre em contato por meio dos nossos canais de atendimento. Estamos prontos para te ajudar!'),
  ('e89231c7-73c6-4751-85ef-96640cf6ceb6', 'cec317a7-4778-5852-9d50-2481c2964975', 2, 'Contestação da Bolsa Melhores Alunos - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e522714c-942b-438c-adda-137e4d84ecee', 'cec317a7-4778-5852-9d50-2481c2964975', 3, 'Contestação da Bolsa Melhores Alunos - Atendimento: Setor responsável: Secretária Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('69e97f9b-e4e3-437c-b7bd-b53d1dd952e7', 'd248f435-7f9c-534b-ad6f-9da0017e744b', 1, 'Cursar apenas DP e/ou Adaptação: Quer fazer uma pausa para cursar apenas as disciplinas de DP e/ou Adaptação? Faça sua solicitação por meio do seu Portal do Aluno > Requerimentos > Cursar apenas DP e/ou Adaptação. O prazo desta solicitação é de até 7 dias úteis para atualização das disciplinas. Caso tenha dúvidas, entre em contato conosco pelos canais de atendimento!'),
  ('ddec3f9f-8acf-4031-953d-38038e4b453a', 'd248f435-7f9c-534b-ad6f-9da0017e744b', 2, 'Cursar apenas DP e/ou Adaptação - Condições: Ter registro de matrícula; Ter disciplinas de períodos letivos anteriores a serem cursadas'),
  ('ccd620e4-d99e-4a39-a0ee-210ef3f5763b', 'd248f435-7f9c-534b-ad6f-9da0017e744b', 3, 'Cursar apenas DP e/ou Adaptação - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio.'),
  ('85201bb6-16e1-452c-bf5f-81ac7f671bcd', '436562c5-d979-5c99-91d1-ba9397784f79', 1, 'DP/Adaptação indisponível no portfólio: Tem alguma DP ou Adaptação que precisa cursar e não estamos oferecendo no momento? Você pode solicitar a abertura de turma diretamente pelo portal Requerimento/ DP/Adaptação indisponível no portfólio ou nos acionar nos canais de atendimento do ASA informando o nome da disciplina. Importante: a validação dependerá se as turmas terão quórum suficiente ou se possuem estudantes formandos matriculados. E já anota na agenda: as aulas de DP/Adaptação ocorrem aos sábados. Confira o prazo para solicitação disponível no Manual do Aluno.'),
  ('b87b12b7-3feb-48f1-8e16-82db7dbe50e7', '436562c5-d979-5c99-91d1-ba9397784f79', 2, 'DP/Adaptação indisponível no portfólio - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('fec0720a-68a9-4648-bb58-8cea77558983', '436562c5-d979-5c99-91d1-ba9397784f79', 3, 'DP/Adaptação indisponível no portfólio - Atendimento: Setor responsável: Pró-Reitoria de Graduação. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('2ad3c058-7636-406c-84b9-2c336efabfdb', '0cf64e8e-b632-5e0a-a569-c4871a996305', 1, 'Destrancamento de Curso: Se você trancou o curso, mas mudou de ideia e quer retornar no mesmo período letivo, agora você pode solicitar e reverter o trancamento por meio do portal Requerimento/ Destrancamento do Curso ou por um dos canais de atendimento do ASA. Estamos felizes em tê-lo(a) de volta! Importante: confira o prazo para solicitação disponível no Manual do Aluno.'),
  ('2fa6caf2-d915-4881-ac1f-fdeaa0b948d8', '0cf64e8e-b632-5e0a-a569-c4871a996305', 2, 'Destrancamento de Curso - Condições: Estudante deve ter situação de matrícula "Trancado"'),
  ('2ce768ab-7213-4383-8328-5df876b59112', '0cf64e8e-b632-5e0a-a569-c4871a996305', 3, 'Destrancamento de Curso - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação / Mestrado.'),
  ('84e87bc5-2183-4043-8c01-94ed7da22adb', '2746bc40-b08f-5a23-941f-833bad553629', 1, 'Destrancamento de DP e Adaptação: Mudar de ideia faz parte da vida. Se você trancou alguma disciplina de DP ou adaptação e deseja voltar a cursar no mesmo período letivo, faça a sua solicitação por meio do portal Requerimento/ Destrancamento de DP e adaptação. Se preferir, fale conosco por meio de um dos canais de atendimento do ASA. Importante: confira o prazo para solicitação disponível no Manual do Aluno.'),
  ('d2cb0ed5-bae3-4bee-a7b7-1f374ab897ba', '2746bc40-b08f-5a23-941f-833bad553629', 2, 'Destrancamento de DP e Adaptação - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('8bc9b291-1cd0-4b05-8a34-f973fa789230', '2746bc40-b08f-5a23-941f-833bad553629', 3, 'Destrancamento de DP e Adaptação - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('ea837ab9-3854-47e9-b6c4-86e2fc0e858e', '9b954f73-f602-5aba-8854-03cd12d9a1f9', 1, 'Dificuldades para realização de Provas Oficiais/Exame On-line: Sabemos que imprevistos acontecem, sejam eles por queda de energia, instabilidade de internet, entre outros. E se no dia da sua P.O. isso aconteceu, não se preocupe, você pode enviar a sua solicitação pelo portal Requerimento/Dificuldades para realização de P.O. Informe-nos o que aconteceu para que seja possível a avaliação. Se preferir, pode nos procurar em um dos nossos canais. Estamos prontos para te auxiliar! Lembre-se de anexar o seu comprovante ou print da dificuldade enfrentada, ele será importante para a análise.'),
  ('7d9e791d-91eb-427a-bea5-604ad9ffd3a2', '9b954f73-f602-5aba-8854-03cd12d9a1f9', 2, 'Dificuldades para realização de Provas Oficiais/Exame On-line - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('7d3a3b77-cf72-43dc-ab98-e5d258dd75ed', '9b954f73-f602-5aba-8854-03cd12d9a1f9', 3, 'Dificuldades para realização de Provas Oficiais/Exame On-line - Atendimento: Setor responsável: Secretaria. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('f8f2e779-0352-4225-a6ae-07ab1976f392', '543910bf-6704-52db-8398-4b9c38352ea3', 1, 'Disciplinas Isoladas (Ex-alunos): Um bom filho a casa torna, não é mesmo? Se você é Alumni Alvarista e deseja cursar algumas disciplinas adicionais da grade de cursos da FECAP, faça a sua solicitação por meio do portal Requerimento/ Disciplinas Isoladas (Ex-alunos). Se preferir, pode nos procurar por meio dos nossos canais de atendimento. Vamos adorar te receber novamente!'),
  ('d27f1572-4c43-4923-a33f-3e800cb15aff', '543910bf-6704-52db-8398-4b9c38352ea3', 2, 'Disciplinas Isoladas (Ex-alunos) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('057cd49f-d765-4d59-a1dd-ed76f693da40', '543910bf-6704-52db-8398-4b9c38352ea3', 3, 'Disciplinas Isoladas (Ex-alunos) - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('c21d89a4-7862-4f8c-a2c4-2a06a6347cb0', '3ba65844-74b0-5738-9a37-a108cf561025', 1, 'Disciplinas em Inglês – Equivalência de Disciplina Eletiva: Você foi aprovado(a) em alguma disciplina em inglês do nosso curso de extensão. Parabéns! Agora você pode solicitar a validação da equivalência para uma disciplina eletiva por meio do seu portal Requerimento/ Disciplinas em Inglês – Equivalência de Disciplina Eletiva. Ficou com dúvidas? Fique à vontade para falar conosco por meio dos canais de atendimento.'),
  ('d8585d0c-cad6-460b-8a4c-ce1292fbb5f4', '3ba65844-74b0-5738-9a37-a108cf561025', 2, 'Disciplinas em Inglês – Equivalência de Disciplina Eletiva - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9c5d0d86-7baf-4836-84c3-5981683cf93c', '3ba65844-74b0-5738-9a37-a108cf561025', 3, 'Disciplinas em Inglês – Equivalência de Disciplina Eletiva - Atendimento: Setor responsável: Pró-Reitoria de Extensão e Desenvolvimento. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('e03a849d-54c0-4090-8201-35a2ad6964ad', '30c5dbea-f4dc-569e-8f7c-62128cae32c1', 1, 'Disciplinas em Inglês – Validação de Horas Complementares: Sabia que as disciplinas em inglês do curso de extensão podem contar como horas complementares? Para isso, após aprovado(a) na matéria, abra a solicitação da validação da carga horária do curso como horas complementares por meio do portal Requerimento/ Disciplinas em Inglês – Validação de Horas Complementares. Se ficar com dúvidas, fique à vontade para nos chamar em um dos nossos canais de atendimento.'),
  ('903b3521-9b15-49e9-b8e4-734b78bd8e13', '30c5dbea-f4dc-569e-8f7c-62128cae32c1', 2, 'Disciplinas em Inglês – Validação de Horas Complementares - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('3c1705c9-44fd-42ec-8097-8eac4aefad2c', '30c5dbea-f4dc-569e-8f7c-62128cae32c1', 3, 'Disciplinas em Inglês – Validação de Horas Complementares - Atendimento: Setor responsável: Pró-Reitoria de Extensão e Desenvolvimento. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('8d5eee23-07de-4cc0-98a1-0a7c6ba1a05a', '90feb424-44bf-5ad8-80b5-530339624c8b', 1, 'Disciplinas extracurriculares: Deseja cursar outras disciplinas fora do seu curso ou com outra ênfase? É uma ótima opção para horas complementares, além de agregar na sua formação acadêmica. Para requisitar, basta acessar Requerimento/ Disciplinas extracurriculares ou entrar em contato por meio dos nossos canais de atendimento. Estamos prontos para te auxiliar! Atenção: disciplinas extracurriculares são pagas.'),
  ('31215772-8a1b-4d9d-8816-850a7a0f25ba', '90feb424-44bf-5ad8-80b5-530339624c8b', 2, 'Disciplinas extracurriculares - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('657ec46c-a578-48d0-8335-a93118b3c9c6', '90feb424-44bf-5ad8-80b5-530339624c8b', 3, 'Disciplinas extracurriculares - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('358802a6-feee-4dbe-80a2-4f9b23e607ce', '2a8e8a00-b84e-5a7e-9a94-61f2e31ed7b6', 1, 'Dispensa de disciplina: Deseja solicitar a dispensa de uma disciplina já cursada na FECAP ou em outra Instituição de Ensino? Para requisitar, basta abrir uma solicitação em seu portal Requerimento/ Dispensa de disciplina. Se preferir, nos procure em um dos nossos canais informando qual disciplina deseja dispensar. Afinal, seu sucesso também é o nosso! Importante: se você cursou a disciplina em outra Instituição de Ensino deverá apresentar o Histórico Escolar e Conteúdo Programático da Instituição de origem. Atenção: confira o prazo para solicitação disponível no Manual do Aluno.'),
  ('16b3e9c8-2ee8-49a2-b298-e4db36a3a522', '2a8e8a00-b84e-5a7e-9a94-61f2e31ed7b6', 2, 'Dispensa de disciplina - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('29f149f5-2974-4cbf-bd73-44a6f39cbabd', '2a8e8a00-b84e-5a7e-9a94-61f2e31ed7b6', 3, 'Dispensa de disciplina - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('ca3e670d-2712-4ebc-9c97-633ccb459a3f', 'fa8858ed-9f33-5331-882e-9c3058ed4d00', 1, 'Inclusão no Nivelamento: Quer participar do programa de nivelamento (Matemática e Português) oferecido aos estudantes do primeiro e segundo semestre, porém as aulas já estão em andamento e você ainda não está inscrito? Solicite sua inclusão no Programa pelo portal Requerimento/ Inscrições de nivelamento fora do prazo ou procure por um dos agentes de sucesso em nossos canais. Confira o cronograma abaixo: NIVELAMENTO I O Nivelamento I de Língua Portuguesa e de Matemática para os(as) alunos(as) dos primeiros semestres dos cursos de Graduação começam dia 25/03/2023. As Provas Finais serão presenciais em 27/05 (sábado), período matutino, reserve esta data. Confira o regulamento aqui. NIVELAMENTO II O Nivelamento II de Língua Portuguesa e de Matemática para os(as) alunos(as) dos segundos semestres dos cursos de Graduação começam dia 25/03/2023.'),
  ('40a6313b-c8cb-4f09-9288-c37be59da3e5', 'fa8858ed-9f33-5331-882e-9c3058ed4d00', 2, 'Inclusão no Nivelamento: As Provas Finais serão presenciais em 27/05 (sábado), período matutino, reserve esta data. Confira o regulamento aqui.'),
  ('23a0c684-b6f4-4828-8284-4db1e875de9e', 'fa8858ed-9f33-5331-882e-9c3058ed4d00', 3, 'Inclusão no Nivelamento - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e32be266-63fa-48ac-83ae-45fc202c4d3a', 'fa8858ed-9f33-5331-882e-9c3058ed4d00', 4, 'Inclusão no Nivelamento - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('43cb870a-99ae-4672-a8dd-420380385ea2', '36d8bcc5-8e67-5052-8a07-8ecc9f119938', 1, 'Ingressantes – 1° Reunião de Pais: No início do ano, o Colégio realiza a 1° reunião de pais para alinhamento do ano letivo. É de suma importância o comparecimento, para tirar dúvidas e ficar por dentro de tudo que a FECAP oferece. A data será previamente divulgada através do ClassApp e calendário escolar.'),
  ('351092e1-7d23-47e7-8c52-33c32d760e59', '36d8bcc5-8e67-5052-8a07-8ecc9f119938', 2, 'Ingressantes – 1° Reunião de Pais - Condições: Ter registro de matrícula; Estar regularmente matriculado'),
  ('80040f23-3a23-4422-8721-aebd4a110267', '36d8bcc5-8e67-5052-8a07-8ecc9f119938', 3, 'Ingressantes – 1° Reunião de Pais - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('64d60b4d-cb6f-4611-88e9-16df94764ae1', 'f98a71b2-56ba-5465-8f7a-ac09c8a4636d', 1, 'Ingressantes – Lista de Material: Quer ficar por dentro da lista de materiais didáticos e começar o ano letivo sem pendências? Acesse o link > https://www.fecap.br/colegio-fecap-materiais-didaticos e confira! Você também pode acessá-lo pelo ClassApp ou EduFECAP.'),
  ('88413fed-6596-4ec3-a7e1-36fe4c23e74e', 'f98a71b2-56ba-5465-8f7a-ac09c8a4636d', 2, 'Ingressantes – Lista de Material - Condições: Ter registro de matrícula; Estar regularmente matriculado'),
  ('e8549045-503a-494a-8d4e-9836f6e60fb2', 'f98a71b2-56ba-5465-8f7a-ac09c8a4636d', 3, 'Ingressantes – Lista de Material - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('23073254-c32d-49b1-bd1a-eafb559182c5', '8c91518c-c09c-5111-a9a5-95ea16738332', 1, 'Inscrições PEDP (fora do prazo): As aulas do PEDP já iniciaram e você ainda não está inscrito? Então corra para enviar a sua solicitação e não ficar de fora! Acesse o portal Requerimento/ Inscrições PEDP (fora do prazo) ou entre em contato com a equipe de atendimento ASA por um de nossos canais. Será um prazer te auxiliar!'),
  ('0b099e1f-4c93-4785-bfcc-87cca6803bc2', '8c91518c-c09c-5111-a9a5-95ea16738332', 2, 'Inscrições PEDP (fora do prazo) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('2eaa8786-f85f-4929-a067-812012c3e76a', '8c91518c-c09c-5111-a9a5-95ea16738332', 3, 'Inscrições PEDP (fora do prazo) - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('db4a6064-6b8f-4526-baee-06bf21959979', 'cdf61672-4de7-5517-bc98-a87df1c21e48', 1, 'Lançamento de Notas Pendentes: Está com alguma nota pendente? Seja ela de disciplinas regulares, de PEDP, Nivelamento, entre outras, acesse o portal na opção Requerimento/ Lançamento de Notas Pendentes. Sua solicitação será recebida pela nossa coordenação e será avaliada. Se preferir, você pode nos procurar em um dos nossos canais. Estamos prontos para te auxiliar!'),
  ('a661c8d1-8853-4c41-8c84-102b9d11b359', 'cdf61672-4de7-5517-bc98-a87df1c21e48', 2, 'Lançamento de Notas Pendentes - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('b7072c20-0340-409e-9eb7-0a011f614d4f', 'cdf61672-4de7-5517-bc98-a87df1c21e48', 3, 'Lançamento de Notas Pendentes - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('659a8cee-20ae-43fc-98a0-ae635eeb97c2', 'c2005389-b591-5c8d-b409-b63d9fe22417', 1, 'Locação de Armário: Aqui no Colégio FECAP, disponibilizamos armários para que os estudantes utilizem durante o período em que estiverem na instituição. Para garantir seu armário, abra uma solicitação pelo Portal do aluno> Secretaria >Requerimentos > Chave do armário Colégio. A solicitação terá andamento mediante pagamento da taxa de R$50,00 e assinatura do termo de autorização pelo responsável do(a) aluno(a).'),
  ('de27f893-4fc7-4f15-a1ef-b1119bbda694', 'c2005389-b591-5c8d-b409-b63d9fe22417', 2, 'Locação de Armário - Condições: Ter registro de matrícula; Efetuar o pagamento da taxa; Responsável deve assinar termo de autorização para uso do armário'),
  ('a61933f2-a6db-4d58-bb16-a411d905cde3', 'c2005389-b591-5c8d-b409-b63d9fe22417', 3, 'Locação de Armário - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Coordenação do Colégio. Nível de ensino: Colégio.'),
  ('15043f04-ff91-417b-a404-cca829182d7c', '1ddc1e1f-c421-5e0b-82e7-28d61a2e5f77', 1, 'Nome do aluno não consta na lista de presença: Notou que seu nome não está na lista de presença? Estamos aqui para resolver essa questão! Você pode enviar a sua solicitação pelo portal Requerimento/Nome não consta na lista de presença ou, em caso de dúvidas, nos procure por meio de um dos nossos canais de atendimento.'),
  ('51466e21-3e42-48e9-bc60-8c31a8c03ddc', '1ddc1e1f-c421-5e0b-82e7-28d61a2e5f77', 2, 'Nome do aluno não consta na lista de presença - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('aa8732d6-49d5-4c76-b99d-5d12f629448a', '1ddc1e1f-c421-5e0b-82e7-28d61a2e5f77', 3, 'Nome do aluno não consta na lista de presença - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('6b98ff90-e29e-48f7-882d-d95d7c561e00', '95da738b-da09-5328-807f-c4d6aa122fcd', 1, 'PEDP | Revisão de provas: O Sufoco de provas e PEDP passou, mas não ficou feliz com o critério usado e gostaria que o professor realizasse uma nova análise? Vamos te ajudar! Você pode solicitar a revisão da sua prova diretamente com a coordenação pelo portal Requerimento/Revisão de provas ou, se preferir, nos procure em um dos nossos canais.'),
  ('01c25eb2-060b-443a-9ee3-d0be54e8589c', '95da738b-da09-5328-807f-c4d6aa122fcd', 2, 'PEDP | Revisão de provas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('214ca88d-1d7a-4c31-8d3d-e88cd4a6818d', '95da738b-da09-5328-807f-c4d6aa122fcd', 3, 'PEDP | Revisão de provas - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('65643f99-2a1a-4fbb-8c3f-6865bcf9eaee', '99663c42-312f-5e84-8851-3852a25cf2ee', 1, 'Prova Substitutiva: Teve algum imprevisto e não compareceu no dia da prova? Abra sua solicitação de Prova substitutiva pontuando qual(is) prova(s) perdeu e realizar o pagamento da taxa de R$50,00. Através do Portal do Aluno > Requerimentos > Solicitação de Prova Substitutiva. Em até 7 dias úteis, após o pagamento do boleto, você será avisado sobre o dia e horário para realizar a nova prova.'),
  ('b5dd8eea-50b4-4212-af97-83beeffec575', '99663c42-312f-5e84-8851-3852a25cf2ee', 2, 'Prova Substitutiva - Condições: Ter registro de matrícula; Realizar a solicitação através dos canais indicados; Realizar o pagamento da taxa'),
  ('d084fdd8-224c-4b13-8b90-22a9e79daaf3', '99663c42-312f-5e84-8851-3852a25cf2ee', 3, 'Prova Substitutiva - Atendimento: Setor responsável: Coordenação do Colégio. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta-feira, das 08:00 às 21:00 e aos sábados, das 09:30 às 13:00. Nível de ensino: Colégio.'),
  ('edcb272a-b6a5-4945-8280-e4e5f514802f', 'd30c5c5d-d8a1-5e75-b2e7-db5cfcb64cc7', 1, 'Prova Substitutiva com abono: Perdeu alguma prova por motivos de saúde? Fique tranquilo(a)! Você pode solicitar a prova substitutiva mediante apresentação do atestado médico. Abra sua solicitação pelo Portal do Aluno > Requerimentos > Solicitação de Prova Substitutiva com abono. Em até 7 dias úteis, seu documento será analisado, e, se deferido, você será avisado sobre o dia e horário para realizar a prova.'),
  ('c9ae9463-e679-4ab9-904b-9d2ee02c6a68', 'd30c5c5d-d8a1-5e75-b2e7-db5cfcb64cc7', 2, 'Prova Substitutiva com abono - Condições: Ter registro de matrícula; Realizar a solicitação através dos canais indicados; Anexa o atestado médico no requerimento'),
  ('ada61663-dad5-4f92-ba5f-c9fa3a95d3d9', 'd30c5c5d-d8a1-5e75-b2e7-db5cfcb64cc7', 3, 'Prova Substitutiva com abono - Atendimento: Setor responsável: Coordenação do Colégio. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta-feira, das 08:00 às 21:00 e aos sábados, das 09:30 às 13:00. Nível de ensino: Colégio.'),
  ('0e69bf7c-59e1-4146-b5d1-2d010342ec7e', '1781e0a3-0a00-533a-956d-b04cd8bfb821', 1, 'Reagendamento de provas por sobreposições de horários: Se você está cursando adaptações ou dependências e as provas estão coincidindo o horário, não se preocupe, você pode requisitar o reagendamento de data/turno de uma delas. Solicite por meio do portal Requerimento/Reagendamento de provas por sobreposições de horários ou, se preferir, nos procure nos canais de atendimento do ASA. Faremos de tudo para te ajudar a ter sucesso em suas provas!'),
  ('4b6979dc-e4f8-4512-9e80-0a245830d5d7', '1781e0a3-0a00-533a-956d-b04cd8bfb821', 2, 'Reagendamento de provas por sobreposições de horários - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('4e16e231-b4f1-45c1-80e7-997320700096', '1781e0a3-0a00-533a-956d-b04cd8bfb821', 3, 'Reagendamento de provas por sobreposições de horários - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('0b46e77f-7d84-4f9c-ae74-94837a292a4b', 'd8107551-a192-57fa-ac98-7ea411d7b2d1', 1, 'Reconsideração de Resultados e Recursos: Deseja realizar o pedido de reconsideração de Resultados e Recursos do ano letivo? Para isso, o responsável pelo estudante deve fazer a solicitação junto à direção da Coordenação do Colégio. Observações: para realizar a reconsideração, o(a) aluno(a) deve possuir a frequência mínima de 75% nas aulas; – O pedido deverá ser feito em até 10 dias úteis da divulgação dos resultados; – O prazo para a reconsideração pode levar até 30 dias úteis.'),
  ('2958e8ea-0d60-439f-9a16-f3c0d38359ec', 'd8107551-a192-57fa-ac98-7ea411d7b2d1', 2, 'Reconsideração de Resultados e Recursos - Condições: Ter registro de matrícula; Possuir a frequência mínima exigida de 75%; O pedido deverá ser protocolado na escola em até 10 dias da divulgação dos resultados; O prazo de análise da Coordenação ficará suspenso nos períodos de férias e de recessos escolares'),
  ('56d96dd3-6e8b-481b-bc79-9963679bb158', 'd8107551-a192-57fa-ac98-7ea411d7b2d1', 3, 'Reconsideração de Resultados e Recursos - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('479fca99-a82d-41b0-9a26-8aede54d8093', 'a11d1ffa-2a38-58db-9c0f-1c55e18f4585', 1, 'Remanejamento de disciplinas: Possui janelas em sua grade horária e deseja remanejar disciplinas de DP ou adaptação? Sem problemas! Basta fazer a solicitação por meio do portal Requerimento/ Remanejamento de disciplinas. Se preferir, entre em contato por meio dos nossos canais de atendimento, informando o nome da disciplina que deseja remanejar, indicando o curso, dia da semana e horário.'),
  ('2b1e4663-2a0b-45ec-ba71-b66f3a2168c9', 'a11d1ffa-2a38-58db-9c0f-1c55e18f4585', 2, 'Remanejamento de disciplinas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('b048dbe1-3822-489d-960e-96e3b5411e74', 'a11d1ffa-2a38-58db-9c0f-1c55e18f4585', 3, 'Remanejamento de disciplinas - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('bcb0f90a-5fdb-45be-b668-da0548760367', 'e1b22c41-d859-5a7b-8c54-8259c3d7cc44', 1, 'Rematrícula: Agora a rematrícula é AUTOMÁTICA! Assim que você é aprovado(a), o boleto de rematrícula já fica disponível no Portal do Aluno > Financeiro, para pagamento até o dia o 07/01.'),
  ('c549ee92-3c5f-4b87-ac46-b19f09a89f14', 'e1b22c41-d859-5a7b-8c54-8259c3d7cc44', 2, 'Rematrícula - Condições: Não possuir débitos financeiros referentes ao ano letivo anterior'),
  ('9d8406c5-c8f2-495f-add1-63f0777125a2', 'e1b22c41-d859-5a7b-8c54-8259c3d7cc44', 3, 'Rematrícula - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio / Graduação.'),
  ('c0d0bead-0ff0-480e-ace6-546707da0472', '8fdd1642-c972-5e8a-9e23-72a79e4cac64', 1, 'Rematrícula Antecipada: Quer garantir um desconto na sua primeira mensalidade do próximo ano? No mês de novembro, você pode antecipar sua rematrícula e, assim, garantir o desconto aplicado na campanha vigente, sem o reajuste do valor da 1° mensalidade do próximo ano. Entre em contato com o Colégio pelos canais de atendimento e saiba mais!'),
  ('09a52de9-c784-4891-a864-60685393f9f7', '8fdd1642-c972-5e8a-9e23-72a79e4cac64', 2, 'Rematrícula Antecipada - Condições: Não possuir débitos financeiros pendentes'),
  ('21c51d87-83a2-4396-ab50-c72092dfc206', '8fdd1642-c972-5e8a-9e23-72a79e4cac64', 3, 'Rematrícula Antecipada - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta-feira, das 08:00 às 21:00 e aos sábados, das 09:00 às 13:00. Nível de ensino: Colégio.'),
  ('200a3d62-25a1-483b-bffb-bb6bfb36eb58', '96be4945-e3c8-508d-95ea-6a0555387cf2', 1, 'Rematrícula fora de Época: Imprevistos acontecem e se você necessita realizar a sua rematrícula fora da época, faça a solicitação via portal Requerimento/ Rematrícula fora de época. Mas corra, não perca a chance de continuar vivendo os melhores anos da sua vida! Se tiver alguma dúvida, fique à vontade para nos procurar por meio dos nossos canais de atendimento. Atenção: matrículas feitas fora do prazo podem resultar em faltas lançadas retroativamente e atividades avaliativas não revalidadas. Por isso, garanta sempre a sua rematrícula em dia!'),
  ('166fc580-546f-40fa-8e56-3a540132f7de', '96be4945-e3c8-508d-95ea-6a0555387cf2', 2, 'Rematrícula fora de Época - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('234a657d-b312-4570-854e-1bc8f08948e6', '96be4945-e3c8-508d-95ea-6a0555387cf2', 3, 'Rematrícula fora de Época - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado.'),
  ('09487254-f702-4803-97a6-ba35f7a851c9', '55555555-5555-5555-5555-555555555555', 1, 'Reprovação por Frequência: O estudante que ultrapassar 25% de faltas em qualquer disciplina fica automaticamente reprovado por frequência, independente da nota obtida.'),
  ('45600059-4a10-42c8-b7eb-9716f1d1faee', '55555555-5555-5555-5555-555555555555', 2, 'Reprovação por Frequência - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('b784b460-2105-4a7a-9fd1-4c825d1ca091', '55555555-5555-5555-5555-555555555555', 3, 'Reprovação por Frequência - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('e037840a-ee03-4972-ab15-302fbc11ecc3', 'd2a74317-953a-5374-83f6-d98c0f3b8c7b', 1, 'Reunião com a Coordenação de Curso: Quer bater um papo com a Coordenação do curso? Tirar suas dúvidas, entender mais sobre a profissão ou compartilhar suas necessidades. A Coordenação está pronta para te ouvir! Basta acessar Requerimento/ Reunião com a Coordenação de Curso ou procurar a equipe ASA em nossos canais de atendimento que nós iremos te auxiliar.'),
  ('bdf1fbd5-7d77-41dd-949d-5e8ca8772e96', 'd2a74317-953a-5374-83f6-d98c0f3b8c7b', 2, 'Reunião com a Coordenação de Curso - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f631020e-535d-45b2-8654-a3e21b30bff0', 'd2a74317-953a-5374-83f6-d98c0f3b8c7b', 3, 'Reunião com a Coordenação de Curso - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a Sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('bda298d6-eb28-489f-815e-b34698a53d70', '601b9517-5acf-56ab-952c-22e58c8398ff', 1, 'Reversão de Trancamento de Disciplina: Você trancou uma disciplina, mas mudou de ideia e resolveu voltar a cursar ainda este semestre? Solicite o destrancamento da disciplina por meio do Portal do Aluno > Menu > Secretaria/Requerimentos > Reversão de Trancamento – Pós. Importante: após a solicitação, a Coordenação irá orientá-lo(a) com maiores informações.'),
  ('3f0eb204-d8ea-4612-9c75-dbe35af1592f', '601b9517-5acf-56ab-952c-22e58c8398ff', 2, 'Reversão de Trancamento de Disciplina - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('dd2e52dd-fd84-415f-aec9-bfe36e768b54', '601b9517-5acf-56ab-952c-22e58c8398ff', 3, 'Reversão de Trancamento de Disciplina - Atendimento: Setor responsável: Pós-graduação. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('9dbd901e-2505-4a42-b594-f0b5c0390c1c', '21bc2278-09ba-5672-b3c3-f867fc8e56fc', 1, 'Reverter Cancelamento do curso: Você cancelou o seu curso, mas pensou melhor e resolveu ficar na FECAP? Essa é uma notícia maravilhosa! Você pode solicitar e reverter o seu cancelamento por meio do portal Requerimento/Reverter o cancelamento do curso ou por um dos canais de atendimento do ASA. Será um enorme prazer te atender.'),
  ('73659199-94f2-42d0-b997-057d74a31bb2', '21bc2278-09ba-5672-b3c3-f867fc8e56fc', 2, 'Reverter Cancelamento do curso - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('756eea32-bd36-47e6-b75d-52de000a82f7', '21bc2278-09ba-5672-b3c3-f867fc8e56fc', 3, 'Reverter Cancelamento do curso - Atendimento: Setor responsável: Área de Sucesso do Alvarista. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Pós-Graduação / Mestrado.'),
  ('3e4edde2-746d-40c0-a9e8-61fa7cfa634c', '089e200a-28bb-5c67-9c7c-129bd43323ea', 1, 'Solicitação de Boleto: Não recebeu o seu boleto, sua bolsa/desconto não está devidamente cadastrado ou precisa realizar algum ajuste? Abra este requerimento descrevendo qual é o problema que está enfrentando para que possamos verificar. Estamos disponíveis para te ajudar!'),
  ('476e673f-2d04-4d66-9089-bd329378c2e1', '089e200a-28bb-5c67-9c7c-129bd43323ea', 2, 'Solicitação de Boleto - Condições: Ter registro de matrícula'),
  ('640b57b9-99f6-48e7-a875-fffb8d4c8af8', '089e200a-28bb-5c67-9c7c-129bd43323ea', 3, 'Solicitação de Boleto - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('1eb7fb5b-9e14-4b70-a987-770adf5484c2', '03f8e14a-8727-5d87-b518-4513fd19e683', 1, 'Solicitação de DP: Você chegou no final do curso, mas ainda possui uma DP? Não deixe de cursá-la! Para isso, solicite o cadastro dela por meio do seu Portal do Aluno > Menu > Secretaria/Requerimentos > Solicitação de DP – Pós.'),
  ('6afc7a60-7ee3-4485-bd3e-ea09d47932a4', '03f8e14a-8727-5d87-b518-4513fd19e683', 2, 'Solicitação de DP - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('88493851-5496-44d7-82a1-d5adece90a9b', '03f8e14a-8727-5d87-b518-4513fd19e683', 3, 'Solicitação de DP - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('37a38507-9ee7-4d52-92b5-655c7f3ad736', '6bee45e4-d90b-598a-ad4f-fc4522b3e0ad', 1, 'Solicitação de Exame: As avaliações passaram e você não conseguiu atingir a média final 7,0? Não se preocupe, pois ainda dá tempo de recuperar com a Prova de Exame. Caso você seja da modalidade EAD, a Prova Exame terá uma data específica a ser realizada. Caso estude na modalidade Flex, Presencial, Live ou Semipresencial, sua prova será agendada para uma data confirmada via e-mail. Para isso, solicite a realização da Prova Exame pelo seu Portal do Aluno > Menu > Secretaria/Requerimentos > Solicitação de Exame – Pós Graduação. Importante: O prazo máximo para a solicitação da Prova do Exame é de 30 dias corridos após o encerramento da disciplina. Para realização da prova de exame a FECAP poderá cobrar uma taxa administrativa.'),
  ('2370ac51-f92c-458b-9b54-5613dd634752', '6bee45e4-d90b-598a-ad4f-fc4522b3e0ad', 2, 'Solicitação de Exame - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('95373bf4-46b1-4696-9cfd-30ccd444a22f', '6bee45e4-d90b-598a-ad4f-fc4522b3e0ad', 3, 'Solicitação de Exame - Atendimento: Setor responsável: Pós-graduação. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('241abfc2-8aee-4a4a-b464-3a0aa843b8d5', '57e983cf-2d44-53a9-a358-8995cbdb45f6', 1, 'Solicitação de Transferência: Vários fatores influenciam na escolha de um curso e de modalidade, não é mesmo? E se, por acaso, você decidiu mudar, vamos apoiar a sua decisão. Você pode solicitar a transferência interna de curso por meio do Portal do Aluno > Menu > Secretaria/Requerimentos > Solicitação de Transferência.'),
  ('8331b8bf-5b7f-4971-9164-805a55b9cba8', '57e983cf-2d44-53a9-a358-8995cbdb45f6', 2, 'Solicitação de Transferência - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('cb811c82-6c6d-4cae-8c89-10f690185ef9', '57e983cf-2d44-53a9-a358-8995cbdb45f6', 3, 'Solicitação de Transferência - Atendimento: Setor responsável: Pós-graduação. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('27336a80-333d-40a3-a981-92f55fd39808', 'a0000000-0000-0000-0000-000000000004', 1, 'Trabalho de Conclusão de Curso (TCC): O Trabalho de Conclusão de Curso (TCC) deve ser iniciado no penúltimo semestre do curso, com orientador definido até o final do primeiro mês de aula, e entregue conforme cronograma da coordenação.'),
  ('011c81ff-da66-4bd6-a35f-4bd7724225e3', 'a0000000-0000-0000-0000-000000000004', 2, 'Trabalho de Conclusão de Curso (TCC) - Condições: Iniciar no penúltimo semestre do curso; orientador definido até o final do primeiro mês de aula'),
  ('27053105-bc5a-4c9a-af04-2297af61be8c', 'a0000000-0000-0000-0000-000000000004', 3, 'Trabalho de Conclusão de Curso (TCC) - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('c14ecf1c-efcf-4842-9c80-516068e8f0c1', '9187a226-4aca-59c8-94de-3cb0dc040640', 1, 'Tradução Juramentada do Histórico Escolar: Você gostaria de realizar a tradução juramentada do seu Histórico Escolar? É fácil! Basta comparecer a um cartório ou junta comercial com o seu Histórico Escolar oficial assinado que o estabelecimento em questão realizará a tradução juramentada do documento. Caso você tenha o Histórico Escolar no formato digital, mas cartório aceite somente o documento impresso, para obter o seu Histórico Escolar Impresso, acesse o Portal do Aluno > Menu > Secretaria/Requerimentos > Histórico Escolar – 2a. Via. Importante: a emissão deste documento requer um custo de R$ 10,00 e o prazo para conclusão da solicitação é de 20 dias úteis.'),
  ('a73f601c-f9e8-4f46-a02b-0c6fc862b320', '9187a226-4aca-59c8-94de-3cb0dc040640', 2, 'Tradução Juramentada do Histórico Escolar - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('26d5d21e-6cab-4546-98cc-bbfc30e4e7e0', '9187a226-4aca-59c8-94de-3cb0dc040640', 3, 'Tradução Juramentada do Histórico Escolar - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('78556d29-9622-4043-9a77-c641f9e13b8b', '31e8ee5d-e165-5d94-8a3c-4bc22799ba3f', 1, 'Trancamento de Disciplina: Deseja solicitar o trancamento de alguma disciplina da sua grade? Basta abrir uma solicitação em seu Portal do Aluno > Menu > Secretaria/Requerimentos > Trancamento de Disciplina. Importante: Caso solicite o trancamento do TCC ou Soft Skills, fique atento(a) ao prazo divulgado pela Coordenação no início do curso.'),
  ('8d56c369-e55a-4755-9bfd-98879c4a99e1', '31e8ee5d-e165-5d94-8a3c-4bc22799ba3f', 2, 'Trancamento de Disciplina - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('d05b95ed-60f1-4be0-8435-5e4805661301', '31e8ee5d-e165-5d94-8a3c-4bc22799ba3f', 3, 'Trancamento de Disciplina - Atendimento: Setor responsável: Secretaria Acadêmica. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('1aa08979-7562-4023-a8d7-f14737ce247f', '33333333-3333-3333-3333-333333333333', 1, 'Trancamento de Matrícula: O trancamento de matrícula deve ser solicitado com 15 dias de antecedência do início do semestre e pode impactar bolsas ou financiamentos ativos.'),
  ('665fdee3-56c5-474e-bc20-761c06446c98', '33333333-3333-3333-3333-333333333333', 2, 'Trancamento de Matrícula - Condições: Solicitar com 15 dias de antecedência do início do semestre'),
  ('b2658986-def5-413b-b009-782fb7f7092f', '33333333-3333-3333-3333-333333333333', 3, 'Trancamento de Matrícula - Atendimento: Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('0f363dca-162a-46f6-a2ba-0a1ee759ffa2', '3f092677-960f-53d1-a415-a47e8cdc2d3b', 1, 'Trancamento/Cancelamento de Disciplina: Deseja solicitar o trancamento de alguma disciplina da sua grade? Basta abrir uma solicitação em seu Portal do Aluno > Menu > Secretaria/Requerimentos > Trancamento/Cancelamento de Disciplina. Importante: Você pode fazer esta solicitação a qualquer momento, desde que não tenha excedido o limite de faltas (25% da carga horária da disciplina).'),
  ('589974aa-581f-4cf6-833b-a7a41678f16d', '3f092677-960f-53d1-a415-a47e8cdc2d3b', 2, 'Trancamento/Cancelamento de Disciplina - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('98e20426-25e9-42f9-9d3c-3a0c8f131631', '3f092677-960f-53d1-a415-a47e8cdc2d3b', 3, 'Trancamento/Cancelamento de Disciplina - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Mestrado.'),
  ('6659a09d-ddc1-4f62-be44-5aaf214f8c00', '38220fb3-a932-58e3-b16a-6b43ef87fefd', 1, 'Transferência de turma: Deseja trocar de turma por algum motivo? É simples! Procure a coordenação do Colégio e dê início à solicitação. Caso tenha vaga na turma desejada, o(a) aluno(a) será orientado(a). Se tiver alguma dúvida, entre em contato conosco pelos canais de atendimento.'),
  ('5990f03e-30fe-48af-aaee-f5da63cb8eb5', '38220fb3-a932-58e3-b16a-6b43ef87fefd', 2, 'Transferência de turma - Condições: Ter registro de matrícula; Ter o aval da Orientação educacional'),
  ('aa889ca7-5d41-4896-b525-3707db5572d5', '38220fb3-a932-58e3-b16a-6b43ef87fefd', 3, 'Transferência de turma - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio / Graduação.'),
  ('6db2932e-6630-4b40-bb49-724747eb5ef5', 'ab316807-b21b-5d7e-91d2-86b2e8f969c7', 1, 'Transferência de turno: Está com dificuldades para frequentar o curso no seu turno? Se por algum motivo deseja trocar de horário (Matutino ou Noturno), fique tranquilo(a), podemos te ajudar a realizar a mudança! Você pode abrir a solicitação para análise no portal Requerimento/ Transferência de turno. Se preferir, é só nos procurar em um dos nossos canais. Faremos de tudo para lhe ajudar em sua jornada.'),
  ('e852b979-e428-47aa-b328-d720130ad399', 'ab316807-b21b-5d7e-91d2-86b2e8f969c7', 2, 'Transferência de turno - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('50f4d99d-5d4b-4bf2-90b8-777a05dd7fe4', 'ab316807-b21b-5d7e-91d2-86b2e8f969c7', 3, 'Transferência de turno - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('fe509c5c-7af0-417a-956c-a8fd2c883f50', '35cb34e0-18ce-5682-b1d1-4f119d361933', 1, 'Transferência de ênfase/eletivas: Nem sempre as nossas escolhas permanecem as mesmas até o final do curso, não é mesmo? Se você deseja trocar de eletiva ou é estudante de Ciências Econômica e deseja trocar de ênfase, fique tranquilo(a), podemos analisar e realizar a mudança, caso esteja dentro do prazo! Envie sua solicitação pelo portal Requerimento/ Transferência de ênfase/eletivas ou entre em contato conosco por meios dos canais de atendimento. Estamos prontos para te ajudar! Atenção: poderá ocorrer ajuste em sua ficha financeira.'),
  ('01a8f6a2-6b6c-43e6-bb78-094ef7c74fba', '35cb34e0-18ce-5682-b1d1-4f119d361933', 2, 'Transferência de ênfase/eletivas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('b809b49c-730b-4aa3-8cc9-eeb0d7f06e95', '35cb34e0-18ce-5682-b1d1-4f119d361933', 3, 'Transferência de ênfase/eletivas - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('2bb28e54-3e83-4bd6-8018-d878bed60e8e', '0a6d3b57-d937-5256-8549-eda30d68dc86', 1, 'Transferência interna de curso (Turmas a partir do 2ºsemestre): Vários fatores influenciam na escolha de um curso, não é mesmo? E se, por acaso, você decidiu mudar, vamos respeitar a sua decisão. Você pode requisitar a transferência interna de curso por meio do portal Requerimento/ Transferência interna de curso. Vale lembrar que será realizada a análise de grade para verificar quais disciplinadas poderão ser aproveitadas no novo curso. Se preferir, entre em contato conosco por meio dos canais de atendimento. Estamos comprometidos com o seu sucesso!'),
  ('b495c619-5012-4af3-a133-112fadaaa24a', '0a6d3b57-d937-5256-8549-eda30d68dc86', 2, 'Transferência interna de curso (Turmas a partir do 2ºsemestre) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e615ce93-b6c3-409a-a2ab-6824ba923984', '0a6d3b57-d937-5256-8549-eda30d68dc86', 3, 'Transferência interna de curso (Turmas a partir do 2ºsemestre) - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('9b43109a-bb14-4b7b-805f-a39738f5b817', 'a7c48090-b9fb-5403-96f7-6fec70ef19f7', 1, 'Transferência interna de curso (Turmas do 1º semestre): Ainda está no primeiro semestre e não sentiu identificação com o curso? Fique tranquilo(a), nós podemos te ajudar a encontrar um curso que combine mais com você e realizar a mudança. Para solicitar a transferência interna de curso, acesse o portal Requerimento/ Transferência interna de curso. Se preferir, entre em contato conosco por meio dos canais de atendimento. Conte com a gente em seu caminho até o topo! Atenção: estudantes bolsistas do ProUni não podem transferir de curso no primeiro semestre da concessão da bolsa.'),
  ('6bebe3c3-8063-49cf-8d9e-6f1f4840fd55', 'a7c48090-b9fb-5403-96f7-6fec70ef19f7', 2, 'Transferência interna de curso (Turmas do 1º semestre) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('b849ce8c-d7ce-487a-aba9-8429cc696927', 'a7c48090-b9fb-5403-96f7-6fec70ef19f7', 3, 'Transferência interna de curso (Turmas do 1º semestre) - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('4b959f5d-4ac5-4325-8299-02037fe9ea4b', 'ea3bda4f-10d0-5234-b0ca-d254897e07af', 1, 'Vista de Prova de Exame: A correria das provas já acabou, mas você não concordou com os critérios usados na avaliação e deseja a revisão da nota? Vamos te ajudar! Você pode enviar a solicitação por meio do portal Requerimento/ Vista de Prova de Exame ou nos procurar nos canais de atendimento do ASA.'),
  ('1b8a578b-5d86-4188-974f-ffe5e78b61b7', 'ea3bda4f-10d0-5234-b0ca-d254897e07af', 2, 'Vista de Prova de Exame - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('388d14e3-dd96-441b-8744-e6bc97aa51a5', 'ea3bda4f-10d0-5234-b0ca-d254897e07af', 3, 'Vista de Prova de Exame - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('a7db6180-101c-4e32-a3b7-1ee3b8edea7e', '071a0c38-4bc1-56cd-b880-8ee1815e8b70', 1, 'Disciplinas Isoladas (Aluno de Instituições Parceiras e Não-Parceiras): Se você é estudante de outra instituição, mas deseja cursar uma ou mais disciplinas na FECAP, vamos adorar te receber! Entre em contato conosco por meio dos nossos canais de atendimento, indicando a disciplina que deseja cursar. Estamos prontos para te auxiliar. Importante: poderá ocorrer cobrança por disciplina ou por proporcionalidade de carga horária.'),
  ('33da46d0-a1ab-4b13-992c-98434dd53411', '071a0c38-4bc1-56cd-b880-8ee1815e8b70', 2, 'Disciplinas Isoladas (Aluno de Instituições Parceiras e Não-Parceiras) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('0273be89-e8f1-4c0f-a13f-794cd581d1a3', '071a0c38-4bc1-56cd-b880-8ee1815e8b70', 3, 'Disciplinas Isoladas (Aluno de Instituições Parceiras e Não-Parceiras) - Atendimento: Setor responsável: Coordenação de Curso. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('fa465bd4-7dd3-4f49-86f3-6cf91cebc564', 'b7b03a2c-3526-5cd6-b9cc-b890c81fd2fc', 1, 'Disciplinas Isoladas (Alunos Estrangeiros): Estudantes internacionais de instituições parceiras podem solicitar o ingresso em uma ou mais disciplinas da grade de cursos de graduação da FECAP. Para isso, entre em contato por um dos nossos canais de atendimento. Será um prazer ser a sua instituição de ensino no Brasil!'),
  ('2db0adb5-2202-4772-9013-ea0e5eea7734', 'b7b03a2c-3526-5cd6-b9cc-b890c81fd2fc', 2, 'Disciplinas Isoladas (Alunos Estrangeiros) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('9f3596ee-0166-41b6-b7be-ab4a57c6e12b', 'b7b03a2c-3526-5cd6-b9cc-b890c81fd2fc', 3, 'Disciplinas Isoladas (Alunos Estrangeiros) - Atendimento: Setor responsável: International Office. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('e69f0e8a-3e89-4cc8-960b-3e50882910e2', '1af7c2c5-fada-5f74-83ae-4de1b022e590', 1, 'ProUni: Concessão: Você foi pré-selecionado(a) e aprovado(a) no ProUni. Parabéns! Ficamos felizes que você nos escolheu como a sua Instituição de Ensino. Fique ligado(a) aos seus meios de comunicação, você será orientado(a) sobre a entrega dos documentos por e-mail ou contato telefônico. Boa sorte! Lembre-se, em caso de dúvidas estamos sempre prontos para te ajudar!'),
  ('23e7a80b-5b93-484a-be39-05ee20ae7934', '1af7c2c5-fada-5f74-83ae-4de1b022e590', 2, 'ProUni: Concessão - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('6fad678e-10d1-4b5f-919d-c7b4291ab2a2', '1af7c2c5-fada-5f74-83ae-4de1b022e590', 3, 'ProUni: Concessão - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('7df987d6-9ce9-489b-9568-c3ba99ab3049', '9c79633b-3c71-50e6-9a83-c4e4e0fc7284', 1, 'ProUni: Concessão (lista de espera): Está inscrito(a) na lista de espera do ProUni? Fique atento(a) ao seu e-mail e telefone, a Secretaria Acadêmica entrará em contato para solicitar a entrega da documentação. Boa sorte! Lembre-se, em caso de dúvidas, fique à vontade para entrar em contato conosco por meios dos nossos canais de atendimento.'),
  ('af8a932c-2e4e-4acb-864e-2adb9707760d', '9c79633b-3c71-50e6-9a83-c4e4e0fc7284', 2, 'ProUni: Concessão (lista de espera) - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('1cbb5cbd-415c-473f-ac3e-bbb4d7dccefd', '9c79633b-3c71-50e6-9a83-c4e4e0fc7284', 3, 'ProUni: Concessão (lista de espera) - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('8478b6ec-d2d9-493d-85a4-9e8207ca52c4', '51b180f0-0df4-594f-8e40-a3c13b19b9a0', 1, 'Abatimento de valores de Disciplinas em Inglês: Você decidiu realizar alguma disciplina em inglês por meio dos nossos cursos de extensão e foi aprovado(a). Isso é maravilhoso! Você pode solicitar a sua restituição em forma de abatimento de mensalidades ou até mesmo realizar outro curso de extensão. Basta abrir a sua solicitação pelo portal Requerimento/Abatimento de valores de Disciplinas em Inglês ou pode nos procurar por meio dos canais de atendimento do ASA. Estaremos disponíveis para te ajudar!'),
  ('a84d1de3-a1c8-45e4-b1d0-16085cae8dfa', '51b180f0-0df4-594f-8e40-a3c13b19b9a0', 2, 'Abatimento de valores de Disciplinas em Inglês - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f5511660-3702-406e-943c-0544c38a23a2', '51b180f0-0df4-594f-8e40-a3c13b19b9a0', 3, 'Abatimento de valores de Disciplinas em Inglês - Atendimento: Setor responsável: Extensão. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação.'),
  ('4a6bc5b5-5e7a-4881-9ca0-7d516d6c791a', '9a94efe5-5518-5d44-bea6-e7536b70f710', 1, 'Adesão ao Programa Parcelamento FECAP: A FECAP oferece aos alunos regularmente matriculados no Mestrado o Programa de Parcelamento da FECAP, que permite o parcelamento de 40% da mensalidade do curso para pagamento após a conclusão do mesmo. A solicitação deste serviço deve ser feita pelo Portal do Aluno > Menu > Secretaria/Requerimentos > Adesão ao Programa Parcelamento FECAP. Confira o Regulamento do Programa Parcelamento FECAP.'),
  ('41dd4d47-5e3b-4874-8d84-d380316d5f94', '9a94efe5-5518-5d44-bea6-e7536b70f710', 2, 'Adesão ao Programa Parcelamento FECAP - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ce568d5f-874b-498b-b29a-44900cdc477c', '9a94efe5-5518-5d44-bea6-e7536b70f710', 3, 'Adesão ao Programa Parcelamento FECAP - Atendimento: Setor responsável: Financeiro. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Mestrado.'),
  ('a7ddd483-0109-4b7d-9722-816557200e8d', 'c61d5034-e6d1-5577-863a-08ee1cdfa585', 1, 'Antecipação de Parcelas: Quer antecipar algumas parcelas do seu contrato? Basta nos procurar em um dos canais de atendimento do ASA. Estamos à disposição para te auxiliar!'),
  ('e486656b-0ef5-4afa-a311-4ab4e1f2fa9c', 'c61d5034-e6d1-5577-863a-08ee1cdfa585', 2, 'Antecipação de Parcelas - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('73a0533f-71e9-4bab-ada7-e94b7e02830c', 'c61d5034-e6d1-5577-863a-08ee1cdfa585', 3, 'Antecipação de Parcelas - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('0aab701a-be59-448a-bc99-7f0be56ac6de', '445b2968-b6d1-5165-893d-6fc708071a55', 1, 'Boleto não registrado: Tentou pagar o boleto e não conseguiu? Não se preocupe, nós resolvemos para você! Acesse o seu Portal do Aluno > Menu > Secretaria/Requerimentos > Boleto não Registrado e informe o mês do boleto em questão.'),
  ('4b87d36b-97e5-465d-9913-44a781a8087f', '445b2968-b6d1-5165-893d-6fc708071a55', 2, 'Boleto não registrado - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('bf29d41d-0d53-4d24-aab8-9c265ea60666', '445b2968-b6d1-5165-893d-6fc708071a55', 3, 'Boleto não registrado - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('62610c1c-2ff9-4c68-a9cd-034abf10e63a', 'acd5008f-0263-570b-b486-a0b63551492d', 1, 'Cadastro das parcelas de DP/Adaptação: Se a sua carga horária ultrapassou 400h ou você está cursando disciplinas em regime de DP ou adaptação, e seus boletos não foram gerados automaticamente, você pode solicitar o lançamento das parcelas pelo portal Requerimento/ Cadastro das parcelas de DP/Adaptação. É muito rápido e simples. Caso prefira, entre em contato com os canais de atendimento do ASA. Estamos prontos para te ajudar!'),
  ('5352c6db-39a1-43e5-9034-ef768da83824', 'acd5008f-0263-570b-b486-a0b63551492d', 2, 'Cadastro das parcelas de DP/Adaptação - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('f9ea4824-485e-461e-99b7-e045c4433112', 'acd5008f-0263-570b-b486-a0b63551492d', 3, 'Cadastro das parcelas de DP/Adaptação - Atendimento: Setor responsável: Área do Sucesso Alvarista. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('3db67b1f-1ea5-4579-8ca8-a6b5ffc8a4eb', '3e6b4fff-2353-54d6-924d-f7de7b9a04b7', 1, 'Cursos de Extensão | Abono de valores em novo curso: Fez inscrição em algum curso de extensão e, infelizmente, ele foi cancelado? Temos uma ótima notícia: você poderá usar o valor pago em outro curso! Mas caso não queira, você poderá solicitar a restituição, sem problema algum. Basta abrir uma solicitação pelo portal Requerimento/Abatimento de valores ou, se preferir, pode nos procurar através dos nossos canais de atendimento. Estamos disponíveis para te auxiliar.'),
  ('6f8ec5ae-0b49-4703-98f1-b4c0a4a33bec', '3e6b4fff-2353-54d6-924d-f7de7b9a04b7', 2, 'Cursos de Extensão | Abono de valores em novo curso - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('cb126be7-24e8-4cf7-a65e-8b3e77ae7729', '3e6b4fff-2353-54d6-924d-f7de7b9a04b7', 3, 'Cursos de Extensão | Abono de valores em novo curso - Atendimento: Setor responsável: Extensão. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado / Pós-Graduação.'),
  ('58f89bb0-dad5-4b98-bc72-77092fc799f9', '29604265-70ff-526b-ada2-2ca8d2772055', 1, 'Emissão Mensal de Boletos: Quer tirar a segunda via do seu boleto para pagamento da mensalidade? O envio acontece todo mês no seu e-mail cadastrado no ato da matrícula, mas você pode retirar a segunda via pelo caminho: Portal do aluno> Financeiro.'),
  ('8242f98c-30d3-4342-a3c5-5d05119330e8', '29604265-70ff-526b-ada2-2ca8d2772055', 2, 'Emissão Mensal de Boletos - Condições: A emissão dos boletos é realizada mensalmente na última semana do mês com vencimento para o dia 07 do mês subsequente'),
  ('1d0bfadc-060f-4a8c-b96c-86b52910e716', '29604265-70ff-526b-ada2-2ca8d2772055', 3, 'Emissão Mensal de Boletos - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('f9466a48-3f6e-47b5-befe-82b77dc9996a', '936d5ee4-cdf2-538d-b4c7-75aa094ae093', 1, 'FIES – Restituições/Reembolsos: Não sabe como solicitar a sua restituição do programa FIES? Veja como é simples: acesse o portal Requerimento/ FIES – Restituições/Reembolsos e preencha a solicitação. Em caso de dúvidas, nos procure em nossos canais de Atendimento do ASA. Será um prazer te auxiliar!'),
  ('d059f448-b8e2-493e-bd82-bf810aac3af0', '936d5ee4-cdf2-538d-b4c7-75aa094ae093', 2, 'FIES – Restituições/Reembolsos - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('0924029f-6ff1-4211-bada-3f31735256be', '936d5ee4-cdf2-538d-b4c7-75aa094ae093', 3, 'FIES – Restituições/Reembolsos - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Graduação / Mestrado.'),
  ('3e3f2eec-acaa-428e-a521-89c39180e02f', '698903db-74bd-5386-bc11-c5845358b37a', 1, 'Negociação On-line: Sabia que na FECAP é possível negociar e quitar suas dívidas de maneira 100% on-line? Faça isso diretamente pelo Portal do Aluno > Menu > Negociações On-line. Confira também o tutorial “Como fazer uma Negociação On-line?”: https://www.youtube.com/watch?v=jvDe9O4HzPk'),
  ('6f491418-72ff-4b15-95c7-234c3a3e9126', '698903db-74bd-5386-bc11-c5845358b37a', 2, 'Negociação On-line - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('710139e6-72cd-4e8e-a5a4-18de125d46bd', '698903db-74bd-5386-bc11-c5845358b37a', 3, 'Negociação On-line - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8538414f-e2be-405d-a2b8-689006734d08', 'ebf50f6b-e3d3-54c8-978c-7d90598aa405', 1, 'Pagamento Recorrente: Tenha mais comodidade no pagamento das suas mensalidades, com cobranças automáticas feitas mensalmente. Faça agora a ativação da nova modalidade de pagamento recorrente por meio do seu Portal do Aluno! Para habilitar essa modalidade, é fácil: •Entre no seu Portal do Aluno; •Na página inicial, acesse o menu “Financeiro”; •Em “Financeiro”, selecione “Cartão”; •Informe os dados do seu cartão e a quantidade de parcelas desejadas; •Logo abaixo, marque a opção “Pagamento recorrente”; •Aparecerá uma mensagem especificando a ação. Clique em “Sim”; •Feito isso, clique em “Pagar” e em seguida em “Confirmar”. •Pronto, pagamento recorrente habilitado! Obs: a novidade não está disponível para estudantes oriundos das Plataformas “Quero Pago” e “NOVO FIES”. Dúvidas? Entre em contato conosco por meio dos canais de atendimento.'),
  ('28051839-19d9-47e4-9889-ab0ed1f1a6c9', 'ebf50f6b-e3d3-54c8-978c-7d90598aa405', 2, 'Pagamento Recorrente - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('91355a04-7408-45c1-ad7d-b08a31c9f67e', 'ebf50f6b-e3d3-54c8-978c-7d90598aa405', 3, 'Pagamento Recorrente - Atendimento: Setor responsável: Financeiro. Horário de atendimento: Segunda a sexta-feira, das 8h às 18h. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('2e9896a6-d50c-48fa-b576-1e065491c07a', 'f25e00d4-94f6-505b-9fcf-80d248f3911c', 1, 'Pagamento das adaptações: Precisa realizar alguma adaptação fora da grade curricular? Confira como funciona o processo: Solicite ao Colégio a relação da(s) disciplina(s) adaptativa. Em até 7 dias úteis, o boleto de pagamento das parcelas ficará disponível no seu Portal do Aluno > Financeiro. Caso tenha alguma dúvida, entre em contato com o Colégio pelos canais de atendimento.'),
  ('41e5c2d9-237e-4741-bacb-84cf168a4817', 'f25e00d4-94f6-505b-9fcf-80d248f3911c', 2, 'Pagamento das adaptações - Condições: Ter registro de matricula; Possuir disciplinas de adaptação fora da grade curricular padrão'),
  ('dbfa21e1-a46f-4b17-ba83-868ba6e5cc1d', 'f25e00d4-94f6-505b-9fcf-80d248f3911c', 3, 'Pagamento das adaptações - Atendimento: Setor responsável: Financeiro. Local: Área de Sucesso Alvarista. Horário de atendimento: Segunda a Sexta das 9h00 às 21h00 | Sábado das 09h00 às 12h00. Nível de ensino: Colégio.'),
  ('8ee3a5ad-b871-484c-9637-2e7e8774a2ed', 'e04a55a7-87df-5702-b097-f85939284e27', 1, 'Pagamento do valor Anual: Deseja realizar o pagamento anual do seu curso? Para isso, basta entrar em contato com o setor financeiro por e-mail: tesouraria@fecap.br ou Whatsapp: (11) 94018-5617. O setor fará as orientações necessárias e emitirá o boleto anual para pagamento.'),
  ('7ef14bd0-2c51-4f07-a98d-b030f3e42fde', 'e04a55a7-87df-5702-b097-f85939284e27', 2, 'Pagamento do valor Anual - Condições: Ter registro de matrícula; Não possuir nenhum débito financeiro pendente'),
  ('56cbad40-248a-42fa-804f-f69e797d1fdd', 'e04a55a7-87df-5702-b097-f85939284e27', 3, 'Pagamento do valor Anual - Atendimento: Setor responsável: Coordenação do Colégio. Local: Coordenação do Colégio. Horário de atendimento: Segunda a sexta-feira, das 09:00 às 18:30. Nível de ensino: Colégio.'),
  ('c005cfe0-b6cb-4fb1-9073-e52e2bc8369f', '4384a068-c474-5f33-ac03-c0f58cdfcb52', 1, 'Pagamento à Vista da Semestralidade: Deseja realizar o pagamento antecipado do semestre? Faça a solicitação pelo portal Requerimento/ Pagamento à Vista da Semestralidade. Em caso de dúvidas, procure por um dos atendentes ASA em nossos canais de atendimento. Estamos prontos para te ajudar!'),
  ('52709559-1aa7-4674-8cc7-56b94a8443a4', '4384a068-c474-5f33-ac03-c0f58cdfcb52', 2, 'Pagamento à Vista da Semestralidade - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('099d43a9-0301-41b3-a427-f042f1ef1755', '4384a068-c474-5f33-ac03-c0f58cdfcb52', 3, 'Pagamento à Vista da Semestralidade - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Colégio / Graduação / Mestrado.'),
  ('9be7a1ba-c73f-46e0-bbde-d014554bbbb8', '8a79a569-bc70-5e4e-b587-81bd8d1c86b4', 1, 'Pagamento à Vista do Curso: Deseja realizar o pagamento à vista do curso referente ao Contrato de Prestação de Serviços Educacionais? Basta solicitar essa condição pelo Portal do Aluno > Menu > Secretaria/Requerimentos > Pagamento à Vista da Curso.'),
  ('6471201c-b53b-484a-a1ee-43e7e1c01cd4', '8a79a569-bc70-5e4e-b587-81bd8d1c86b4', 2, 'Pagamento à Vista do Curso - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('dd999f5d-268e-416e-aec5-aadc0d333aea', '8a79a569-bc70-5e4e-b587-81bd8d1c86b4', 3, 'Pagamento à Vista do Curso - Atendimento: Setor responsável: Financeiro. Local: ASA - Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Pós-Graduação.'),
  ('7bdad0be-979f-4ff4-9ae2-4c5d36d97f0d', '1463f5a3-b5e0-5954-9672-87f53ed21a7b', 1, 'Pagamentos de Mensalidade: Todos os boletos de serviços (mensalidades, dependências, adaptações, entre outros) são emitidos pelo seu Portal do Aluno. Assim que realizar seu login, vá até a aba Financeiro e escolha a opção da parcela desejada e a forma de pagamento (boleto, cartão ou PIX). Prontinho! Em caso de dúvidas, entre em contato por meio dos nossos canais de atendimento.'),
  ('cf5a9aba-681f-4da4-a3c5-b65aa72c1e76', '1463f5a3-b5e0-5954-9672-87f53ed21a7b', 2, 'Pagamentos de Mensalidade - Condições: O estudante pode estar regularmente matriculado ou não; O estudante precisa do acesso (login e senha) ao portal; Caso o estudante ou responsável financeiro não tenha mais acesso ao portal, deverá recuperar a senha ou solicitar o pagamento nos demais canais de atendimento disponíveis; Por questões de segurança, as informações financeiras serão fornecidas somente ao estudante e seu responsável financeiro'),
  ('8bccbda8-a870-4024-a2aa-706894c244b8', '1463f5a3-b5e0-5954-9672-87f53ed21a7b', 3, 'Pagamentos de Mensalidade - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('ac8922c6-8c4f-4120-a061-7fd96e9e17bf', 'b730daf4-6b73-51ff-b695-dae3dd3abea5', 1, 'Renovação do Programa Parcelamento FECAP: Gostaria de renovar sua inscrição no Programa de Financiamento da Fecap (FIFE)? Faça sua solicitação pelo Portal do Aluno > Menu > Secretaria/Requerimentos > Renovação do Programa Parcelamento FECAP.'),
  ('df33e4e3-192b-4bf2-983a-fe896a4a5064', 'b730daf4-6b73-51ff-b695-dae3dd3abea5', 2, 'Renovação do Programa Parcelamento FECAP - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('e7821ac5-6dce-4b46-bbe3-3fcf69bec3c3', 'b730daf4-6b73-51ff-b695-dae3dd3abea5', 3, 'Renovação do Programa Parcelamento FECAP - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Mestrado.'),
  ('2aa7678b-220a-4bf6-98b8-47aebd8399e0', '5ed7261a-7e85-55c3-9233-a9e04ce42fb2', 1, 'Restituições: Realizou algum pagamento indevido ou duplicado e precisa da restituição? Fique tranquilo(a), basta abrir uma solicitação pelo portal Requerimento/Restituição ou, se preferir, pode nos procurar por meio dos canais do ASA! Estamos à disposição para te ajudar! Lembre-se: envie-nos os dados bancários e o comprovante de pagamento para agilizar o processo de restituição.'),
  ('86f08a0c-9231-4faf-9411-0a71f2fce652', '5ed7261a-7e85-55c3-9233-a9e04ce42fb2', 2, 'Restituições - Condições: Não há condições específicas; a informação vale para todos os estudantes.'),
  ('ba72065c-4b78-4174-98f8-c795a41e017a', '5ed7261a-7e85-55c3-9233-a9e04ce42fb2', 3, 'Restituições - Atendimento: Setor responsável: Financeiro. Local: Área do Sucesso Alvarista. Horário de atendimento: Segunda a sexta, das 7h00 às 21h00 | Sábado, das 09h00 às 12h30. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('1acfa6df-a7df-462c-b88b-cbca6d93be5e', '1fe20a5f-656e-5e65-8a46-89224f21c9de', 1, 'Solicitação de Passe Escolar EMTU: Se você está regularmente matriculado na FECAP e está fora da Cidade de São Paulo, saiba que você pode solicitar o benefício da meia passagem. Para fazer sua solicitação é fácil! 1 – Primeiro faça seu pré-cadastro pelo site da EMTU. O pagamento da taxa é feito no próprio site. 2 – Depois acesse o Portal do aluno > Menu > Requerimentos > e solicite o envio dos seus dados para a EMTU.'),
  ('5741bd3d-378d-42cc-b3f3-5c88d0468a30', '1fe20a5f-656e-5e65-8a46-89224f21c9de', 2, 'Solicitação de Passe Escolar EMTU - Condições: Ter situação de matrícula "Cursando"; Ter entregue os documentos do estudante: RG, CPF e comprovante de residência atualizado'),
  ('4e69ffbd-79dd-4e92-8d64-485672d19bec', '1fe20a5f-656e-5e65-8a46-89224f21c9de', 3, 'Solicitação de Passe Escolar EMTU - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.'),
  ('8b9aca71-bdf9-49ed-9565-fc19b444593c', '9daef918-ccf5-5111-8f9c-24b5ff127d8f', 1, 'Solicitação de Passe Escolar SPTrans: Se você está regularmente matriculado na FECAP e utiliza a SPTrans, informamos que o seu cadastro será atualizado automaticamente. Se você ou a SPTrans não identificaram o envio dos dados pela FECAP, acesse o Portal do aluno > Menu > Requerimentos > e solicite o comprovante de envio dos seus dados à SPTrans. Caso ainda não tenha ativado seu benefício, confira o passo a passo: 1. Acesse sua situação cadastral no site da SPTrans; 2. Pague a taxa solicitada e aguarde a liberação do benefício, que deverá ocorrer automaticamente em 72 horas. Mas, fique atento(a): – Se você ingressou na FECAP neste semestre, o prazo para envio de seus dados para a SPTrans é de 15 dias após a data de conclusão da matrícula;'),
  ('78585ee6-c4aa-4828-be5f-0f13e6f21041', '9daef918-ccf5-5111-8f9c-24b5ff127d8f', 2, 'Solicitação de Passe Escolar SPTrans: – Se você está pedindo o Bilhete Único pela primeira vez, assim que você pagar a taxa e receber o seu Bilhete, é necessário fazer o desbloqueio na plataforma. Depois desse passo importante, em 72 horas o benefício será liberado automaticamente. ATENÇÃO: Só abra este requerimento caso a SPTrans informe a necessidade de um comprovante de que os seus dados foram devidamente cadastrados ou se você ou a SPTrans não identificaram o envio dos dados pela FECAP.'),
  ('22a912ae-18d6-4366-88e5-b0c840e86fe1', '9daef918-ccf5-5111-8f9c-24b5ff127d8f', 3, 'Solicitação de Passe Escolar SPTrans - Condições: Ter situação de matrícula "Cursando"; Ter entregue os documentos do estudante: RG, CPF e comprovante de residência atualizado; O estudante deverá possuir um pré-cadastro no site da SPTrans antes de realizar a solicitação'),
  ('30ece064-75f9-4127-bb19-c8f3924b382e', '9daef918-ccf5-5111-8f9c-24b5ff127d8f', 4, 'Solicitação de Passe Escolar SPTrans - Atendimento: Setor responsável: Secretaria Acadêmica. Local: Área do Sucesso Alvarista. Horário de atendimento: De segunda a sexta-feira, das 08h00 às 21h30 e aos sábados, das 09h00 às 13h00. Nível de ensino: Sem restrição de nível de ensino; vale para todos os níveis.');
